function plannerRoot() {
  return path.join(supportRoot(), "Planner");
}

function plannerDailyRoot() {
  return path.join(plannerRoot(), "Daily");
}

function plannerBacklogPath() {
  return path.join(plannerRoot(), "Backlog.md");
}

function plannerTemplatesRoot() {
  return path.join(plannerRoot(), "Templates");
}

function plannerRecoveryRoot() {
  return path.join(plannerRoot(), "Recovery");
}

function plannerDefaultTemplatePath() {
  return path.join(plannerTemplatesRoot(), "default.md");
}

function plannerDesignPath() {
  return path.join(plannerRoot(), "DESIGN.md");
}

function plannerCategoriesPath() {
  return path.join(plannerRoot(), "Categories.json");
}

function plannerCategoryID(name: string) {
  return cleanDailyText(name)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    || `category-${Date.now()}`;
}

function defaultPlannerCategories(): PlannerCategory[] {
  const now = new Date().toISOString();
  return defaultPlannerCategoryNames.map((name, index) => ({
    id: plannerCategoryID(name),
    name,
    icon: name === "Work" ? "briefcase" : name === "Business" ? "store" : name === "Home" ? "house" : "home",
    color: name === "Work" ? "#8BB7FF" : name === "Business" ? "#7ED6A5" : name === "Home" ? "#F2B36D" : "#BFA2FF",
    createdAt: now,
    updatedAt: now,
    order: index
  }));
}

function normalizePlannerCategoryName(value: unknown) {
  return cleanDailyText(value).replace(/\s+/g, " ");
}

function normalizePlannerCategoryRecord(value: unknown, fallbackOrder = 0): PlannerCategory | null {
  const raw = dailyItemJSON(value);
  const name = normalizePlannerCategoryName(raw.name ?? raw.title ?? raw.id);
  if (!name) return null;
  const id = cleanDailyText(raw.id) || plannerCategoryID(name);
  const now = new Date().toISOString();
  return {
    id,
    name,
    color: cleanDailyText(raw.color) || undefined,
    icon: cleanDailyText(raw.icon) || undefined,
    createdAt: cleanDailyText(raw.createdAt) || now,
    updatedAt: cleanDailyText(raw.updatedAt) || now,
    order: Number.isFinite(Number(raw.order)) ? Number(raw.order) : fallbackOrder,
    hidden: raw.hidden === true
  };
}

function normalizePlannerCategories(value: unknown): PlannerCategory[] {
  const rawCategories = (value as { categories?: unknown[] } | null)?.categories;
  const entries = Array.isArray(value)
    ? value
    : Array.isArray(rawCategories)
      ? rawCategories
      : [];
  const seen = new Set<string>();
  const categories: PlannerCategory[] = [];
  for (const [index, entry] of entries.entries()) {
    const category = normalizePlannerCategoryRecord(entry, index);
    if (!category) continue;
    const key = category.name.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    categories.push(category);
  }
  for (const category of defaultPlannerCategories()) {
    const key = category.name.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    categories.push({ ...category, order: categories.length });
  }
  return categories.sort((left, right) => left.order - right.order || left.name.localeCompare(right.name));
}

function loadPlannerCategories(includeHidden = false): PlannerCategory[] {
  ensurePlannerScaffold();
  const filePath = plannerCategoriesPath();
  const loaded = fs.existsSync(filePath)
    ? readJSON<{ categories?: unknown[] }>(filePath, { categories: [] })
    : { categories: defaultPlannerCategories() };
  const categories = normalizePlannerCategories(loaded);
  if (!fs.existsSync(filePath)) writeJSON(filePath, { version: 1, categories });
  return includeHidden ? categories : categories.filter((category) => category.hidden !== true);
}

function savePlannerCategories(categories: PlannerCategory[], options: { origin?: "local" | "sync" } = {}) {
  const previous = loadPlannerCategories(true);
  const normalized = normalizePlannerCategories(categories);
  if (options.origin !== "sync") {
    const nextIDs = new Set(normalized.map((category) => category.id));
    for (const category of previous) {
      if (!nextIDs.has(category.id)) recordMacSyncTombstone("plannerCategory", category.id);
    }
  }
  writeJSON(plannerCategoriesPath(), { version: 1, categories: normalized });
  emitPlannerCategoriesChanged();
  return normalized.filter((category) => category.hidden !== true);
}

function upsertPlannerCategory(input: Partial<PlannerCategory> & { name?: string }) {
  const name = normalizePlannerCategoryName(input.name);
  if (!name) throw new Error("Category name is required.");
  const categories = loadPlannerCategories(true);
  const now = new Date().toISOString();
  const inputID = cleanDailyText(input.id);
  const existingByID = inputID
    ? categories.find((category) => category.id.toLowerCase() === inputID.toLowerCase())
    : undefined;
  const existingByName = categories.find((category) => category.name.toLowerCase() === name.toLowerCase());
  const existing = existingByID ?? existingByName;
  if (existing && existing.name !== name) {
    renamePlannerCategoryAreaReferences(existing.name, name);
  }
  const next: PlannerCategory = {
    id: existing?.id ?? (cleanDailyText(input.id) || plannerCategoryID(name)),
    name,
    color: normalizePlannerCategoryName(input.color) || existing?.color,
    icon: normalizePlannerCategoryName(input.icon) || existing?.icon,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    order: Number.isFinite(Number(input.order)) ? Number(input.order) : (existing?.order ?? categories.length),
    hidden: input.hidden === true ? true : input.hidden === false ? false : existing?.hidden
  };
  const updated = existing
    ? categories.map((category) => category.id === existing.id ? next : category)
    : [...categories, next];
  return { category: next, categories: savePlannerCategories(updated) };
}

function deletePlannerCategory(categoryID: string) {
  const key = cleanDailyText(categoryID).toLowerCase();
  if (!key) throw new Error("Category id is required.");
  const categories = loadPlannerCategories(true);
  const existing = categories.find((category) => category.id.toLowerCase() === key || category.name.toLowerCase() === key);
  if (!existing) return loadPlannerCategories();
  if (defaultPlannerCategoryNames.some((name) => name.toLowerCase() === existing.name.toLowerCase())) {
    const hidden = categories.map((category) => category.id === existing.id ? { ...category, hidden: true, updatedAt: new Date().toISOString() } : category);
    return savePlannerCategories(hidden);
  }
  return savePlannerCategories(categories.filter((category) => category.id !== existing.id));
}

function plannerTemplateFingerprint(template: string) {
  return String(template ?? "").replace(/\r\n/g, "\n").trim();
}

function shouldReplacePlannerDefaultTemplate(template: string) {
  const fingerprint = plannerTemplateFingerprint(template);
  if (!fingerprint) return true;
  return legacyPlannerTemplates.some((legacy) => plannerTemplateFingerprint(legacy) === fingerprint);
}

function pad2(value: number) {
  return String(value).padStart(2, "0");
}

function plannerDayID(date = new Date()) {
  return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
}

function normalizePlannerDayID(value?: string | null) {
  const raw = String(value ?? "").trim();
  if (!raw) return plannerDayID();
  const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return plannerDayID();
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const parsed = new Date(year, month - 1, day);
  if (
    parsed.getFullYear() !== year
    || parsed.getMonth() !== month - 1
    || parsed.getDate() !== day
  ) {
    return plannerDayID();
  }
  return raw;
}

function normalizeDailyItemDayID(value?: string | null, fallback?: string | null) {
  const raw = String(value ?? fallback ?? "").trim();
  if (raw.toLowerCase() === plannerBacklogID) return plannerBacklogID;
  return normalizePlannerDayID(raw);
}

// Strict day resolution for tool/voice WRITE paths. Empty input keeps the
// "today" default, but a non-empty value that cannot be resolved to a real day
// throws instead of silently coercing to today (which would file the task on the
// wrong day while telling the model it succeeded). Understands "backlog", strict
// ISO dates, and natural-language ("tomorrow", "Monday", "June 20").
function resolvePlannerDayIDForWrite(value?: string | null, fallback?: string | null): string {
  const raw = String(value ?? "").trim();
  if (!raw) {
    if (fallback) return normalizeDailyItemDayID(fallback);
    return plannerDayID();
  }
  if (raw.toLowerCase() === plannerBacklogID) return plannerBacklogID;
  const iso = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (iso) {
    const normalized = normalizePlannerDayID(raw);
    // normalizePlannerDayID returns today for calendar-invalid ISO strings; detect that.
    if (normalized !== raw) {
      throw new Error(`"${raw}" is not a valid date. Use YYYY-MM-DD.`);
    }
    return normalized;
  }
  const parsed = parsePlannerDayIDFromPrompt(raw);
  if (parsed) return parsed;
  throw new Error(`I couldn't understand the date "${raw}". Use YYYY-MM-DD, "today", "tomorrow", a weekday, or "backlog".`);
}

function plannerDateFromDayID(dayID: string) {
  const normalized = normalizePlannerDayID(dayID);
  const [year, month, day] = normalized.split("-").map((part) => Number(part));
  return new Date(year, month - 1, day, 12, 0, 0, 0);
}

function plannerDayOffset(dayID: string, offset: number) {
  const date = plannerDateFromDayID(dayID);
  date.setDate(date.getDate() + offset);
  return plannerDayID(date);
}

function plannerDayPath(dayID: string) {
  const normalized = normalizePlannerDayID(dayID);
  const [year, month] = normalized.split("-");
  return path.join(plannerDailyRoot(), year, month, `${normalized}.md`);
}

function ensurePlannerScaffold() {
  fs.mkdirSync(plannerDailyRoot(), { recursive: true });
  fs.mkdirSync(plannerTemplatesRoot(), { recursive: true });
  fs.mkdirSync(plannerRecoveryRoot(), { recursive: true });
  if (!fs.existsSync(plannerBacklogPath())) {
    fs.writeFileSync(plannerBacklogPath(), defaultPlannerBacklog, "utf8");
  }
  const templatePath = plannerDefaultTemplatePath();
  if (!fs.existsSync(templatePath)) {
    fs.writeFileSync(templatePath, defaultPlannerTemplate, "utf8");
  } else {
    const savedTemplate = fs.readFileSync(templatePath, "utf8").replace(/\r\n/g, "\n");
    if (shouldReplacePlannerDefaultTemplate(savedTemplate)) {
      fs.writeFileSync(templatePath, defaultPlannerTemplate, "utf8");
    }
  }
  if (!fs.existsSync(plannerDesignPath())) {
    fs.writeFileSync(plannerDesignPath(), defaultPlannerDesign, "utf8");
  }
}

function renderPlannerTemplate(template: string, dayID: string) {
  const date = plannerDateFromDayID(dayID);
  const displayDate = date.toLocaleDateString(undefined, {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric"
  });
  const weekday = date.toLocaleDateString(undefined, { weekday: "long" });
  const month = date.toLocaleDateString(undefined, { month: "long" });
  const replacements: Record<string, string> = {
    date: displayDate,
    isoDate: dayID,
    weekday,
    month,
    yesterday: plannerDayOffset(dayID, -1),
    tomorrow: plannerDayOffset(dayID, 1)
  };
  return template.replace(/\{\{\s*(date|isoDate|weekday|month|yesterday|tomorrow)\s*\}\}/g, (_match, key: string) => replacements[key] ?? "");
}

function plannerDayTitle(dayID: string) {
  const today = plannerDayID();
  if (dayID === today) return "Today";
  const date = plannerDateFromDayID(dayID);
  return date.toLocaleDateString(undefined, {
    weekday: "short",
    month: "short",
    day: "numeric",
    year: date.getFullYear() === new Date().getFullYear() ? undefined : "numeric"
  });
}

function plannerDaySummary(dayID: string, activeDayID?: string): PlannerDaySummary {
  const filePath = plannerDayPath(dayID);
  const stat = fs.existsSync(filePath) ? fs.statSync(filePath) : undefined;
  return {
    id: dayID,
    title: plannerDayTitle(dayID),
    subtitle: dayID,
    path: filePath,
    updatedAt: stat?.mtimeMs,
    active: activeDayID ? dayID === activeDayID : dayID === plannerDayID()
  };
}

function plannerBacklogSummary(active = false): PlannerDaySummary {
  const filePath = plannerBacklogPath();
  const stat = fs.existsSync(filePath) ? fs.statSync(filePath) : undefined;
  return {
    id: plannerBacklogID,
    title: "Backlog",
    subtitle: "No date yet",
    path: filePath,
    updatedAt: stat?.mtimeMs,
    active
  };
}

function loadPlannerDay(dayID?: string): PlannerDayDetail {
  ensurePlannerScaffold();
  const normalizedDayID = normalizePlannerDayID(dayID);
  const filePath = plannerDayPath(normalizedDayID);
  if (!fs.existsSync(filePath)) {
    const template = fs.existsSync(plannerDefaultTemplatePath())
      ? fs.readFileSync(plannerDefaultTemplatePath(), "utf8").replace(/\r\n/g, "\n")
      : defaultPlannerTemplate;
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, renderPlannerTemplate(template, normalizedDayID), "utf8");
  }
  const summary = plannerDaySummary(normalizedDayID, normalizedDayID);
  return {
    ...summary,
    markdown: fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n")
  };
}

function loadPlannerBacklog(): PlannerBacklogDetail {
  ensurePlannerScaffold();
  const filePath = plannerBacklogPath();
  if (!fs.existsSync(filePath)) {
    fs.writeFileSync(filePath, defaultPlannerBacklog, "utf8");
  }
  return {
    ...plannerBacklogSummary(true),
    markdown: fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n")
  };
}

function listPlannerDays(limit = 90, activeDayID = plannerDayID()): PlannerDaySummary[] {
  ensurePlannerScaffold();
  const ids = new Set<string>([activeDayID, plannerDayID()]);
  const dailyRoot = plannerDailyRoot();
  if (fs.existsSync(dailyRoot)) {
    for (const year of fs.readdirSync(dailyRoot)) {
      const yearRoot = path.join(dailyRoot, year);
      if (!fs.statSync(yearRoot).isDirectory()) continue;
      for (const month of fs.readdirSync(yearRoot)) {
        const monthRoot = path.join(yearRoot, month);
        if (!fs.statSync(monthRoot).isDirectory()) continue;
        for (const entry of fs.readdirSync(monthRoot)) {
          const match = entry.match(/^(\d{4}-\d{2}-\d{2})\.md$/);
          if (match) ids.add(match[1]);
        }
      }
    }
  }
  return [...ids]
    .sort((left, right) => right.localeCompare(left))
    .slice(0, Math.max(1, limit))
    .map((id) => plannerDaySummary(id, activeDayID));
}

function snapshotPlannerDay(dayID: string, previousMarkdown: string) {
  if (!previousMarkdown.trim()) return;
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const filePath = path.join(plannerRecoveryRoot(), dayID, `${stamp}.md`);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, previousMarkdown, "utf8");
  prunePlannerRecoveryBucket(dayID);
}

function prunePlannerRecoveryBucket(dayID: string) {
  const bucketPath = path.join(plannerRecoveryRoot(), dayID);
  if (!fs.existsSync(bucketPath)) return;
  const now = Date.now();
  const entries = fs.readdirSync(bucketPath)
    .filter((fileName) => fileName.endsWith(".md"))
    .map((fileName) => {
      const filePath = path.join(bucketPath, fileName);
      const stat = fs.statSync(filePath);
      return { filePath, mtimeMs: stat.mtimeMs };
    })
    .sort((left, right) => right.mtimeMs - left.mtimeMs);
  for (const [index, entry] of entries.entries()) {
    const isRecentEnough = now - entry.mtimeMs <= plannerRecoveryMaxAgeMs;
    const keep = index < plannerRecoveryMaxSnapshotsPerBucket
      && (isRecentEnough || index < plannerRecoveryMinSnapshotsPerBucket);
    if (!keep) fs.rmSync(entry.filePath, { force: true });
  }
  try {
    if (fs.readdirSync(bucketPath).length === 0) fs.rmdirSync(bucketPath);
  } catch {
    // Best effort cleanup only.
  }
}

function prunePlannerRecoverySnapshots() {
  const root = plannerRecoveryRoot();
  if (!fs.existsSync(root)) return;
  for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
    if (entry.isDirectory()) prunePlannerRecoveryBucket(entry.name);
  }
}

type PlannerSaveOptions = {
  origin?: "local" | "sync" | "migration";
  updatedAt?: number;
};

function savePlannerDay(dayID: string | undefined, markdown: string, options: PlannerSaveOptions = {}): PlannerDayDetail {
  ensurePlannerScaffold();
  const normalizedDayID = normalizePlannerDayID(dayID);
  const filePath = plannerDayPath(normalizedDayID);
  const previousMarkdown = fs.existsSync(filePath)
    ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n")
    : "";
  const stamp = options.updatedAt ?? macSyncFileUpdatedAt(filePath) ?? Date.now();
  const normalizedPrevious = macSyncNormalizePlannerMarkdown(normalizedDayID, previousMarkdown, stamp);
  const nextMarkdown = macSyncNormalizePlannerMarkdown(normalizedDayID, String(markdown ?? "").replace(/\r\n/g, "\n"), options.updatedAt ?? Date.now());
  if (options.origin !== "sync" && options.origin !== "migration") {
    macSyncRecordPlannerItemDeletes(normalizedDayID, normalizedPrevious, nextMarkdown);
  }
  if (previousMarkdown !== nextMarkdown) snapshotPlannerDay(normalizedDayID, previousMarkdown);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, nextMarkdown, "utf8");
  return loadPlannerDay(normalizedDayID);
}

function savePlannerBacklog(markdown: string, options: PlannerSaveOptions = {}): PlannerBacklogDetail {
  ensurePlannerScaffold();
  const filePath = plannerBacklogPath();
  const previousMarkdown = fs.existsSync(filePath)
    ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n")
    : "";
  const stamp = options.updatedAt ?? macSyncFileUpdatedAt(filePath) ?? Date.now();
  const normalizedPrevious = macSyncNormalizePlannerMarkdown(plannerBacklogID, previousMarkdown, stamp);
  const nextMarkdown = macSyncNormalizePlannerMarkdown(plannerBacklogID, String(markdown ?? "").replace(/\r\n/g, "\n"), options.updatedAt ?? Date.now());
  if (options.origin !== "sync" && options.origin !== "migration") {
    macSyncRecordPlannerItemDeletes(plannerBacklogID, normalizedPrevious, nextMarkdown);
  }
  if (previousMarkdown !== nextMarkdown) snapshotPlannerDay(plannerBacklogID, previousMarkdown);
  fs.writeFileSync(filePath, nextMarkdown, "utf8");
  return loadPlannerBacklog();
}

function savePlannerDayFromEditor(dayID: string | undefined, markdown: string): PlannerDayDetail {
  const normalizedDayID = normalizePlannerDayID(dayID);
  const previousMarkdown = loadPlannerDay(normalizedDayID).markdown;
  return savePlannerDay(
    normalizedDayID,
    preserveStructuredDailyItemsAfterEditorRoundTrip(normalizedDayID, previousMarkdown, markdown)
  );
}

function savePlannerBacklogFromEditor(markdown: string): PlannerBacklogDetail {
  const previousMarkdown = loadPlannerBacklog().markdown;
  return savePlannerBacklog(
    preserveStructuredDailyItemsAfterEditorRoundTrip(plannerBacklogID, previousMarkdown, markdown)
  );
}

function markdownTaskLike(text: string) {
  return text
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .every((line) => /^[-*]\s+\[[ xX]\]\s+/.test(line) || /^[-*]\s+/.test(line));
}

function plannerSectionFor(mode: "move" | "copy" | "link", text: string) {
  if (mode === "link") return "Linked Notes";
  return markdownTaskLike(text) ? "Tasks" : "Notes";
}

function plannerMetadataComment(request: PlannerScheduleRequest, mode: "move" | "copy" | "link") {
  const metadata: JsonObject = {
    id: randomUUID().toLowerCase(),
    mode,
    createdAt: new Date().toISOString()
  };
  if (request.sourceTarget) metadata.sourceNote = buildNoteURL(request.sourceTarget);
  if (request.sourceDayID) metadata.originalDate = request.sourceDayID;
  return `<!-- oa-planner ${JSON.stringify(metadata)} -->`;
}

function buildNoteURL(target: NoteLinkTarget) {
  const params = new URLSearchParams({
    ownerKind: target.ownerKind,
    ownerId: target.ownerId,
    noteId: target.noteId
  });
  return `oa-note://open?${params.toString()}`;
}

function markdownLinkForTarget(title: string | undefined, target: NoteLinkTarget) {
  const safeTitle = (title?.trim() || "Linked note").replace(/\]/g, "\\]");
  return `[${safeTitle}](${buildNoteURL(target)})`;
}

// Deep link that opens a conversation thread from note markdown (the renderer's
// link interceptor routes it to selectThread, same as notification clicks).
function buildThreadURL(threadID: string) {
  return `oa-thread://open?id=${encodeURIComponent(threadID)}`;
}

function ensurePlannerSection(markdown: string, heading: string) {
  const pattern = new RegExp(`(^|\\n)##\\s+${heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*\\n`, "i");
  if (pattern.test(markdown)) return markdown;
  const suffix = markdown.endsWith("\n") ? "" : "\n";
  return `${markdown}${suffix}\n## ${heading}\n`;
}

function isEmptyPlannerPlaceholderLine(line: string) {
  const trimmed = line.trim();
  return /^[-*]\s*(?:\[[ xX]\]\s*)?$/.test(trimmed)
    || /^(?:&nbsp;|\u00a0|<br\s*\/?>)$/i.test(trimmed);
}

function cleanPlannerSectionBody(body: string) {
  const cleaned = body
    .split("\n")
    .filter((line) => !isEmptyPlannerPlaceholderLine(line))
    .join("\n")
    .replace(/\n{3,}/g, "\n\n");
  return cleaned.trim() ? cleaned.replace(/^\n+/, "\n").replace(/\n+$/, "\n") : "";
}

function cleanPlannerTaskSpacing(markdown: string) {
  let insideTasks = false;
  const lines = String(markdown ?? "").replace(/\r\n/g, "\n").split("\n");
  const cleaned = lines.filter((line) => {
    const sectionHeading = line.match(/^##\s+(.+?)\s*$/);
    if (sectionHeading) insideTasks = cleanDailyText(sectionHeading[1]).toLowerCase() === "tasks";
    return !(insideTasks && isEmptyPlannerPlaceholderLine(line));
  });
  return cleaned.join("\n").replace(/\n{3,}/g, "\n\n");
}

function appendToPlannerSection(markdown: string, heading: string, block: string) {
  const source = ensurePlannerSection(markdown.replace(/\r\n/g, "\n"), heading);
  const headingPattern = new RegExp(`(^|\\n)(##\\s+${heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*\\n)`, "i");
  const match = headingPattern.exec(source);
  if (!match || match.index < 0) return `${source.trimEnd()}\n\n## ${heading}\n${block.trim()}\n`;
  const insertAt = match.index + match[0].length;
  const before = source.slice(0, insertAt);
  const after = source.slice(insertAt);
  const nextHeading = after.search(/\n##\s+/);
  const sectionBody = cleanPlannerSectionBody(nextHeading >= 0 ? after.slice(0, nextHeading) : after);
  const rest = nextHeading >= 0 ? after.slice(nextHeading) : "";
  // Keep one blank line between the new task and the previous one so each task
  // stays a separate item in the editor (otherwise they merge and need manual fixing).
  const spacer = sectionBody.trim() ? (sectionBody.endsWith("\n") ? "\n" : "\n\n") : "";
  return `${before}${sectionBody}${spacer}${block.trim()}\n${rest}`;
}

function appendToPlannerSubsection(markdown: string, heading: string, subheading: string | undefined, block: string) {
  if (!subheading) return appendToPlannerSection(markdown, heading, block);
  const source = ensurePlannerSection(markdown.replace(/\r\n/g, "\n"), heading);
  const headingPattern = new RegExp(`(^|\\n)(##\\s+${heading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*\\n)`, "i");
  const match = headingPattern.exec(source);
  if (!match || match.index < 0) return appendToPlannerSection(source, heading, block);
  const bodyStart = match.index + match[0].length;
  const beforeBody = source.slice(0, bodyStart);
  const afterHeading = source.slice(bodyStart);
  const nextHeading = afterHeading.search(/\n##\s+/);
  const body = nextHeading >= 0 ? afterHeading.slice(0, nextHeading) : afterHeading;
  const rest = nextHeading >= 0 ? afterHeading.slice(nextHeading) : "";
  const escapedSubheading = subheading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const subheadingPattern = new RegExp(`(^|\\n)(###\\s+${escapedSubheading}\\s*\\n)`, "i");
  const subheadingMatch = subheadingPattern.exec(body);
  if (subheadingMatch) {
    const subBodyStart = subheadingMatch.index + subheadingMatch[0].length;
    const beforeSubBody = body.slice(0, subBodyStart);
    const afterSubheading = body.slice(subBodyStart);
    const nextSubheading = afterSubheading.search(/\n###\s+/);
    const subBody = cleanPlannerSectionBody(nextSubheading >= 0 ? afterSubheading.slice(0, nextSubheading) : afterSubheading);
    const afterSubBody = nextSubheading >= 0 ? afterSubheading.slice(nextSubheading) : "";
    // Keep one blank line between the new task and the previous one so each task
    // stays a separate item in the editor (otherwise they merge and need manual fixing).
    const spacer = subBody.trim() ? (subBody.endsWith("\n") ? "\n" : "\n\n") : "";
    return `${beforeBody}${beforeSubBody}${subBody}${spacer}${block.trim()}\n${afterSubBody}${rest}`;
  }
  const sectionBody = cleanPlannerSectionBody(body);
  const spacer = sectionBody.trim() ? (sectionBody.endsWith("\n") ? "\n" : "\n\n") : "";
  return `${beforeBody}${sectionBody}${spacer}### ${subheading}\n${block.trim()}\n${rest}`;
}

// A block runs from its opener to ITS closer — but when the editor stripped the
// closing comment, stop at the next opener (or end of file) instead of lazily
// swallowing the neighbouring task's block (which made unrelated updates delete
// the next task).
const dailyItemBlockPattern = /<!--\s*oa-daily-item\s+({[\s\S]*?})\s*-->(?:(?!<!--\s*\/?oa-daily-item)[\s\S])*?(?:<!--\s*\/oa-daily-item\s*-->|(?=<!--\s*oa-daily-item)|$)/g;

function plannerTaskSubheadingAtOffset(markdown: string, offset: number) {
  const source = String(markdown ?? "").replace(/\r\n/g, "\n");
  const lines = source.split("\n");
  let cursor = 0;
  let insideTasks = false;
  let currentSubheading: string | undefined;
  for (const line of lines) {
    if (cursor >= offset) break;
    const heading = line.match(/^##\s+(.+?)\s*$/);
    if (heading) {
      insideTasks = cleanDailyText(heading[1]).toLowerCase() === "tasks";
      currentSubheading = undefined;
    } else if (insideTasks) {
      const subheading = line.match(/^###\s+(.+?)\s*$/);
      if (subheading) currentSubheading = normalizeDailyArea(subheading[1]) ?? cleanDailyTagLabel(subheading[1]);
    }
    cursor += line.length + 1;
  }
  return insideTasks ? currentSubheading : undefined;
}

function normalizedDailyStatus(value: unknown, checked = false): DailyItemStatus {
  const normalized = String(value ?? "").trim().toLowerCase();
  if (normalized === "doing" || normalized === "in_progress" || normalized === "active") return "doing";
  if (normalized === "done" || normalized === "complete" || normalized === "completed") return "done";
  return checked ? "done" : "todo";
}

function cleanDailyText(value: unknown) {
  return String(value ?? "").replace(/\r\n/g, "\n").trim();
}

function cleanDailyTagLabel(value: unknown) {
  return cleanDailyText(value).replace(/^[@#]\s*/, "").replace(/\s+/g, " ");
}

function normalizeDailySection(value: unknown) {
  const text = cleanDailyTagLabel(value);
  return text || undefined;
}

function normalizeDailyTagLabels(value: unknown): string[] {
  const rawValues = Array.isArray(value)
    ? value
    : typeof value === "string"
      ? value.split(/[,\n]/)
      : [];
  const seen = new Set<string>();
  const tags: string[] = [];
  for (const raw of rawValues) {
    const label = cleanDailyTagLabel(raw);
    if (!label) continue;
    const key = label.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    tags.push(label);
  }
  return tags;
}

function dailyFreeTagKey(value: unknown) {
  return cleanDailyTagLabel(value).toLowerCase().replace(/[^a-z0-9]+/g, "");
}

function dailyItemHasFreeTag(item: Pick<DailyItem, "tags">, tag: string) {
  const wanted = dailyFreeTagKey(tag);
  return Boolean(wanted && (item.tags ?? []).some((candidate) => dailyFreeTagKey(candidate) === wanted));
}

function normalizeDailyArea(value: unknown) {
  const text = cleanDailyText(value).replace(/\s+/g, " ");
  const normalized = text.toLowerCase();
  if (!normalized) return undefined;
  const categories = loadPlannerCategories(true);
  const match = categories.find((category) =>
    category.id.toLowerCase() === normalized
    || category.name.toLowerCase() === normalized
  );
  if (match) return match.name;
  // Fuzzy pass against the user's REAL categories before the fixed aliases:
  // "errand" must resolve to an existing "Errands" category, not flip to the
  // hard-coded Personal bucket. Canonical "work"/"personal" stay exact.
  if (normalized !== "work" && normalized !== "personal") {
    const fuzzy = categories.filter((category) => {
      const name = category.name.toLowerCase();
      return name === `${normalized}s`
        || `${name}s` === normalized
        || ` ${name} `.includes(` ${normalized} `)
        || ` ${normalized} `.includes(` ${name} `);
    });
    if (fuzzy.length === 1) return fuzzy[0].name;
  }
  if (["work", "job", "office", "client"].includes(normalized)) return "Work";
  if (["business", "shop", "store", "company"].includes(normalized)) {
    return categories.find((category) => category.name.toLowerCase() === "business")?.name ?? text;
  }
  if (["home", "house"].includes(normalized)) {
    return categories.find((category) => category.name.toLowerCase() === "home")?.name ?? text;
  }
  if (["personal", "life", "family", "errand", "errands"].includes(normalized)) return "Personal";
  if (normalized === "business") {
    return categories.find((category) => category.name.toLowerCase() === "business")?.name;
  }
  return text;
}

function projectAreaFromScope(input: { projectID?: unknown; folderID?: unknown; scopeTags?: unknown }) {
  const projects = loadProjects().plannerLists;
  const byID = new Map(projects.map((project) => [project.id.toLowerCase(), project]));
  const byTitle = new Map(projects.map((project) => [project.title.toLowerCase(), project]));
  const areaForProject = (project?: ProjectItem) => {
    const visited = new Set<string>();
    let current = project;
    while (current) {
      const area = normalizeDailyArea(current.area);
      if (area) return area;
      const parentKey = cleanDailyText(current.parentID).toLowerCase();
      if (!parentKey || visited.has(parentKey)) return undefined;
      visited.add(parentKey);
      current = byID.get(parentKey);
    }
    return undefined;
  };
  const scopeTagCandidates = Array.isArray(input.scopeTags)
    ? normalizeDailyScopeTags(input.scopeTags)
        .filter((tag) => tag.kind === "project" || tag.kind === "folder")
        .flatMap((tag) => [tag.id ?? "", tag.label])
    : [];
  const candidates = [
    cleanDailyText(input.projectID),
    cleanDailyText(input.folderID),
    ...scopeTagCandidates
  ].map((value) => value.toLowerCase()).filter(Boolean);
  for (const candidate of candidates) {
    const project = byID.get(candidate) ?? byTitle.get(candidate);
    const area = areaForProject(project);
    if (area) return area;
  }
  return undefined;
}

function inferDailyArea(input: { title?: unknown; detailsMarkdown?: unknown; projectID?: unknown; folderID?: unknown; scopeTags?: unknown }) {
  const scopedArea = projectAreaFromScope(input);
  if (scopedArea) return scopedArea;
  const text = [
    input.title,
    input.detailsMarkdown,
    input.projectID,
    input.folderID,
    ...(Array.isArray(input.scopeTags) ? input.scopeTags.map((tag) => JSON.stringify(tag)) : [])
  ].map((value) => cleanDailyText(value)).join(" ").toLowerCase();
  if (!text.trim()) return undefined;
  if (/\b(home|house|family|personal|doctor|dentist|appointment|grocery|groceries|errand|errands|lawn|yard|quote|repair|service)\b/.test(text)) {
    return "Personal";
  }
  if (/\b(work|client|project|repo|github|pull request|pr|ticket|bug|deploy|deployment|database|sql|dev|qa|story|stories|task assigned|assigned by|atoms|darkrunner|matter)\b/.test(text)) {
    return "Work";
  }
  return undefined;
}

function dailyItemLineNumber(markdown: string, index: number) {
  return markdown.slice(0, Math.max(0, index)).split("\n").length;
}

function dailyItemJSON(value: unknown): JsonObject {
  return value && typeof value === "object" && !Array.isArray(value) ? value as JsonObject : {};
}

function dailyScopeTagKey(tag: DailyItemScopeTag) {
  return `${tag.marker}:${tag.kind}:${tag.id ?? cleanDailyTagLabel(tag.label).toLowerCase()}`;
}

function normalizeDailyScopeTag(value: unknown): DailyItemScopeTag | null {
  const raw = dailyItemJSON(value);
  const rawKind = String(raw.kind ?? "").trim();
  const marker = raw.marker === "#" || raw.marker === "@"
    ? raw.marker
    : rawKind === "category"
      ? "#"
      : "@";
  const kind: DailyItemScopeTag["kind"] =
    rawKind === "category" || rawKind === "project" || rawKind === "folder" || rawKind === "unresolved"
      ? rawKind
      : marker === "#" ? "category" : "project";
  const label = cleanDailyTagLabel(raw.label ?? raw.title ?? raw.name);
  const id = cleanDailyText(raw.id);
  if (!label && !id) return null;
  return { marker, label: label || id, kind, id: id || undefined };
}

function normalizeDailyScopeTags(value: unknown): DailyItemScopeTag[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  const tags: DailyItemScopeTag[] = [];
  for (const candidate of value) {
    const tag = normalizeDailyScopeTag(candidate);
    if (!tag) continue;
    const key = dailyScopeTagKey(tag);
    if (seen.has(key)) continue;
    seen.add(key);
    tags.push(tag);
  }
  return tags;
}

function escapeDailyTagRegex(value: string) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function dailyTagNamePattern(label: string) {
  return cleanDailyTagLabel(label)
    .split(/\s+/)
    .filter(Boolean)
    .map(escapeDailyTagRegex)
    .join("\\s+");
}

function dailyTagCandidates(projects = loadProjects().plannerLists) {
  const categories = loadPlannerCategories(true)
    .filter((category) => category.hidden !== true && cleanDailyTagLabel(category.name))
    .map((category) => ({
      marker: "#" as const,
      kind: "category" as const,
      id: category.id,
      label: cleanDailyTagLabel(category.name)
    }));
  const lists = projects
    .filter((project) => cleanDailyTagLabel(project.title))
    .map((project) => {
      const kind: DailyItemScopeTag["kind"] = project.kind === "folder" ? "folder" : "project";
      return {
        marker: "@" as const,
        kind,
        id: project.id,
        label: cleanDailyTagLabel(project.title)
      };
    });
  return [...categories, ...lists]
    .sort((left, right) => right.label.length - left.label.length);
}

function resolveDailyProjectTitle(projectID?: string) {
  if (!projectID) return "";
  const projects = loadProjects();
  return projects.plannerLists.find((project) => project.id.toLowerCase() === projectID.toLowerCase())?.title
    ?? projects.projectNameByID.get(projectID)
    ?? projects.projectNameByID.get(projectID.toUpperCase())
    ?? projects.projectNameByID.get(projectID.toLowerCase())
    ?? projectID;
}

function resolveDailyFolderTitle(folderID?: string) {
  if (!folderID) return "";
  return loadProjects().plannerLists.find((project) =>
    project.kind === "folder" && project.id.toLowerCase() === folderID.toLowerCase()
  )?.title ?? folderID ?? "";
}

function scopeTagsFromDailyFields(projectID?: string, folderID?: string): DailyItemScopeTag[] {
  const tags: DailyItemScopeTag[] = [];
  const projectLabel = resolveDailyProjectTitle(projectID);
  if (projectID && projectLabel) tags.push({ marker: "@", label: projectLabel, kind: "project", id: projectID });
  const folderLabel = resolveDailyFolderTitle(folderID);
  if (folderID && folderLabel) tags.push({ marker: "@", label: folderLabel, kind: "folder", id: folderID });
  return tags;
}

function dedupeDailyScopeTags(tags: DailyItemScopeTag[]) {
  const seen = new Set<string>();
  const next: DailyItemScopeTag[] = [];
  for (const tag of tags) {
    const normalized = normalizeDailyScopeTag(tag);
    if (!normalized) continue;
    const key = dailyScopeTagKey(normalized);
    if (seen.has(key)) continue;
    seen.add(key);
    next.push(normalized);
  }
  return next;
}

function knownDailyTagAtStart(text: string, candidates: ReturnType<typeof dailyTagCandidates>) {
  for (const candidate of candidates) {
    const pattern = dailyTagNamePattern(candidate.label);
    if (!pattern) continue;
    const regex = new RegExp(`^${escapeDailyTagRegex(candidate.marker)}\\s*${pattern}(?=$|\\s)`, "i");
    const match = text.match(regex);
    if (!match) continue;
    return {
      tag: candidate,
      title: text.slice(match[0].length).trim()
    };
  }
  return null;
}

function knownDailyTagAtEnd(text: string, candidates: ReturnType<typeof dailyTagCandidates>) {
  for (const candidate of candidates) {
    const pattern = dailyTagNamePattern(candidate.label);
    if (!pattern) continue;
    const regex = new RegExp(`(?:^|\\s)${escapeDailyTagRegex(candidate.marker)}\\s*${pattern}\\s*$`, "i");
    const match = text.match(regex);
    if (!match) continue;
    return {
      tag: candidate,
      title: text.slice(0, match.index).trim()
    };
  }
  return null;
}

function unknownDailyTagAtStart(text: string) {
  const match = text.match(/^([@#])([^\s]+)(?:\s+|$)/);
  if (!match) return null;
  const title = text.slice(match[0].length).trim();
  if (!title) return null;
  const marker = match[1] as "@" | "#";
  return {
    tag: {
      marker,
      label: cleanDailyTagLabel(match[2]),
      kind: marker === "#" ? "category" as const : "unresolved" as const
    },
    title
  };
}

function unknownDailyTagAtEnd(text: string) {
  const match = text.match(/(?:^|\s)([@#])([^\s]+)\s*$/);
  if (!match || match.index === undefined) return null;
  const title = text.slice(0, match.index).trim();
  if (!title) return null;
  const marker = match[1] as "@" | "#";
  const label = cleanDailyTagLabel(match[2]);
  // "#482" at the end of "review PR #482" is an issue number, not a category —
  // never strip it into a bogus numeric heading.
  if (!label || /^\d+$/.test(label)) return null;
  return {
    tag: {
      marker,
      label,
      kind: marker === "#" ? "category" as const : "unresolved" as const
    },
    title
  };
}

function parseDailyTitleScope(value: unknown, candidates = dailyTagCandidates()) {
  const originalTitle = cleanDailyText(value).replace(/\s+/g, " ");
  let title = originalTitle;
  const tags: DailyItemScopeTag[] = [];
  const pushTag = (tag: DailyItemScopeTag) => {
    tags.push(tag);
  };
  for (let index = 0; index < 6; index += 1) {
    const start = knownDailyTagAtStart(title, candidates) ?? unknownDailyTagAtStart(title);
    if (start) {
      pushTag(start.tag);
      title = start.title;
      continue;
    }
    const end = knownDailyTagAtEnd(title, candidates) ?? unknownDailyTagAtEnd(title);
    if (end) {
      pushTag(end.tag);
      title = end.title;
      continue;
    }
    break;
  }
  return {
    title: title || originalTitle,
    scopeTags: dedupeDailyScopeTags(tags)
  };
}

function projectIDFromScopeTags(tags: DailyItemScopeTag[]) {
  return tags.find((tag) => tag.kind === "project" && tag.id)?.id;
}

function folderIDFromScopeTags(tags: DailyItemScopeTag[]) {
  return tags.find((tag) => tag.kind === "folder" && tag.id)?.id;
}

function areaFromScopeTags(tags: DailyItemScopeTag[]) {
  const categoryTag = tags.find((tag) => tag.kind === "category" || tag.marker === "#");
  return normalizeDailyArea(categoryTag?.label ?? categoryTag?.id);
}

function plannerListScopeTags(tags: DailyItemScopeTag[]) {
  return tags.filter((tag) => tag.kind === "project" || tag.kind === "folder" || tag.kind === "unresolved");
}

function scopeTagsForDailyItem(item: Pick<DailyItem, "projectID" | "folderID" | "scopeTags">) {
  const existing = plannerListScopeTags(normalizeDailyScopeTags(item.scopeTags));
  return existing.length ? existing : scopeTagsFromDailyFields(item.projectID, item.folderID);
}

function dailyItemVisibleTitle(item: DailyItem) {
  const tags = scopeTagsForDailyItem(item);
  const suffix = tags.map((tag) => `${tag.marker}${tag.label}`).join(" ");
  return [cleanDailyText(item.title), suffix].filter(Boolean).join(" ");
}

function dailyItemDedupeCore(value: unknown) {
  return cleanDailyText(value)
    .toLowerCase()
    .replace(/\ba\.?\s*m\.?/g, "am")
    .replace(/\bp\.?\s*m\.?/g, "pm")
    .replace(/&/g, " and ")
    .replace(/\bat\s+from\b/g, " from ")
    .replace(/\b(?:at\s+)?(?:from\s+)?\d{1,2}(?::\d{2})?\s*(?:am|pm)?\s*(?:to|through|-)\s*\d{1,2}(?::\d{2})?\s*(?:am|pm)?\b/g, " ")
    .replace(/\b(?:at|from)\s+\d{1,2}(?::\d{2})?\s*(?:am|pm)?\b/g, " ")
    .replace(/[^a-z0-9@#]+/g, " ")
    .replace(/\b(?:at|from)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const dailyItemSimilarityStopwords = new Set([
  "a", "an", "and", "are", "at", "by", "for", "from", "in", "into", "is", "it", "of", "on", "or", "the", "to", "with",
  "task", "todo", "item", "check", "measure", "measurement", "measurements"
]);

function dailyItemSimilarityTokens(value: unknown) {
  return dailyItemDedupeCore(value)
    .split(/\s+/)
    .map((token) => token.trim())
    .filter((token) => token.length >= 3 && !dailyItemSimilarityStopwords.has(token));
}

function dailyItemSimilarityScore(left: unknown, right: unknown) {
  const leftTokens = new Set(dailyItemSimilarityTokens(left));
  const rightTokens = new Set(dailyItemSimilarityTokens(right));
  if (!leftTokens.size || !rightTokens.size) return 0;
  const shared = [...leftTokens].filter((token) => rightTokens.has(token)).length;
  const smaller = Math.min(leftTokens.size, rightTokens.size);
  return smaller ? shared / smaller : 0;
}

function dailyItemLooksSimilar(left: unknown, right: unknown) {
  const leftCore = dailyItemDedupeCore(left);
  const rightCore = dailyItemDedupeCore(right);
  if (!leftCore || !rightCore) return false;
  if (leftCore === rightCore) return true;
  if ((leftCore.includes(rightCore) || rightCore.includes(leftCore)) && Math.min(leftCore.length, rightCore.length) >= 10) return true;
  const sharedTokens = dailyItemSimilarityTokens(left).filter((token) => new Set(dailyItemSimilarityTokens(right)).has(token));
  return sharedTokens.length >= 2 && dailyItemSimilarityScore(left, right) >= 0.8;
}

function dailyItemInputTitle(raw: JsonObject) {
  return parseDailyTitleScope(raw.title ?? raw.text ?? raw.label ?? "").title;
}

type PlannerListResolution =
  | { status: "none" }
  | { status: "ok"; list: ProjectItem }
  | { status: "not_found"; query: string }
  | { status: "ambiguous"; query: string; candidates: ProjectItem[] };

function resolvePlannerListFromDailyInput(raw: JsonObject): PlannerListResolution {
  const listValue = dailyItemJSON(raw.list);
  const rawID = cleanDailyText(
    raw.listID
      ?? raw.listId
      ?? raw.listProjectID
      ?? listValue.id
      ?? ""
  ).toLowerCase();
  const rawName = cleanDailyText(
    raw.listName
      ?? raw.listTitle
      ?? raw.listLabel
      ?? listValue.name
      ?? listValue.title
      ?? (typeof raw.list === "string" ? raw.list : "")
  ).toLowerCase();
  if (!rawID && !rawName) return { status: "none" };
  const lists = loadProjects().plannerLists;
  const exact = lists.find((project) =>
    (rawID && project.id.toLowerCase() === rawID)
    || (rawName && project.title.toLowerCase() === rawName)
  );
  if (exact) return { status: "ok", list: exact };
  // An ID was given but matched nothing — that is a hard miss.
  if (rawID && !rawName) return { status: "not_found", query: rawID };
  // Forgiving fallback: the model often says the List name with extra words
  // ("New Home Stuff list", "the New Home Stuff"). Strip filler and match on the
  // normalized name so the item still lands in the right List instead of silently
  // dropping to the bare Category.
  const wanted = normalizePlannerListName(rawName);
  if (!wanted) return { status: "not_found", query: rawName };
  const wantedPadded = ` ${wanted} `;
  const normalizedMatches = lists.filter((project) => {
    const candidate = normalizePlannerListName(project.title);
    if (!candidate) return false;
    if (candidate === wanted) return true;
    // Whole-word containment only: "home" may match "new home stuff", but
    // "work" must NOT match "workout".
    const candidatePadded = ` ${candidate} `;
    return candidatePadded.includes(wantedPadded) || wantedPadded.includes(candidatePadded);
  });
  if (normalizedMatches.length === 1) return { status: "ok", list: normalizedMatches[0] };
  if (normalizedMatches.length === 0) return { status: "not_found", query: rawName };
  // Two or more Lists collide on the normalized name — do not guess.
  return { status: "ambiguous", query: rawName, candidates: normalizedMatches };
}

// Throws a descriptive error when a List/folder was explicitly named in the input
// but could not be resolved to exactly one real List, so the model is told the
// placement failed instead of silently filing under the bare Category.
function assertPlannerListResolved(resolution: PlannerListResolution) {
  if (resolution.status === "not_found") {
    const known = loadProjects().plannerLists.map((project) => project.title);
    const hint = known.length ? ` Known lists: ${known.join(", ")}.` : "";
    throw new Error(`I couldn't find a list called "${resolution.query}".${hint} Please pick an existing list or say the exact name.`);
  }
  if (resolution.status === "ambiguous") {
    const names = resolution.candidates.map((project) => project.title).join(", ");
    throw new Error(`"${resolution.query}" matches more than one list (${names}). Which one did you mean?`);
  }
}

function plannerListFromDailyInput(raw: JsonObject) {
  const resolution = resolvePlannerListFromDailyInput(raw);
  return resolution.status === "ok" ? resolution.list : undefined;
}

function normalizePlannerListName(value: string) {
  return value
    .toLowerCase()
    .replace(/^(the|my|our)\s+/i, "")
    .replace(/\s+(list|category|section|folder)$/i, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function findSimilarDailyItem(items: DailyItem[], raw: JsonObject) {
  if (cleanDailyText(raw.id)) return undefined;
  const wanted = dailyItemDedupeCore(dailyItemInputTitle(raw));
  if (!wanted) return undefined;
  const matches = items.filter((item) =>
    dailyItemLooksSimilar(dailyItemVisibleTitle(item), wanted)
    || dailyItemLooksSimilar(item.title, wanted)
  );
  return matches.length === 1 ? matches[0] : undefined;
}

function mergedDuplicateDailyInput(raw: JsonObject, existing: DailyItem) {
  const incomingDetails = cleanDailyText(raw.detailsMarkdown ?? raw.details ?? raw.description);
  const existingDetails = cleanDailyText(existing.detailsMarkdown);
  const detailsMode = cleanDailyText(raw.detailsMode ?? raw.detailMode).toLowerCase();
  const replaceDetails = raw.replaceDetails === true || detailsMode === "replace" || detailsMode === "overwrite";
  const detailsMarkdown = replaceDetails
    ? incomingDetails
    : incomingDetails
    ? existingDetails && !existingDetails.toLowerCase().includes(incomingDetails.toLowerCase())
      ? `${existingDetails}\n${incomingDetails}`
      : existingDetails || incomingDetails
    : existing.detailsMarkdown;
  const links = normalizeDailyLinks([
    ...existing.links,
    ...(Array.isArray(raw.links) ? raw.links : [])
  ]);
  return {
    ...raw,
    // Plain-line ids ("plain:12") are line numbers, only valid for reads on the
    // source file; persisting one into a structured block makes later deletes
    // remove whatever ends up on that line. Let a fresh UUID be generated.
    id: existing.id.startsWith("plain:") ? undefined : existing.id,
    // Keep the INCOMING title: merging "add X" into a similar task Y must not
    // silently keep Y's wording while telling the model X was added.
    title: dailyItemInputTitle(raw) ? raw.title : existing.title,
    area: raw.area ?? existing.area,
    section: raw.section ?? existing.section,
    tags: raw.tags ?? existing.tags,
    projectID: raw.projectID ?? existing.projectID,
    folderID: raw.folderID ?? existing.folderID,
    scopeTags: raw.scopeTags ?? existing.scopeTags,
    detailsMarkdown,
    steps: Array.isArray(raw.steps) ? raw.steps : existing.steps,
    links
  };
}

function normalizeDailyStep(value: unknown, index: number): DailyItemStep | null {
  if (typeof value === "string") {
    const text = cleanDailyText(value);
    return text ? { id: randomUUID().toLowerCase(), text, checked: false } : null;
  }
  const raw = dailyItemJSON(value);
  const text = cleanDailyText(raw.text ?? raw.title ?? raw.label);
  if (!text) return null;
  return {
    id: cleanDailyText(raw.id) || `step-${index + 1}`,
    text,
    checked: raw.checked === true || raw.done === true
  };
}

function normalizeDailyLinks(value: unknown): NoteLinkTarget[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  const links: NoteLinkTarget[] = [];
  for (const candidate of value) {
    const target = normalizeNoteLinkTarget(candidate);
    if (!target) continue;
    const key = noteLinkKey(target);
    if (seen.has(key)) continue;
    seen.add(key);
    links.push(target);
  }
  return links;
}

function projectTitleForDailyItem(projectID?: string) {
  return resolveDailyProjectTitle(projectID);
}

function dailyItemMetadataForComment(item: DailyItem) {
  const scopeTags = scopeTagsForDailyItem(item);
  return {
    id: item.id,
    dayID: item.dayID,
    title: item.title,
    status: item.status,
    checked: item.checked,
    projectID: item.projectID,
    folderID: item.folderID,
    area: item.area,
    section: item.section,
    tags: normalizeDailyTagLabels(item.tags),
    scopeTags,
    detailsMarkdown: item.detailsMarkdown,
    steps: item.steps,
    links: item.links,
    reminderAt: item.reminderAt ?? null,
    reminderTimezone: item.reminderTimezone ?? null,
    reminderDeliveredAt: item.reminderDeliveredAt ?? null,
    createdAt: item.createdAt,
    updatedAt: item.updatedAt,
    order: item.order
  };
}

function normalizeReminderDate(value: unknown) {
  const text = cleanDailyText(value);
  if (!text) return null;
  const date = new Date(text);
  if (!Number.isFinite(date.getTime())) return null;
  return date.toISOString();
}

function renderDailyItemBlock(item: DailyItem) {
  const checked = item.checked || item.status === "done";
  const lines = [
    `<!-- oa-daily-item ${JSON.stringify(dailyItemMetadataForComment(item))} -->`,
    `- [${checked ? "x" : " "}] ${dailyItemVisibleTitle(item)}`
  ];
  if (item.detailsMarkdown.trim()) {
    lines.push("  - Details:");
    for (const detailLine of item.detailsMarkdown.trim().split("\n")) {
      lines.push(`    ${detailLine}`);
    }
  }
  if (item.steps.length) {
    lines.push("  - Steps:");
    for (const step of item.steps) {
      lines.push(`    - [${step.checked ? "x" : " "}] ${step.text}`);
    }
  }
  if (item.links.length) {
    lines.push("  - Links:");
    for (const link of item.links) {
      lines.push(`    - ${markdownLinkForTarget("Linked note", link)}`);
    }
  }
  lines.push("<!-- /oa-daily-item -->");
  return lines.join("\n");
}

function parseStructuredDailyItem(dayID: string, rawJSON: string, block: string, order: number, line: number, inheritedArea?: string): DailyItem | null {
  let metadata: JsonObject;
  try {
    metadata = JSON.parse(rawJSON) as JsonObject;
  } catch {
    return null;
  }
  const visibleTask = block.match(/^\s*[-*]\s+\[([ xX])\]\s+(.+?)\s*$/m);
  const visibleChecked = visibleTask ? visibleTask[1].toLowerCase() === "x" : metadata.checked === true;
  const titleScope = parseDailyTitleScope(visibleTask?.[2] ?? metadata.title ?? "");
  const metadataScopeTags = normalizeDailyScopeTags(metadata.scopeTags);
  const metadataProjectID = cleanDailyText(metadata.projectID) || undefined;
  const metadataFolderID = cleanDailyText(metadata.folderID) || undefined;
  const scopeTags = titleScope.scopeTags.length
    ? titleScope.scopeTags
    : metadataScopeTags.length
      ? metadataScopeTags
      : scopeTagsFromDailyFields(metadataProjectID, metadataFolderID);
  const listScopeTags = plannerListScopeTags(scopeTags);
  const projectID = projectIDFromScopeTags(listScopeTags) ?? metadataProjectID;
  const folderID = folderIDFromScopeTags(listScopeTags) ?? metadataFolderID;
  const title = titleScope.scopeTags.length ? titleScope.title : cleanDailyText(visibleTask?.[2] ?? metadata.title ?? "");
  if (!title) return null;
  const steps = Array.isArray(metadata.steps)
    ? metadata.steps.map((step, index) => normalizeDailyStep(step, index)).filter((step): step is DailyItemStep => Boolean(step))
    : [];
  const now = new Date().toISOString();
  return {
    id: cleanDailyText(metadata.id) || randomUUID().toLowerCase(),
    dayID: normalizeDailyItemDayID(cleanDailyText(metadata.dayID), dayID),
    title,
    status: normalizedDailyStatus(metadata.status, visibleChecked),
    checked: visibleChecked,
    projectID,
    folderID,
    projectName: resolveDailyProjectTitle(projectID) || undefined,
    folderName: resolveDailyFolderTitle(folderID) || undefined,
    area: normalizeDailyArea(metadata.area) || normalizeDailyArea(inheritedArea) || areaFromScopeTags(scopeTags) || inferDailyArea({ title, detailsMarkdown: metadata.detailsMarkdown, projectID, folderID, scopeTags: listScopeTags }),
    section: normalizeDailySection(metadata.section),
    tags: normalizeDailyTagLabels(metadata.tags),
    scopeTags: listScopeTags,
    detailsMarkdown: cleanDailyText(metadata.detailsMarkdown),
    steps,
    links: normalizeDailyLinks(metadata.links),
    reminderAt: normalizeReminderDate(metadata.reminderAt),
    reminderTimezone: cleanDailyText(metadata.reminderTimezone) || null,
    reminderDeliveredAt: normalizeReminderDate(metadata.reminderDeliveredAt),
    createdAt: cleanDailyText(metadata.createdAt) || now,
    updatedAt: cleanDailyText(metadata.updatedAt) || now,
    order: Number.isFinite(Number(metadata.order)) ? Number(metadata.order) : order,
    structured: true,
    line
  };
}

function parseDailyItemsFromMarkdown(dayID: string, markdown: string): DailyItem[] {
  const source = String(markdown ?? "").replace(/\r\n/g, "\n");
  const items: DailyItem[] = [];
  const blockRanges: Array<{ start: number; end: number }> = [];
  let match: RegExpExecArray | null;
  dailyItemBlockPattern.lastIndex = 0;
  while ((match = dailyItemBlockPattern.exec(source))) {
    const item = parseStructuredDailyItem(
      dayID,
      match[1],
      match[0],
      items.length,
      dailyItemLineNumber(source, match.index),
      plannerTaskSubheadingAtOffset(source, match.index)
    );
    if (item) items.push(item);
    blockRanges.push({ start: match.index, end: match.index + match[0].length });
  }
  const isInsideStructuredBlock = (index: number) => blockRanges.some((range) => index >= range.start && index < range.end);
  const linePattern = /^(\s*)[-*]\s+\[([ xX])\]\s+(.+?)\s*$/;
  const lines = source.split("\n");
  const lineStarts: number[] = [];
  {
    let cursor = 0;
    for (const lineText of lines) {
      lineStarts.push(cursor);
      cursor += lineText.length + 1;
    }
  }
  let insideTasks = false;
  let currentSubheading: string | undefined;
  // Indented children already claimed by a preceding plain task as its
  // details/steps; they must not become items of their own.
  const consumedChildLines = new Set<number>();
  lines.forEach((line, index) => {
    const start = lineStarts[index];
    const heading = line.match(/^##\s+(.+?)\s*$/);
    if (heading) {
      insideTasks = cleanDailyText(heading[1]).toLowerCase() === "tasks";
      currentSubheading = undefined;
      return;
    }
    if (insideTasks) {
      const subheading = line.match(/^###\s+(.+?)\s*$/);
      if (subheading) {
        currentSubheading = normalizeDailyArea(subheading[1]) ?? cleanDailyTagLabel(subheading[1]);
        return;
      }
    }
    if (isInsideStructuredBlock(start)) return;
    if (consumedChildLines.has(index)) return;
    const task = line.match(linePattern);
    if (!task) return;
    const title = task[3].replace(/<!--[\s\S]*?-->/g, "").trim();
    if (!title) return;
    const checked = task[2].toLowerCase() === "x";
    const titleScope = parseDailyTitleScope(title);
    const listScopeTags = plannerListScopeTags(titleScope.scopeTags);
    const projectID = projectIDFromScopeTags(listScopeTags);
    const folderID = folderIDFromScopeTags(listScopeTags);
    // A plain task owns the indented block under it (same shape the structured
    // renderer writes): nested checkboxes become steps, everything else becomes
    // detailsMarkdown. Without this, the canvas shows the details but parsed
    // items (Items panel, phone app, reminders) silently lose them.
    const taskIndent = task[1].length;
    const detailLines: string[] = [];
    const plainSteps: DailyItemStep[] = [];
    for (let child = index + 1; child < lines.length; child += 1) {
      const childLine = lines[child];
      const childTrimmed = childLine.trim();
      if (!childTrimmed) continue;
      if (isInsideStructuredBlock(lineStarts[child])) break;
      const childIndent = childLine.match(/^\s*/)?.[0].length ?? 0;
      if (childIndent <= taskIndent) break;
      const childTask = childLine.match(/^\s*[-*]\s+\[([ xX])\]\s+(.+?)\s*$/);
      if (childTask) {
        const stepText = childTask[2].replace(/<!--[\s\S]*?-->/g, "").trim();
        if (stepText) {
          plainSteps.push({ id: `step-${plainSteps.length + 1}`, text: stepText, checked: childTask[1].toLowerCase() === "x" });
        }
      } else if (!childTrimmed.startsWith("<!--")) {
        const withoutBullet = childTrimmed.replace(/^[-*]\s+/, "");
        const withoutLabel = withoutBullet.replace(/^(Details|Steps|Links):\s*/i, "");
        if (withoutLabel) detailLines.push(withoutLabel);
      }
      consumedChildLines.add(child);
    }
    items.push({
      id: `plain:${index + 1}`,
      dayID,
      title: titleScope.title,
      status: checked ? "done" : "todo",
      checked,
      projectID,
      folderID,
      projectName: resolveDailyProjectTitle(projectID) || undefined,
      folderName: resolveDailyFolderTitle(folderID) || undefined,
      area: normalizeDailyArea(currentSubheading) || areaFromScopeTags(titleScope.scopeTags) || inferDailyArea({ title: titleScope.title, projectID, folderID, scopeTags: listScopeTags }),
      section: undefined,
      tags: [],
      scopeTags: listScopeTags,
      detailsMarkdown: detailLines.join("\n"),
      steps: plainSteps,
      links: [],
      reminderAt: null,
      reminderTimezone: null,
      reminderDeliveredAt: null,
      createdAt: "",
      updatedAt: "",
      order: items.length,
      structured: false,
      line: index + 1
    });
  });
  return items.sort((left, right) => left.order - right.order || (left.line ?? 0) - (right.line ?? 0));
}

function listDailyItems(dayID?: string): DailyItem[] {
  const day = loadPlannerDay(dayID);
  return parseDailyItemsFromMarkdown(day.id, day.markdown);
}

function plannerDayFreeTextLines(dayID?: string): string[] {
  const day = loadPlannerDay(dayID);
  const source = String(day.markdown ?? "").replace(/\r\n/g, "\n");
  const structuredItems = parseDailyItemsFromMarkdown(day.id, source);
  const structuredTitles = new Set(
    structuredItems.map((item) => cleanDailyText(item.title).toLowerCase()).filter(Boolean)
  );
  const blockRanges: Array<{ start: number; end: number }> = [];
  let match: RegExpExecArray | null;
  dailyItemBlockPattern.lastIndex = 0;
  while ((match = dailyItemBlockPattern.exec(source))) {
    blockRanges.push({ start: match.index, end: match.index + match[0].length });
  }
  const isInsideStructuredBlock = (index: number) => blockRanges.some((range) => index >= range.start && index < range.end);
  const checkboxPattern = /^(\s*)[-*+]\s+\[([ xX])\]\s+(.+?)\s*$/;
  const lines: string[] = [];
  let offset = 0;
  source.split("\n").forEach((line) => {
    const start = offset;
    offset += line.length + 1;
    if (isInsideStructuredBlock(start)) return;
    const trimmed = line.trim();
    if (!trimmed) return;
    if (/^#{1,6}\s/.test(trimmed)) return;
    if (/^>\s?/.test(trimmed)) return;
    if (/^<!--/.test(trimmed) || /^<!--[\s\S]*-->$/.test(trimmed)) return;
    if (checkboxPattern.test(trimmed)) return;
    const text = trimmed.replace(/<!--[\s\S]*?-->/g, "").trim();
    if (!text) return;
    if (structuredTitles.has(text.toLowerCase())) return;
    lines.push(text);
  });
  return lines;
}

function dailyItemsKnowledgeResult(dayID?: string) {
  const normalizedDayID = normalizePlannerDayID(dayID);
  const items = listDailyItems(normalizedDayID);
  const freeTextItems = plannerDayFreeTextLines(normalizedDayID);
  const result: { items: DailyItem[]; noteMarkdown?: string; freeTextItems?: string[] } = { items };
  if (freeTextItems.length) result.freeTextItems = freeTextItems;
  if (!items.length) {
    const day = loadPlannerDay(normalizedDayID);
    result.noteMarkdown = String(day.markdown ?? "").replace(/\r\n/g, "\n");
  }
  return result;
}

function normalizeDailyItemInput(input: unknown, existing?: DailyItem): DailyItem {
  const raw = dailyItemJSON(input);
  const dayID = normalizeDailyItemDayID(cleanDailyText(raw.dayID), existing?.dayID);
  // Honor an explicit "uncomplete" intent first. Without this, existing.checked
  // (or a status that resolves to done) silently overrides an incoming
  // checked:false / status:"todo", making un-completing a task a no-op.
  const statusText = String(raw.status ?? "").trim().toLowerCase();
  const explicitlyUnchecked = raw.checked === false
    || raw.done === false
    || statusText === "todo"
    || statusText === "open"
    || statusText === "not_done"
    || statusText === "not done"
    || statusText === "doing"
    || statusText === "in_progress"
    || statusText === "active";
  const checked = !explicitlyUnchecked
    && (raw.checked === true || raw.done === true || existing?.checked === true);
  const status = normalizedDailyStatus(raw.status ?? existing?.status, checked);
  const titleScope = parseDailyTitleScope(raw.title ?? existing?.title ?? "");
  const title = titleScope.title;
  if (!title) throw new Error("Daily item needs a title.");
  const now = new Date().toISOString();
  const stepsValue = Array.isArray(raw.steps) ? raw.steps : existing?.steps ?? [];
  const hasProjectID = Object.prototype.hasOwnProperty.call(raw, "projectID");
  const hasFolderID = Object.prototype.hasOwnProperty.call(raw, "folderID");
  const hasScopeTags = Object.prototype.hasOwnProperty.call(raw, "scopeTags");
  const shouldClearPlannerList = raw.clearList === true
    || raw.removeList === true
    || raw.unassignList === true
    || raw.listID === null
    || raw.listId === null
    || raw.listName === null
    || raw.list === null
    || raw.projectID === null
    || raw.folderID === null
    || (hasScopeTags && Array.isArray(raw.scopeTags) && raw.scopeTags.length === 0);
  const listResolution = resolvePlannerListFromDailyInput(raw);
  // If the caller named a List but it couldn't be resolved to one real List, fail
  // loud — unless an explicit projectID/folderID already pins the scope. This stops
  // the item from silently landing under the bare Category while we report success.
  if ((listResolution.status === "not_found" || listResolution.status === "ambiguous")
    && !cleanDailyText(raw.projectID) && !cleanDailyText(raw.folderID)) {
    assertPlannerListResolved(listResolution);
  }
  const inputList = listResolution.status === "ok" ? listResolution.list : undefined;
  const hasList = Boolean(inputList);
  const rawProjectID = shouldClearPlannerList ? undefined : cleanDailyText(raw.projectID) || (inputList && inputList.kind !== "folder" ? inputList.id : undefined);
  const rawFolderID = shouldClearPlannerList ? undefined : cleanDailyText(raw.folderID) || (inputList?.kind === "folder" ? inputList.id : undefined);
  const rawScopeTags = normalizeDailyScopeTags(raw.scopeTags);
  const fieldProjectID = shouldClearPlannerList ? undefined : hasProjectID || hasList ? rawProjectID : existing?.projectID;
  const fieldFolderID = shouldClearPlannerList ? undefined : hasFolderID || hasList ? rawFolderID : existing?.folderID;
  const fieldScopeTags = scopeTagsFromDailyFields(fieldProjectID, fieldFolderID);
  const titleListScopeTags = plannerListScopeTags(titleScope.scopeTags);
  const sourceScopeTags = titleScope.scopeTags.length
    ? (titleListScopeTags.length ? titleScope.scopeTags : fieldScopeTags)
    : shouldClearPlannerList
      ? []
    : hasScopeTags
      ? rawScopeTags
      : fieldScopeTags;
  const scopeTags = plannerListScopeTags(sourceScopeTags);
  const projectID = projectIDFromScopeTags(scopeTags) ?? fieldProjectID;
  const folderID = folderIDFromScopeTags(scopeTags) ?? fieldFolderID;
  // On updates the task's CURRENT category must win over keyword inference —
  // otherwise an unrelated edit (rename, reminder change) silently re-categorizes
  // and relocates the task. Inference only fills the gap for new items.
  const area = areaFromScopeTags(titleScope.scopeTags)
    || areaFromScopeTags(rawScopeTags)
    || normalizeDailyArea(raw.area ?? raw.category)
    || normalizeDailyArea(existing?.area)
    || inferDailyArea({ title, detailsMarkdown: raw.detailsMarkdown ?? existing?.detailsMarkdown, projectID, folderID, scopeTags });
  const hasTags = Object.prototype.hasOwnProperty.call(raw, "tags") || Object.prototype.hasOwnProperty.call(raw, "tag");
  const tags = hasTags
    ? normalizeDailyTagLabels(raw.tags ?? raw.tag)
    : normalizeDailyTagLabels(existing?.tags);
  const hasReminderAt = Object.prototype.hasOwnProperty.call(raw, "reminderAt")
    || Object.prototype.hasOwnProperty.call(raw, "notifyAt")
    || Object.prototype.hasOwnProperty.call(raw, "dueAt");
  const reminderAt = hasReminderAt
    ? normalizeReminderDate(raw.reminderAt ?? raw.notifyAt ?? raw.dueAt)
    : existing?.reminderAt ?? null;
  const hasReminderTimezone = Object.prototype.hasOwnProperty.call(raw, "reminderTimezone")
    || Object.prototype.hasOwnProperty.call(raw, "timezone")
    || Object.prototype.hasOwnProperty.call(raw, "timeZone");
  const reminderTimezone = hasReminderTimezone
    ? cleanDailyText(raw.reminderTimezone ?? raw.timezone ?? raw.timeZone) || null
    : existing?.reminderTimezone ?? null;
  const hasReminderDeliveredAt = Object.prototype.hasOwnProperty.call(raw, "reminderDeliveredAt");
  const reminderDeliveredAt = (() => {
    if (!reminderAt) return null;
    if (hasReminderDeliveredAt) return normalizeReminderDate(raw.reminderDeliveredAt);
    return reminderAt === (existing?.reminderAt ?? null) ? existing?.reminderDeliveredAt ?? null : null;
  })();
  return {
    // Never persist a plain-line id ("plain:12") into a structured block: those
    // are line numbers, and a later delete/move would remove the wrong line.
    id: (() => {
      const rawID = cleanDailyText(raw.id);
      if (rawID && !rawID.startsWith("plain:")) return rawID;
      return (existing?.structured ? existing.id : "") || randomUUID().toLowerCase();
    })(),
    dayID,
    title,
    status,
    checked: checked || status === "done",
    projectID,
    folderID,
    projectName: resolveDailyProjectTitle(projectID) || undefined,
    folderName: resolveDailyFolderTitle(folderID) || undefined,
    area,
    section: normalizeDailySection(raw.section ?? raw.grouping) ?? normalizeDailySection(existing?.section),
    tags,
    scopeTags,
    detailsMarkdown: cleanDailyText(raw.detailsMarkdown ?? existing?.detailsMarkdown ?? ""),
    steps: stepsValue.map((step, index) => normalizeDailyStep(step, index)).filter((step): step is DailyItemStep => Boolean(step)),
    links: normalizeDailyLinks(raw.links ?? existing?.links ?? []),
    reminderAt,
    reminderTimezone,
    reminderDeliveredAt: reminderAt ? reminderDeliveredAt : null,
    createdAt: existing?.createdAt || cleanDailyText(raw.createdAt) || now,
    updatedAt: now,
    order: Number.isFinite(Number(raw.order)) ? Number(raw.order) : existing?.order ?? 0,
    structured: true
  };
}

function replaceStructuredDailyItem(markdown: string, item: DailyItem) {
  let replaced = false;
  let needsRelocation = false;
  dailyItemBlockPattern.lastIndex = 0;
  const next = markdown.replace(dailyItemBlockPattern, (block: string, rawJSON: string, offset: number) => {
    const existing = parseStructuredDailyItem(item.dayID, rawJSON, block, 0, 0);
    if (existing?.id !== item.id) return block;
    replaced = true;
    // When the category changed, drop the block here and re-append it under the
    // new ### heading — otherwise the metadata claims the new category while the
    // visible note still shows the task under the old one.
    const currentHeading = cleanDailyText(plannerTaskSubheadingAtOffset(markdown, offset)).toLowerCase();
    const targetHeading = cleanDailyText(item.area).toLowerCase();
    if (currentHeading !== targetHeading) {
      needsRelocation = true;
      return "";
    }
    return renderDailyItemBlock(item);
  });
  if (replaced && needsRelocation) {
    return cleanPlannerTaskSpacing(
      appendToPlannerSubsection(next.replace(/\n{3,}/g, "\n\n"), "Tasks", item.area, renderDailyItemBlock(item))
    );
  }
  return cleanPlannerTaskSpacing(
    replaced ? next : appendToPlannerSubsection(markdown, "Tasks", item.area, renderDailyItemBlock(item))
  );
}

function normalizeStructuredDailyItemLayout(dayID: string, markdown: string) {
  let normalized = cleanPlannerTaskSpacing(markdown);
  const structuredItems = parseDailyItemsFromMarkdown(dayID, normalized)
    .filter((item) => item.structured && !item.id.startsWith("plain:"));
  for (const item of structuredItems) {
    normalized = replaceStructuredDailyItem(normalized, item);
  }
  return cleanPlannerTaskSpacing(normalized);
}

function renamePlannerCategoryAreaReferences(oldName: string, newName: string) {
  const previousArea = cleanDailyText(oldName);
  const nextArea = normalizePlannerCategoryName(newName);
  if (!previousArea || !nextArea || previousArea.toLowerCase() === nextArea.toLowerCase()) return;

  const { filePath, snapshot } = projectStoreSnapshot();
  let projectsChanged = false;
  for (const project of snapshot.projects ?? []) {
    if (cleanDailyText(project.area).toLowerCase() !== previousArea.toLowerCase()) continue;
    project.area = nextArea;
    project.updatedAt = currentSwiftDate();
    projectsChanged = true;
  }
  if (projectsChanged) {
    saveProjectStoreSnapshot(filePath, snapshot);
    emitProjectsChanged();
  }

  const backlog = loadPlannerBacklog();
  let backlogMarkdown = backlog.markdown;
  let backlogChanged = false;
  for (const item of parseDailyItemsFromMarkdown(plannerBacklogID, backlogMarkdown)) {
    if (!item.structured || cleanDailyText(item.area).toLowerCase() !== previousArea.toLowerCase()) continue;
    const updated = { ...item, area: nextArea, updatedAt: new Date().toISOString() };
    const nextMarkdown = replaceStructuredDailyItem(backlogMarkdown, updated);
    if (nextMarkdown !== backlogMarkdown) {
      backlogMarkdown = nextMarkdown;
      backlogChanged = true;
    }
  }
  if (backlogChanged) {
    savePlannerBacklog(backlogMarkdown);
    emitPlannerBacklogChanged();
  }

  const changedDayIDs: string[] = [];
  for (const day of listPlannerDays(3650, plannerDayID())) {
    const dayDetail = loadPlannerDay(day.id);
    let dayMarkdown = dayDetail.markdown;
    let dayChanged = false;
    for (const item of parseDailyItemsFromMarkdown(day.id, dayMarkdown)) {
      if (!item.structured || cleanDailyText(item.area).toLowerCase() !== previousArea.toLowerCase()) continue;
      const updated = { ...item, area: nextArea, updatedAt: new Date().toISOString() };
      const nextMarkdown = replaceStructuredDailyItem(dayMarkdown, updated);
      if (nextMarkdown !== dayMarkdown) {
        dayMarkdown = nextMarkdown;
        dayChanged = true;
      }
    }
    if (dayChanged) {
      savePlannerDay(day.id, dayMarkdown);
      changedDayIDs.push(day.id);
    }
  }
  for (const dayID of changedDayIDs) {
    emitPlannerDayChanged(dayID);
  }
}

function removePlainDailyItemLine(markdown: string, itemID: string) {
  const lineNumber = Number(itemID.match(/^plain:(\d+)$/)?.[1] ?? 0);
  if (!lineNumber) return markdown;
  const lines = markdown.split("\n");
  const start = lineNumber - 1;
  if (!lines[start]) return markdown;
  let end = start + 1;
  while (end < lines.length) {
    const line = lines[end];
    const trimmed = line.trim();
    if (!trimmed) {
      end += 1;
      continue;
    }
    // Plain tasks can still have indented Details/Steps/Links children. When
    // converting one to a structured item, remove that whole visible block so
    // the old children do not become orphan bullets above the new task.
    if (/^\s+/.test(line) && !trimmed.startsWith("<!--")) {
      end += 1;
      continue;
    }
    break;
  }
  return [
    ...lines.slice(0, start),
    ...lines.slice(end)
  ].join("\n").replace(/\n{3,}/g, "\n\n");
}

function replacePlainDailyItemBlock(markdown: string, item: DailyItem, replacement: string) {
  const lineNumber = item.line ?? Number(item.id.match(/^plain:(\d+)$/)?.[1] ?? 0);
  if (!lineNumber) return markdown;
  const lines = markdown.split("\n");
  const start = lineNumber - 1;
  if (!lines[start]) return markdown;
  let end = start + 1;
  while (end < lines.length) {
    const line = lines[end];
    const trimmed = line.trim();
    if (!trimmed || (/^\s+/.test(line) && !trimmed.startsWith("<!--"))) {
      end += 1;
      continue;
    }
    break;
  }
  return [
    ...lines.slice(0, start),
    ...replacement.split("\n"),
    ...lines.slice(end)
  ].join("\n");
}

function dailyItemEditorMatchKey(item: DailyItem) {
  return cleanDailyText(dailyItemVisibleTitle(item)).toLowerCase();
}

function editorDetailsWithoutStructuredLinks(item: DailyItem, existing: DailyItem) {
  if (!existing.links.length || !item.detailsMarkdown) return item.detailsMarkdown;
  const linkLines = new Set(existing.links.map((link) => cleanDailyText(markdownLinkForTarget("Linked note", link)).toLowerCase()));
  return item.detailsMarkdown
    .split("\n")
    .filter((line) => !linkLines.has(cleanDailyText(line).toLowerCase()))
    .join("\n")
    .trim();
}

/**
 * TipTap intentionally omits HTML comments when it serializes markdown. Planner
 * task metadata lives in those comments, so a normal canvas save must put the
 * metadata back around tasks that are still present. Missing tasks stay deleted.
 */
function preserveStructuredDailyItemsAfterEditorRoundTrip(dayID: string, previousMarkdown: string, editorMarkdown: string) {
  const incomingMarkdown = String(editorMarkdown ?? "").replace(/\r\n/g, "\n");
  const previousStructured = parseDailyItemsFromMarkdown(dayID, previousMarkdown)
    .filter((item) => item.structured && !item.id.startsWith("plain:"));
  if (!previousStructured.length) return cleanPlannerTaskSpacing(incomingMarkdown);

  const incomingItems = parseDailyItemsFromMarkdown(dayID, incomingMarkdown);
  const incomingStructuredIDs = new Set(
    incomingItems.filter((item) => item.structured).map((item) => item.id)
  );
  const plainByKey = new Map<string, DailyItem[]>();
  for (const item of incomingItems) {
    if (item.structured) continue;
    const key = dailyItemEditorMatchKey(item);
    if (!key) continue;
    plainByKey.set(key, [...(plainByKey.get(key) ?? []), item]);
  }

  const replacements: Array<{ plain: DailyItem; structured: DailyItem }> = [];
  for (const existing of previousStructured) {
    if (incomingStructuredIDs.has(existing.id)) continue;
    const matches = plainByKey.get(dailyItemEditorMatchKey(existing));
    const plain = matches?.shift();
    if (!plain) continue;
    const detailsMarkdown = editorDetailsWithoutStructuredLinks(plain, existing);
    const steps = plain.steps.map((step, index) => ({
      ...step,
      id: existing.steps[index]?.id ?? step.id
    }));
    const contentChanged = existing.checked !== plain.checked
      || existing.detailsMarkdown !== detailsMarkdown
      || JSON.stringify(existing.steps) !== JSON.stringify(steps);
    replacements.push({
      plain,
      structured: {
        ...existing,
        checked: plain.checked,
        status: plain.checked ? "done" : "todo",
        detailsMarkdown,
        steps,
        order: plain.order,
        updatedAt: contentChanged ? new Date().toISOString() : existing.updatedAt,
        structured: true
      }
    });
  }

  let merged = incomingMarkdown;
  for (const replacement of replacements.sort((left, right) => (right.plain.line ?? 0) - (left.plain.line ?? 0))) {
    merged = replacePlainDailyItemBlock(merged, replacement.plain, renderDailyItemBlock(replacement.structured));
  }
  return normalizeStructuredDailyItemLayout(dayID, merged);
}

function setPlainDailyItemChecked(markdown: string, itemID: string, checked: boolean) {
  const lineNumber = Number(itemID.match(/^plain:(\d+)$/)?.[1] ?? 0);
  if (!lineNumber) return markdown;
  const lines = markdown.split("\n");
  const index = lineNumber - 1;
  if (!lines[index]) return markdown;
  lines[index] = lines[index].replace(/\[[ xX]\]/, `[${checked ? "x" : " "}]`);
  return lines.join("\n");
}

function removeStructuredDailyItem(markdown: string, itemID: string) {
  dailyItemBlockPattern.lastIndex = 0;
  return markdown.replace(dailyItemBlockPattern, (block: string, rawJSON: string) => {
    const existing = parseStructuredDailyItem(plannerBacklogID, rawJSON, block, 0, 0)
      ?? parseStructuredDailyItem(plannerDayID(), rawJSON, block, 0, 0);
    return existing?.id === itemID ? "" : block;
  }).replace(/\n{3,}/g, "\n\n");
}

// Remove tasks from a day's markdown by their visible text. Used when MOVING
// tasks to another day so the originals do not stay behind. Handles both plain
// "- [ ]" lines and structured oa-daily-item blocks. Returns the new markdown
// plus the texts that were actually matched and removed.
function removePlannerTasksByText(dayID: string, markdown: string, texts: string[]) {
  // Count-aware: passing the same title twice removes TWO occurrences, so
  // duplicate-titled tasks that each moved also each disappear from the source
  // day instead of one being silently left behind.
  const wanted = new Map<string, number>();
  for (const text of texts) {
    const key = cleanDailyText(text).toLowerCase();
    if (key) wanted.set(key, (wanted.get(key) ?? 0) + 1);
  }
  if (!wanted.size) return { markdown, removed: [] as string[] };
  const removed: string[] = [];
  let next = markdown;
  // Re-parse after each removal because plain-line removal shifts line numbers.
  for (let guard = 0; guard < texts.length + 1; guard += 1) {
    const items = parseDailyItemsFromMarkdown(dayID, next);
    const target = items.find((item) => (wanted.get(dailyItemVisibleTitle(item).toLowerCase()) ?? 0) > 0
      || (wanted.get(cleanDailyText(item.title).toLowerCase()) ?? 0) > 0);
    if (!target) break;
    removed.push(dailyItemVisibleTitle(target));
    const visibleKey = dailyItemVisibleTitle(target).toLowerCase();
    const matchedKey = (wanted.get(visibleKey) ?? 0) > 0 ? visibleKey : cleanDailyText(target.title).toLowerCase();
    const remaining = (wanted.get(matchedKey) ?? 0) - 1;
    if (remaining > 0) wanted.set(matchedKey, remaining);
    else wanted.delete(matchedKey);
    next = target.id.startsWith("plain:")
      ? removePlainDailyItemLine(next, target.id)
      : removeStructuredDailyItem(next, target.id);
  }
  return { markdown: next.replace(/\n{3,}/g, "\n\n"), removed };
}

// Re-derive the mutated item from the freshly saved markdown, so the success
// response reports what was actually persisted — never the in-memory object a
// write path constructed (which can silently differ when fields get dropped).
function readBackMutatedItem(item: DailyItem | null | undefined, ...itemLists: Array<DailyItem[] | undefined>) {
  if (!item) return item;
  for (const items of itemLists) {
    if (!items?.length) continue;
    const byID = items.find((candidate) => candidate.id === item.id);
    if (byID) return byID;
  }
  // plain: item ids are positional and may not survive a re-parse; fall back to
  // an exact-title match before flagging the miss.
  const title = dailyItemVisibleTitle(item).trim().toLowerCase();
  for (const items of itemLists) {
    const byTitle = items?.find((candidate) => dailyItemVisibleTitle(candidate).trim().toLowerCase() === title);
    if (byTitle) return byTitle;
  }
  return { ...item, readBack: false };
}

function dailyMutationResult(day: PlannerDayDetail, item?: DailyItem | null): DailyItemMutationResult {
  const items = parseDailyItemsFromMarkdown(day.id, day.markdown);
  return {
    day,
    items,
    item: readBackMutatedItem(item, items)
  };
}

function upsertDailyItem(input: unknown): DailyItemMutationResult {
  const raw = dailyItemJSON(input);
  const dayID = normalizePlannerDayID(cleanDailyText(raw.dayID));
  const day = loadPlannerDay(dayID);
  const items = parseDailyItemsFromMarkdown(day.id, day.markdown);
  const rawID = cleanDailyText(raw.id);
  const existingByID = items.find((item) => item.id === rawID);
  // A non-empty id that matches nothing on this day is stale (the task lives on
  // another day, or the model echoed an old id). Never persist it into a new
  // block — that would put the same id on two days — treat it as an id-less add
  // so the similar-item dedupe still applies.
  const effectiveRaw = rawID && !existingByID ? { ...raw, id: undefined } : raw;
  const similarExisting = existingByID ? undefined : findSimilarDailyItem(items, effectiveRaw);
  const existing = existingByID ?? similarExisting;
  const item = normalizeDailyItemInput(similarExisting ? mergedDuplicateDailyInput(effectiveRaw, similarExisting) : effectiveRaw, existing);
  const sourceMarkdown = existing?.structured === false && existing.id ? removePlainDailyItemLine(day.markdown, existing.id) : day.markdown;
  const savedDay = savePlannerDay(item.dayID, replaceStructuredDailyItem(sourceMarkdown, item));
  emitPlannerDayChanged(savedDay.id);
  return dailyMutationResult(savedDay, item);
}

function appendMovedDailyItemToDay(input: unknown, targetDayID: string): DailyItemMutationResult {
  const destinationDayID = resolvePlannerDayIDForWrite(targetDayID);
  const day = loadPlannerDay(destinationDayID);
  const existingItems = parseDailyItemsFromMarkdown(day.id, day.markdown);
  const raw = dailyItemJSON(input);
  const item = normalizeDailyItemInput({
    ...raw,
    // Structured IDs remain stable across a move so peers can distinguish a
    // move from a delete plus an unrelated add. Legacy plain-line IDs are local
    // line numbers and are replaced during migration.
    id: raw.id && !String(raw.id).startsWith("plain:") ? raw.id : undefined,
    dayID: destinationDayID,
    order: existingItems.length
  });
  const savedDay = savePlannerDay(destinationDayID, replaceStructuredDailyItem(day.markdown, item));
  emitPlannerDayChanged(savedDay.id);
  return dailyMutationResult(savedDay, item);
}

function toggleDailyItem(dayID: string | undefined, itemID: string, checked: boolean): DailyItemMutationResult {
  const normalizedDayID = normalizePlannerDayID(dayID);
  const day = loadPlannerDay(normalizedDayID);
  const existing = parseDailyItemsFromMarkdown(day.id, day.markdown).find((item) => item.id === itemID);
  if (!existing) return dailyMutationResult(day, null);
  if (existing.structured) {
    const item = normalizeDailyItemInput({ ...existing, checked, status: checked ? "done" : "todo" }, existing);
    const savedDay = savePlannerDay(normalizedDayID, replaceStructuredDailyItem(day.markdown, item));
    emitPlannerDayChanged(savedDay.id);
    return dailyMutationResult(savedDay, item);
  }
  const savedDay = savePlannerDay(normalizedDayID, setPlainDailyItemChecked(day.markdown, itemID, checked));
  emitPlannerDayChanged(savedDay.id);
  return dailyMutationResult(savedDay, { ...existing, checked, status: checked ? "done" : "todo" });
}

// Find a task in a planner day by its visible text. The AI knows the task
// wording (e.g. "mortgage application"), not the internal id, so we match on
// the title: first an exact match, then ignoring case, then a "contains" match.
// The "contains" tier only accepts a UNIQUE match — if the query is a substring
// of two or more tasks we throw instead of silently mutating/deleting the first,
// mirroring the unambiguous-match rule used for planner lists.
function findDailyItemByText(items: DailyItem[], query: string) {
  const wanted = cleanDailyText(query).toLowerCase();
  if (!wanted) return undefined;
  const titleOf = (item: DailyItem) => dailyItemVisibleTitle(item).toLowerCase();
  const exact = items.find((item) => titleOf(item) === wanted)
    ?? items.find((item) => cleanDailyText(item.title).toLowerCase() === wanted);
  if (exact) return exact;
  const partial = items.filter((item) => titleOf(item).includes(wanted));
  if (partial.length === 1) return partial[0];
  if (partial.length > 1) {
    const names = partial.map((item) => dailyItemVisibleTitle(item)).join("; ");
    throw new Error(`"${query}" matches more than one task (${names}). Please say the exact task.`);
  }
  return undefined;
}

// Mark a planner task done (or not done) by its text. Applies immediately,
// like adding a task — no approval step. Reuses toggleDailyItem so it works
// for both structured and plain `- [ ]` tasks.
function completeDailyItem(dayID: string | undefined, query: string, checked = true): DailyItemMutationResult {
  const normalizedDayID = normalizePlannerDayID(dayID);
  const day = loadPlannerDay(normalizedDayID);
  const items = parseDailyItemsFromMarkdown(day.id, day.markdown);
  const match = findDailyItemByText(items, query);
  if (!match) {
    const available = items.map((item) => dailyItemVisibleTitle(item)).filter(Boolean);
    throw new Error(`No task matching "${query}" was found on ${day.id}. Tasks on that day: ${available.length ? available.join("; ") : "none"}.`);
  }
  return toggleDailyItem(normalizedDayID, match.id, checked);
}

type PlannerTaskLocation = {
  kind: "day" | "backlog";
  id: string;
  detail: PlannerDayDetail | PlannerBacklogDetail;
  items: DailyItem[];
  item: DailyItem;
};

function plannerTaskContainers(raw: JsonObject) {
  const requestedSource = cleanDailyText(raw.dayID ?? raw.date);
  if (requestedSource) {
    const sourceID = resolvePlannerDayIDForWrite(requestedSource);
    if (sourceID === plannerBacklogID) {
      const detail = loadPlannerBacklog();
      return [{ kind: "backlog" as const, id: plannerBacklogID, detail }];
    }
    const detail = loadPlannerDay(sourceID);
    return [{ kind: "day" as const, id: sourceID, detail }];
  }

  const backlog = loadPlannerBacklog();
  return [
    { kind: "backlog" as const, id: plannerBacklogID, detail: backlog },
    ...listPlannerDays(3650, plannerDayID()).map((day) => ({
      kind: "day" as const,
      id: day.id,
      detail: loadPlannerDay(day.id)
    }))
  ];
}

function locatePlannerTask(raw: JsonObject): PlannerTaskLocation {
  const itemID = cleanDailyText(raw.itemID ?? raw.dailyItemID ?? raw.id);
  const query = cleanDailyText(
    raw.query
      ?? raw.oldTitle
      ?? raw.currentTitle
      ?? raw.existingTitle
      ?? raw.text
      ?? raw.task
      ?? raw.title
  );
  if (!itemID && !query) throw new Error("Which existing task should I update?");
  const containers = plannerTaskContainers(raw).map((container) => ({
    ...container,
    items: parseDailyItemsFromMarkdown(container.id, container.detail.markdown)
  }));
  const candidates = containers.flatMap((container) => container.items.map((item) => ({ container, item })));
  const matches = itemID
    ? candidates.filter((candidate) => candidate.item.id === itemID)
    : (() => {
      const wanted = query.toLowerCase();
      const exact = candidates.filter(({ item }) => {
        return dailyItemVisibleTitle(item).toLowerCase() === wanted
          || cleanDailyText(item.title).toLowerCase() === wanted;
      });
      if (exact.length) return exact;
      return candidates.filter(({ item }) => dailyItemVisibleTitle(item).toLowerCase().includes(wanted));
    })();

  if (matches.length > 1) {
    const names = matches.map(({ container, item }) => `${dailyItemVisibleTitle(item)} (${container.id})`).join("; ");
    throw new Error(`"${query || itemID}" matches more than one task (${names}). Please say the exact task or date.`);
  }
  const match = matches[0];
  if (!match) {
    const searched = containers.length === 1 ? containers[0].id : "Backlog and all planner days";
    throw new Error(`No task matching "${query || itemID}" was found in ${searched}.`);
  }
  return {
    kind: match.container.kind,
    id: match.container.id,
    detail: match.container.detail,
    items: match.container.items,
    item: match.item
  };
}

function saveUpdatedPlannerTaskSource(location: PlannerTaskLocation, markdown: string) {
  if (location.kind === "backlog") {
    const backlog = savePlannerBacklog(markdown);
    emitPlannerBacklogChanged();
    return backlog;
  }
  const day = savePlannerDay(location.id, markdown);
  emitPlannerDayChanged(day.id);
  return day;
}

function updateDailyItemByText(input: unknown): DailyItemMutationResult | BacklogItemMutationResult {
  const raw = dailyItemJSON(input);
  const source = locatePlannerTask(raw);
  const sourceDayID = source.id;
  const itemID = cleanDailyText(raw.itemID ?? raw.dailyItemID ?? raw.id);
  const matchText = cleanDailyText(raw.query ?? raw.oldTitle ?? raw.currentTitle ?? raw.existingTitle ?? raw.text ?? raw.task);
  const match = source.item;

  // Strict target resolution: "tomorrow" now works, and an unresolvable date
  // throws instead of silently coercing the move target to today.
  const targetDayID = resolvePlannerDayIDForWrite(String(raw.targetDayID ?? raw.newDayID ?? raw.moveToDayID ?? ""), sourceDayID);
  const titleValue = cleanDailyText(raw.title);
  const nextTitle = cleanDailyText(raw.newTitle ?? raw.updatedTitle ?? raw.replacementTitle)
    || (matchText || itemID ? titleValue : "")
    || match.title;
  const resolvedLinks = resolveTaskLinkTargetsFromPayload(raw);
  const mergedLinks = normalizeDailyLinks([...match.links, ...resolvedLinks]);
  const rawWithLinks = resolvedLinks.length
    ? removeLinkedNoteNameListScope({ ...raw, links: mergedLinks }, mergedLinks)
    : raw;
  const rawForUpdate = { ...compactLinkedTaskDetails(rawWithLinks, mergedLinks) };
  // Reminder-only updates must not recategorize. Voice models routinely echo a
  // guessed area/category alongside reminderAt ("T-Mobile Business Internet" →
  // area:"Business") which silently relocated the task under another ###
  // heading. A category change only counts when the call carries an actual
  // organize signal (rename, list, section, tags, details) and no reminder.
  const hasReminderIntent = ["reminderAt", "dueAt", "notifyAt", "checked", "done", "status"]
    .some((key) => Object.prototype.hasOwnProperty.call(raw, key));
  const hasOrganizeIntent = ["newTitle", "updatedTitle", "replacementTitle", "section", "tags", "listName", "listID", "listId", "list", "projectID", "folderID", "clearList", "scopeTags", "detailsMarkdown"]
    .some((key) => Object.prototype.hasOwnProperty.call(raw, key));
  const incomingArea = cleanDailyText(raw.area ?? raw.category);
  if (hasReminderIntent && !hasOrganizeIntent && incomingArea && cleanDailyText(match.area) && incomingArea.toLowerCase() !== cleanDailyText(match.area).toLowerCase()) {
    bridgeDebugLog(`planner update: ignored category "${incomingArea}" on reminder/status-only update of "${dailyItemVisibleTitle(match)}" (kept "${match.area}")`);
    delete rawForUpdate.area;
    delete rawForUpdate.category;
  }
  const item = normalizeDailyItemInput({
    ...rawForUpdate,
    id: match.structured ? match.id : undefined,
    dayID: targetDayID,
    title: nextTitle
  }, match);

  if (targetDayID === sourceDayID) {
    const sourceMarkdown = match.structured
      ? source.detail.markdown
      : removePlainDailyItemLine(source.detail.markdown, match.id);
    const saved = saveUpdatedPlannerTaskSource(source, replaceStructuredDailyItem(sourceMarkdown, item));
    return source.kind === "backlog"
      ? backlogMutationResult(saved as PlannerBacklogDetail, item)
      : dailyMutationResult(saved as PlannerDayDetail, item);
  }

  const targetResult = targetDayID === plannerBacklogID
    ? appendMovedDailyItemToBacklog(item)
    : appendMovedDailyItemToDay(item, targetDayID);
  const nextSourceMarkdown = match.structured
    ? removeStructuredDailyItem(source.detail.markdown, match.id)
    : removePlainDailyItemLine(source.detail.markdown, match.id);
  if (nextSourceMarkdown !== source.detail.markdown) {
    saveUpdatedPlannerTaskSource(source, nextSourceMarkdown);
  }
  return targetResult;
}

function moveDailyItemToDay(dayID: string | undefined, itemID: string, targetDayID: string): DailyItemMutationResult {
  const sourceDayID = normalizePlannerDayID(dayID);
  const destinationDayID = resolvePlannerDayIDForWrite(targetDayID);
  if (!itemID.trim()) throw new Error("Daily item was not found.");
  const result = updateDailyItemByText({
    dayID: sourceDayID,
    itemID,
    targetDayID: destinationDayID
  });
  if ("day" in result) return result;
  throw new Error("The target must be a planner day.");
}

function deleteDailyItem(dayID: string | undefined, itemID: string): DailyItemMutationResult {
  const normalizedDayID = normalizePlannerDayID(dayID);
  const day = loadPlannerDay(normalizedDayID);
  const nextMarkdown = itemID.startsWith("plain:")
    ? removePlainDailyItemLine(day.markdown, itemID)
    : removeStructuredDailyItem(day.markdown, itemID);
  // Don't report success on a no-op delete: if nothing was removed the id/day was
  // wrong, so surface it instead of telling the model the task was deleted.
  if (nextMarkdown === day.markdown) {
    throw new Error(`No task matching "${itemID}" was found on ${day.id}, so nothing was deleted.`);
  }
  const savedDay = savePlannerDay(normalizedDayID, nextMarkdown);
  emitPlannerDayChanged(savedDay.id);
  return dailyMutationResult(savedDay, null);
}

function linkDailyItemNote(dayID: string | undefined, itemID: string, target: unknown): DailyItemMutationResult | BacklogItemMutationResult {
  const link = normalizeNoteLinkTarget(target);
  if (!link) throw new Error("Daily item link target is invalid.");
  if (String(dayID ?? "").trim().toLowerCase() === plannerBacklogID) {
    const backlog = loadPlannerBacklog();
    const existing = parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown).find((item) => item.id === itemID);
    if (!existing) return backlogMutationResult(backlog, null);
    const links = [...existing.links];
    if (!links.some((candidate) => noteLinkKey(candidate) === noteLinkKey(link))) links.push(link);
    return upsertBacklogItem({ ...existing, dayID: plannerBacklogID, links });
  }
  const normalizedDayID = normalizePlannerDayID(dayID);
  const day = loadPlannerDay(normalizedDayID);
  const existing = parseDailyItemsFromMarkdown(day.id, day.markdown).find((item) => item.id === itemID);
  if (!existing) return dailyMutationResult(day, null);
  const links = [...existing.links];
  if (!links.some((candidate) => noteLinkKey(candidate) === noteLinkKey(link))) links.push(link);
  return upsertDailyItem({ ...existing, dayID: normalizedDayID, links });
}

function listBacklogItems(): DailyItem[] {
  const backlog = loadPlannerBacklog();
  return parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown);
}

const plannerSmartListDefinitions = [
  {
    id: "today",
    title: "Today",
    subtitle: "Open items due today"
  },
  {
    id: "backlog",
    title: "Backlog",
    subtitle: "Open items without a date"
  },
  {
    id: "shopping",
    title: "Shopping",
    subtitle: "Items tagged Shopping"
  },
  {
    id: "errands",
    title: "Errands",
    subtitle: "Items tagged Errands"
  },
  {
    id: "waiting-for",
    title: "Waiting For",
    subtitle: "Items waiting on someone"
  },
  {
    id: "work-follow-ups",
    title: "Work Follow-ups",
    subtitle: "Work items tagged Follow-up"
  }
] as const;

function plannerSmartListDefinition(id: string) {
  const key = cleanDailyText(id).toLowerCase();
  return plannerSmartListDefinitions.find((list) => list.id === key) ?? plannerSmartListDefinitions[0];
}

function allPlannerSmartListItems() {
  const seen = new Set<string>();
  const items: DailyItem[] = [];
  const add = (item: DailyItem) => {
    if (item.checked || item.status === "done") return;
    const key = `${item.dayID}:${item.id}`;
    if (seen.has(key)) return;
    seen.add(key);
    items.push(item);
  };
  for (const item of listBacklogItems()) add(item);
  for (const day of listPlannerDays(3650, plannerDayID())) {
    for (const item of listDailyItems(day.id)) add(item);
  }
  return items.sort((left, right) => {
    const leftDay = left.dayID === plannerBacklogID ? "9999-99-99" : left.dayID;
    const rightDay = right.dayID === plannerBacklogID ? "9999-99-99" : right.dayID;
    return leftDay.localeCompare(rightDay) || left.order - right.order || left.title.localeCompare(right.title);
  });
}

function itemMatchesPlannerSmartList(item: DailyItem, smartListID: string) {
  switch (plannerSmartListDefinition(smartListID).id) {
    case "today":
      return item.dayID === plannerDayID();
    case "backlog":
      return item.dayID === plannerBacklogID;
    case "shopping":
      return dailyItemHasFreeTag(item, "Shopping");
    case "errands":
      return dailyItemHasFreeTag(item, "Errands");
    case "waiting-for":
      return dailyItemHasFreeTag(item, "Waiting For") || dailyItemHasFreeTag(item, "Waiting");
    case "work-follow-ups": {
      const isWork = normalizeDailyArea(item.area)?.toLowerCase() === "work";
      const hasFollowUpTag = dailyItemHasFreeTag(item, "Follow-up") || dailyItemHasFreeTag(item, "Follow-ups");
      const hasFollowUpSection = dailyFreeTagKey(item.section) === dailyFreeTagKey("Follow-ups");
      return isWork && (hasFollowUpTag || hasFollowUpSection);
    }
    default:
      return false;
  }
}

function listPlannerSmartListItems(smartListID: string) {
  const definition = plannerSmartListDefinition(smartListID);
  const items = allPlannerSmartListItems().filter((item) => itemMatchesPlannerSmartList(item, definition.id));
  return {
    ...definition,
    count: items.length,
    items
  };
}

function listPlannerSmartLists(): PlannerSmartListSummary[] {
  const items = allPlannerSmartListItems();
  return plannerSmartListDefinitions.map((definition) => ({
    ...definition,
    count: items.filter((item) => itemMatchesPlannerSmartList(item, definition.id)).length
  }));
}

const plannerReminderScanDays = 45;
const plannerReminderMaxTimerMs = 60_000;
let plannerReminderTimer: ReturnType<typeof setTimeout> | null = null;
let plannerReminderRefreshScheduled = false;
const plannerReminderInFlight = new Set<string>();

function plannerReminderLedgerPath() {
  return path.join(supportRoot(), "Planner", "reminder-deliveries.json");
}

function plannerReminderKey(item: DailyItem) {
  return `${item.dayID}:${item.id}:${item.reminderAt ?? ""}`;
}

function readPlannerReminderLedger() {
  return readJSON<Record<string, string>>(plannerReminderLedgerPath(), {});
}

function writePlannerReminderLedger(ledger: Record<string, string>) {
  writeJSON(plannerReminderLedgerPath(), ledger);
}

function plannerReminderItems() {
  const items: DailyItem[] = [];
  for (const item of listBacklogItems()) items.push(item);
  for (const day of listPlannerDays(plannerReminderScanDays, plannerDayID())) {
    for (const item of listDailyItems(day.id)) items.push(item);
  }
  return items.filter((item) => Boolean(item.reminderAt));
}

type PlannerReminderNativeResult = { shown: boolean; failure?: string };

let macNativeReminderSignatureTrusted: boolean | null = null;

function canUseMacNativeReminderNotifications() {
  if (process.platform !== "darwin") return true;
  if (macNativeReminderSignatureTrusted !== null) return macNativeReminderSignatureTrusted;
  try {
    const result = spawnSync("/usr/bin/codesign", ["-dv", "--verbose=4", app.getPath("exe")], {
      encoding: "utf8"
    });
    const details = `${result.stdout ?? ""}\n${result.stderr ?? ""}`;
    const teamIdentifier = details.match(/TeamIdentifier=([^\n\r]+)/)?.[1]?.trim();
    macNativeReminderSignatureTrusted = result.status === 0
      && Boolean(teamIdentifier)
      && teamIdentifier !== "not set"
      && !details.includes("Signature=adhoc");
  } catch {
    macNativeReminderSignatureTrusted = false;
  }
  return macNativeReminderSignatureTrusted;
}

function showPlannerReminderNotification(item: DailyItem): Promise<PlannerReminderNativeResult> {
  if (!canUseMacNativeReminderNotifications()) {
    return Promise.resolve({ shown: false, failure: "This Mac build is not signed for native notifications." });
  }
  if (!Notification.isSupported()) return Promise.resolve({ shown: false, failure: "Native notifications are unsupported." });
  const due = item.reminderAt ? new Date(item.reminderAt) : null;
  const dueText = due && Number.isFinite(due.getTime())
    ? due.toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" })
    : "";
  return new Promise((resolve) => {
    const notification = new Notification({
      title: "OpenAssist reminder",
      body: [dailyItemVisibleTitle(item), dueText].filter(Boolean).join("\n"),
      silent: false
    });
    let settled = false;
    const finish = (result: PlannerReminderNativeResult) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      resolve(result);
    };
    const timeout = setTimeout(() => finish({ shown: false, failure: "Native notification did not confirm delivery." }), 2_000);
    notification.once("show", () => finish({ shown: true }));
    notification.once("failed", (_event, error) => finish({ shown: false, failure: error || "Native notification failed." }));
    notification.on("click", () => {
      try {
        app.focus({ steal: true });
      } catch {
        app.focus();
      }
    });
    try {
      notification.show();
    } catch (error) {
      finish({ shown: false, failure: error instanceof Error ? error.message : String(error) });
    }
  });
}

async function runPlannerReminderScheduler() {
  plannerReminderTimer = null;
  const now = Date.now();
  const ledger = readPlannerReminderLedger();
  let ledgerChanged = false;
  let nextDueAt = Number.POSITIVE_INFINITY;

  for (const item of plannerReminderItems()) {
    if (!item.reminderAt || item.checked || item.status === "done") continue;
    const dueAt = Date.parse(item.reminderAt);
    if (!Number.isFinite(dueAt)) continue;
    const key = plannerReminderKey(item);
    // Delivery is device-local. A Mac notification must never suppress the
    // phone's independently scheduled alert (or another paired Mac).
    if (ledger[key] || plannerReminderInFlight.has(key)) continue;
    if (dueAt <= now) {
      plannerReminderInFlight.add(key);
      const deliveredAt = new Date().toISOString();
      try {
        const nativeResult = await showPlannerReminderNotification(item);
        if (!nativeResult.shown) {
          bridgeDebugLog(`Planner native reminder unavailable; using fallback: ${nativeResult.failure ?? "unknown error"}`);
          if (!emitPlannerReminderDue(item, nativeResult.failure)) continue;
        }
        ledger[key] = deliveredAt;
        ledgerChanged = true;
      } catch (error) {
        bridgeDebugLog(`Planner reminder notification failed: ${error instanceof Error ? error.message : String(error)}`);
      } finally {
        plannerReminderInFlight.delete(key);
      }
    } else {
      nextDueAt = Math.min(nextDueAt, dueAt);
    }
  }

  if (ledgerChanged) writePlannerReminderLedger(ledger);
  const delay = Number.isFinite(nextDueAt)
    ? Math.max(1_000, Math.min(plannerReminderMaxTimerMs, nextDueAt - Date.now()))
    : plannerReminderMaxTimerMs;
  plannerReminderTimer = setTimeout(() => { void runPlannerReminderScheduler(); }, delay);
}

function schedulePlannerReminderRefresh() {
  if (plannerReminderRefreshScheduled) return;
  plannerReminderRefreshScheduled = true;
  setTimeout(() => {
    plannerReminderRefreshScheduled = false;
    if (plannerReminderTimer) {
      clearTimeout(plannerReminderTimer);
      plannerReminderTimer = null;
    }
    void runPlannerReminderScheduler();
  }, 250);
}

function backlogMutationResult(
  backlog: PlannerBacklogDetail,
  item?: DailyItem | null,
  scheduledDay?: PlannerDayDetail,
  scheduledItems?: DailyItem[]
): BacklogItemMutationResult {
  const items = parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown);
  return {
    backlog,
    items,
    // A backlog upsert that scheduled the item onto a day persists it in the
    // day markdown, not the backlog — read back from both.
    item: readBackMutatedItem(item, items, scheduledItems),
    scheduledDay,
    scheduledItems
  };
}

function upsertBacklogItem(input: unknown): BacklogItemMutationResult {
  const raw = dailyItemJSON(input);
  const backlog = loadPlannerBacklog();
  const items = parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown);
  const rawID = cleanDailyText(raw.id);
  const existingByID = items.find((item) => item.id === rawID);
  const similarExisting = existingByID ? undefined : findSimilarDailyItem(items, raw);
  const existing = existingByID ?? similarExisting;
  const item = normalizeDailyItemInput(
    { ...(similarExisting ? mergedDuplicateDailyInput(raw, similarExisting) : raw), dayID: plannerBacklogID },
    existing
  );
  const sourceMarkdown = existing?.structured === false && existing.id
    ? removePlainDailyItemLine(backlog.markdown, existing.id)
    : backlog.markdown;
  const savedBacklog = savePlannerBacklog(replaceStructuredDailyItem(sourceMarkdown, item));
  emitPlannerBacklogChanged();
  return backlogMutationResult(savedBacklog, item);
}

function appendMovedDailyItemToBacklog(input: unknown): BacklogItemMutationResult {
  const backlog = loadPlannerBacklog();
  const existingItems = parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown);
  const raw = dailyItemJSON(input);
  const item = normalizeDailyItemInput({
    ...raw,
    id: raw.id && !String(raw.id).startsWith("plain:") ? raw.id : undefined,
    dayID: plannerBacklogID,
    order: existingItems.length
  });
  const savedBacklog = savePlannerBacklog(replaceStructuredDailyItem(backlog.markdown, item));
  emitPlannerBacklogChanged();
  return backlogMutationResult(savedBacklog, item);
}

function toggleBacklogItem(itemID: string, checked: boolean): BacklogItemMutationResult {
  const backlog = loadPlannerBacklog();
  const existing = parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown).find((item) => item.id === itemID);
  if (!existing) return backlogMutationResult(backlog, null);
  if (existing.structured) {
    const item = normalizeDailyItemInput({ ...existing, dayID: plannerBacklogID, checked, status: checked ? "done" : "todo" }, existing);
    const savedBacklog = savePlannerBacklog(replaceStructuredDailyItem(backlog.markdown, item));
    emitPlannerBacklogChanged();
    return backlogMutationResult(savedBacklog, item);
  }
  const savedBacklog = savePlannerBacklog(setPlainDailyItemChecked(backlog.markdown, itemID, checked));
  emitPlannerBacklogChanged();
  return backlogMutationResult(savedBacklog, { ...existing, checked, status: checked ? "done" : "todo" });
}

function deleteBacklogItem(itemID: string): BacklogItemMutationResult {
  const backlog = loadPlannerBacklog();
  const nextMarkdown = itemID.startsWith("plain:")
    ? removePlainDailyItemLine(backlog.markdown, itemID)
    : removeStructuredDailyItem(backlog.markdown, itemID);
  // Surface a no-op delete instead of reporting success on a wrong/stale id.
  if (nextMarkdown === backlog.markdown) {
    throw new Error(`No backlog item matching "${itemID}" was found, so nothing was deleted.`);
  }
  const savedBacklog = savePlannerBacklog(nextMarkdown);
  emitPlannerBacklogChanged();
  return backlogMutationResult(savedBacklog, null);
}

function moveDailyItemToBacklog(dayID: string | undefined, itemID: string): BacklogItemMutationResult {
  const normalizedDayID = normalizePlannerDayID(dayID);
  const day = loadPlannerDay(normalizedDayID);
  const existing = parseDailyItemsFromMarkdown(day.id, day.markdown).find((item) => item.id === itemID);
  if (!existing) {
    throw new Error(`No task matching "${itemID}" was found on ${day.id}, so nothing was moved to the backlog.`);
  }
  const title = dailyItemVisibleTitle(existing);
  const carriedDetails = [
    existing.detailsMarkdown,
    existing.checked ? `Follow-up from completed planner item on ${day.id}.` : `Moved from ${day.id}.`
  ].filter(Boolean).join("\n\n");
  const backlogResult = appendMovedDailyItemToBacklog({
    ...existing,
    dayID: plannerBacklogID,
    title,
    checked: false,
    status: "todo",
    detailsMarkdown: carriedDetails
  });
  const nextDayMarkdown = existing.id.startsWith("plain:")
    ? removePlainDailyItemLine(day.markdown, existing.id)
    : removeStructuredDailyItem(day.markdown, existing.id);
  const savedDay = savePlannerDay(day.id, nextDayMarkdown);
  emitPlannerDayChanged(savedDay.id);
  return {
    ...backlogResult,
    scheduledDay: savedDay,
    scheduledItems: parseDailyItemsFromMarkdown(savedDay.id, savedDay.markdown)
  };
}

// ---- End-of-day Daily Digest -------------------------------------------------
// The digest sends the day's tasks to the user's Codex subscription (same
// backend-api/codex/responses endpoint the screen analysis and note cleanup
// use) and gets back: a short narrative, wins, a per-leftover suggestion
// (tomorrow/backlog/keep/drop) and follow-ups inferred from DONE tasks whose
// outcome implies waiting on someone ("asked for status" → "check response").

type PlannerDigestLeftover = {
  itemID: string;
  title: string;
  suggestion: "tomorrow" | "backlog" | "keep" | "drop";
  reason: string;
};

type PlannerDigestFollowUp = {
  title: string;
  reason: string;
  sourceTitle: string;
  when: "tomorrow" | "backlog";
};

type PlannerDailyDigest = {
  ok: true;
  dayID: string;
  nextDayID: string;
  summary: string;
  wins: string[];
  stats: { total: number; done: number; open: number };
  leftovers: PlannerDigestLeftover[];
  followUps: PlannerDigestFollowUp[];
  tomorrowPreview: string[];
  openLoops: string[];
  generatedAt: string;
} | { ok: false; error: string };

function plannerNextDayID(dayID: string) {
  const date = new Date(`${normalizePlannerDayID(dayID)}T12:00:00`);
  date.setDate(date.getDate() + 1);
  const candidate = plannerDayID(date);
  // Wrapping up a past day must carry leftovers forward to a day that can
  // still be acted on — never to another day in the past.
  const today = plannerDayID();
  return candidate < today ? today : candidate;
}

function plannerDigestTaskPayload(item: DailyItem) {
  return {
    itemID: item.id,
    title: dailyItemVisibleTitle(item),
    done: item.checked || item.status === "done",
    category: item.area || undefined,
    list: item.projectName || item.folderName || undefined,
    details: item.detailsMarkdown || undefined,
    steps: item.steps.length
      ? item.steps.map((step) => `${step.checked ? "[x]" : "[ ]"} ${step.text}`)
      : undefined,
    reminderAt: item.reminderAt || undefined
  };
}

async function generatePlannerDailyDigest(rawDayID?: string): Promise<PlannerDailyDigest> {
  try {
    const dayID = normalizePlannerDayID(rawDayID);
    const nextDayID = plannerNextDayID(dayID);
    const items = listDailyItems(dayID);
    if (!items.length) {
      return { ok: false, error: "No tasks on this day yet — nothing to wrap up." };
    }
    const tomorrowItems = listDailyItems(nextDayID);
    const day = loadPlannerDay(dayID);
    const focusMatch = day.markdown.match(/^>\s*Focus:\s*(.+)$/m);
    const auth = await resolveCodexTranscriptionAuthContext();
    const settings = await loadSettings();
    const model = codexSafeModel(settings.model);
    const instructions = [
      "You are the OpenAssist end-of-day digest assistant.",
      "Return strict JSON only. No prose outside JSON.",
      "JSON shape: {\"summary\":\"...\",\"wins\":[\"...\"],\"leftovers\":[{\"itemID\":\"...\",\"suggestion\":\"tomorrow|backlog|keep|drop\",\"reason\":\"...\"}],\"followUps\":[{\"title\":\"...\",\"reason\":\"...\",\"sourceItemID\":\"...\",\"when\":\"tomorrow|backlog\"}]}.",
      "summary: 2-3 warm, factual sentences about how the day went. Mention the focus if one was set.",
      "wins: one short line per meaningful DONE task (max 5). Empty array if nothing was done.",
      "leftovers: EVERY task with done=false appears exactly once, using its exact itemID.",
      "leftover suggestions: 'tomorrow' for tasks that clearly should continue; 'backlog' for undated/someday work; 'keep' only when the task belongs to this specific day; 'drop' only for obvious duplicates or no-longer-relevant tasks. Give a short reason.",
      "followUps: look at DONE tasks whose outcome implies waiting on someone or something (asked, called, emailed, requested, submitted, ordered, reported, status inquiries). Propose ONE actionable follow-up task each, e.g. done 'Call T-Mobile to get router status' → 'Check T-Mobile response about router status'. Use when='tomorrow' unless it clearly has no urgency (then 'backlog').",
      "Never invent tasks unrelated to the provided data. Keep every string short and specific. No markdown syntax inside strings."
    ].join("\n");
    const userPayload = [
      `Planner day: ${dayID}`,
      focusMatch?.[1]?.trim() ? `Focus for the day: ${focusMatch[1].trim()}` : "No focus was set.",
      `Tomorrow (${nextDayID}) already has ${tomorrowItems.length} task(s).`,
      "",
      "Tasks (JSON):",
      JSON.stringify(items.map(plannerDigestTaskPayload), null, 2)
    ].join("\n");
    const payload: JsonObject = {
      model,
      store: false,
      stream: true,
      instructions,
      input: [
        { role: "system", content: [{ type: "input_text", text: instructions }] },
        { role: "user", content: [{ type: "input_text", text: userPayload }] }
      ],
      reasoning: { effort: "medium" }
    };
    const response = await fetchWithTimeout("https://chatgpt.com/backend-api/codex/responses", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${auth.token}`,
        "Content-Type": "application/json",
        "User-Agent": chatGPTWebUserAgent,
        "Origin": "https://chatgpt.com"
      },
      body: JSON.stringify(payload)
    }, 90000, "Codex daily digest request timed out.");
    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Codex API request failed: ${response.status} ${errorText}`);
    }
    const text = await readCodexResponsesText(response);
    const jsonText = text.replace(/^[\s\S]*?(\{[\s\S]*\})[\s\S]*?$/, "$1");
    const parsed = JSON.parse(jsonText) as JsonObject;
    const itemsByID = new Map(items.map((item) => [item.id, item]));
    const openItems = items.filter((item) => !item.checked && item.status !== "done");
    const seenLeftovers = new Set<string>();
    const leftovers: PlannerDigestLeftover[] = [];
    const rawLeftovers = Array.isArray(parsed.leftovers) ? parsed.leftovers : [];
    for (const raw of rawLeftovers) {
      const entry = jsonObject(raw);
      if (!entry) continue;
      const itemID = cleanDailyText(entry.itemID);
      const item = itemsByID.get(itemID);
      if (!item || item.checked || seenLeftovers.has(itemID)) continue;
      seenLeftovers.add(itemID);
      const suggestion = String(entry.suggestion ?? "").toLowerCase();
      leftovers.push({
        itemID,
        title: dailyItemVisibleTitle(item),
        suggestion: suggestion === "tomorrow" || suggestion === "backlog" || suggestion === "drop" ? suggestion : "keep",
        reason: cleanDailyText(entry.reason).slice(0, 160)
      });
    }
    // The model must not silently skip open tasks — anything it missed shows
    // up as a "keep" so the user still sees and decides on it.
    for (const item of openItems) {
      if (seenLeftovers.has(item.id)) continue;
      leftovers.push({ itemID: item.id, title: dailyItemVisibleTitle(item), suggestion: "keep", reason: "" });
    }
    const followUps: PlannerDigestFollowUp[] = [];
    const rawFollowUps = Array.isArray(parsed.followUps) ? parsed.followUps : [];
    for (const raw of rawFollowUps.slice(0, 8)) {
      const entry = jsonObject(raw);
      if (!entry) continue;
      const title = cleanDailyText(entry.title).slice(0, 140);
      if (!title) continue;
      const source = itemsByID.get(cleanDailyText(entry.sourceItemID));
      followUps.push({
        title,
        reason: cleanDailyText(entry.reason).slice(0, 160),
        sourceTitle: source ? dailyItemVisibleTitle(source) : "",
        when: String(entry.when ?? "").toLowerCase() === "backlog" ? "backlog" : "tomorrow"
      });
    }
    const doneCount = items.length - openItems.length;
    return {
      ok: true,
      dayID,
      nextDayID,
      summary: cleanDailyText(parsed.summary).slice(0, 600) || `You finished ${doneCount} of ${items.length} tasks today.`,
      wins: (Array.isArray(parsed.wins) ? parsed.wins : [])
        .map((win) => cleanDailyText(win).slice(0, 160))
        .filter(Boolean)
        .slice(0, 5),
      stats: { total: items.length, done: doneCount, open: openItems.length },
      leftovers,
      followUps,
      tomorrowPreview: tomorrowItems
        .filter((item) => !item.checked)
        .slice(0, 6)
        .map((item) => dailyItemVisibleTitle(item)),
      openLoops: listOpenLoopEntries(),
      generatedAt: new Date().toISOString()
    };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : String(error) };
  }
}

// Applies the user's confirmed digest plan: moves leftovers where they chose
// and creates accepted follow-up tasks. Every mutation reuses the existing
// planner functions so history/undo and change events behave normally.
async function applyPlannerDailyDigestPlan(rawPlan: unknown): Promise<{ ok: boolean; error?: string; moved: number; created: number }> {
  const plan = jsonObject(rawPlan) ?? {};
  const dayID = normalizePlannerDayID(cleanDailyText(plan.dayID));
  const nextDayID = plannerNextDayID(dayID);
  let moved = 0;
  let created = 0;
  const failures: string[] = [];
  const actions = Array.isArray(plan.leftovers) ? plan.leftovers : [];
  for (const raw of actions) {
    const entry = jsonObject(raw);
    if (!entry) continue;
    const itemID = cleanDailyText(entry.itemID);
    const action = String(entry.action ?? "").toLowerCase();
    if (!itemID || action === "keep" || !action) continue;
    try {
      if (action === "tomorrow") {
        moveDailyItemToDay(dayID, itemID, nextDayID);
        moved += 1;
      } else if (action === "backlog") {
        moveDailyItemToBacklog(dayID, itemID);
        moved += 1;
      } else if (action === "drop") {
        deleteDailyItem(dayID, itemID);
        moved += 1;
      }
    } catch (error) {
      failures.push(error instanceof Error ? error.message : String(error));
    }
  }
  const followUps = Array.isArray(plan.followUps) ? plan.followUps : [];
  for (const raw of followUps) {
    const entry = jsonObject(raw);
    if (!entry) continue;
    const title = cleanDailyText(entry.title);
    if (!title) continue;
    const details = [
      cleanDailyText(entry.reason),
      cleanDailyText(entry.sourceTitle) ? `Follow-up from "${cleanDailyText(entry.sourceTitle)}" (${dayID}).` : `Follow-up from ${dayID}.`
    ].filter(Boolean).join("\n");
    try {
      if (String(entry.when ?? "").toLowerCase() === "backlog") {
        upsertBacklogItem({ dayID: plannerBacklogID, title, detailsMarkdown: details, checked: false, status: "todo" });
      } else {
        upsertDailyItem({ dayID: nextDayID, title, detailsMarkdown: details, checked: false, status: "todo" });
      }
      created += 1;
    } catch (error) {
      failures.push(error instanceof Error ? error.message : String(error));
    }
  }
  return failures.length
    ? { ok: false, error: failures.join(" "), moved, created }
    : { ok: true, moved, created };
}

// ---- Live Voice session summaries -------------------------------------------
// A 3-5 bullet recap (decisions / actions / open items) written into the voice
// day-log thread's "Session Summary" note. Updated after each session ends and
// finalized when the day log rotates. Fire-and-forget: a failed summary must
// never block stopping a session or rotating the log.

const liveVoiceSummaryTimers = new Map<string, ReturnType<typeof setTimeout>>();
const liveVoiceSummaryDebounceMs = 8_000;
const liveVoiceSummaryMinUserTurns = 3;

function cancelQueuedLiveVoiceSummary(threadID: string) {
  const timer = liveVoiceSummaryTimers.get(threadID);
  if (!timer) return;
  clearTimeout(timer);
  liveVoiceSummaryTimers.delete(threadID);
}

function queueLiveVoiceSessionSummary(threadID: string) {
  if (!threadID.trim()) return;
  cancelQueuedLiveVoiceSummary(threadID);
  const timer = setTimeout(() => {
    liveVoiceSummaryTimers.delete(threadID);
    void generateLiveVoiceSessionSummary(threadID).catch((error) => {
      bridgeDebugLog(`[realtime.voice] session summary failed thread=${threadID}: ${error instanceof Error ? error.message : String(error)}`);
    });
  }, liveVoiceSummaryDebounceMs);
  liveVoiceSummaryTimers.set(threadID, timer);
}

function liveVoiceSummaryTranscriptPayload(threadID: string) {
  const snapshot = readConversationSnapshotWithHistory(threadID);
  const entries = (snapshot.transcript ?? [])
    .map((entry) => ({ role: entry.role, text: cleanDailyText(entry.text).slice(0, 500) }))
    .filter((entry) => entry.text);
  const userTurns = entries.filter((entry) => entry.role === "user" && entry.text.length >= 12).length;
  const lines: string[] = [];
  let budget = 8_000;
  for (const entry of entries.slice().reverse()) {
    const line = `${entry.role === "user" ? "User" : "Assistant"}: ${entry.text}`;
    if (budget - line.length < 0) break;
    budget -= line.length + 1;
    lines.unshift(line);
  }
  return { lines, userTurns };
}

async function generateLiveVoiceSessionSummary(threadID: string, options: { finalize?: boolean } = {}) {
  const { lines, userTurns } = liveVoiceSummaryTranscriptPayload(threadID);
  if (userTurns < liveVoiceSummaryMinUserTurns) {
    bridgeDebugLog(`[realtime.voice] session summary skipped thread=${threadID} userTurns=${userTurns}`);
    return;
  }
  const auth = await resolveCodexTranscriptionAuthContext();
  const settings = await loadSettings();
  const model = codexSafeModel(settings.model);
  const instructions = [
    "You summarize one day of a user's voice-assistant conversation.",
    "Return strict JSON only. No prose outside JSON.",
    "JSON shape: {\"decisions\":[\"...\"],\"actions\":[\"...\"],\"openItems\":[\"...\"]}.",
    "decisions: choices or conclusions the user made. actions: things the assistant actually did or changed. openItems: questions or work left unfinished.",
    "0-5 entries per list, each under 140 characters, plain factual language, no markdown."
  ].join("\n");
  const payload: JsonObject = {
    model,
    store: false,
    stream: true,
    instructions,
    input: [
      { role: "system", content: [{ type: "input_text", text: instructions }] },
      { role: "user", content: [{ type: "input_text", text: lines.join("\n") }] }
    ],
    reasoning: { effort: "low" }
  };
  const response = await fetchWithTimeout("https://chatgpt.com/backend-api/codex/responses", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${auth.token}`,
      "Content-Type": "application/json",
      "User-Agent": chatGPTWebUserAgent,
      "Origin": "https://chatgpt.com"
    },
    body: JSON.stringify(payload)
  }, 90000, "Codex session summary request timed out.");
  if (!response.ok) {
    throw new Error(`Codex API request failed: ${response.status} ${await response.text()}`);
  }
  const text = await readCodexResponsesText(response);
  const parsed = JSON.parse(text.replace(/^[\s\S]*?(\{[\s\S]*\})[\s\S]*?$/, "$1")) as JsonObject;
  const bulletList = (value: unknown) => (Array.isArray(value) ? value : [])
    .map((entry) => cleanDailyText(entry).slice(0, 160))
    .filter(Boolean)
    .slice(0, 5);
  const decisions = bulletList(parsed.decisions);
  const actions = bulletList(parsed.actions);
  const openItems = bulletList(parsed.openItems);
  if (!decisions.length && !actions.length && !openItems.length) return;
  const session = findSession(threadID);
  const dayLabel = session?.liveVoiceDayID ? liveVoiceArchivedTitle(String(session.liveVoiceDayID)).replace(/^Live Voice · /, "") : "";
  const header = options.finalize
    ? `_Final summary${dayLabel ? ` for ${dayLabel}` : ""}._`
    : `_Updated ${new Date().toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })}${dayLabel ? ` · ${dayLabel}` : ""}._`;
  const sectionOf = (title: string, bullets: string[]) =>
    bullets.length ? [`**${title}**`, ...bullets.map((line) => `- ${line}`)] : [];
  const content = [
    header,
    "",
    ...sectionOf("Decisions", decisions),
    ...sectionOf("Actions", actions),
    ...sectionOf("Open items", openItems)
  ].join("\n");
  const target = resolveCanonicalThreadReferenceNote(threadID, "Session Summary");
  const note = loadThreadReferenceNote(threadID, target.noteID);
  saveThreadNote(threadID, target.noteID, replaceMarkdownSection(note.markdown, "Summary", content));
  bridgeDebugLog(`[realtime.voice] session summary written thread=${threadID} finalize=${options.finalize === true}`);
}

// ---- Open Loops ledger -------------------------------------------------------
// One durable note ("Open Loops" under the "Assistant" planner list) holding a
// checkable line per unresolved delegated task, deep-linked to the day log it
// came from. This is the single "pick up later" surface; the day logs stay the
// detailed archive.

const openLoopsLedgerListTitle = "Assistant";
const openLoopsLedgerNoteTitle = "Open Loops";

function ensureOpenLoopsLedger() {
  const lists = loadProjects().plannerLists;
  const list = lists.find((entry) => (entry.title ?? "").trim().toLowerCase() === openLoopsLedgerListTitle.toLowerCase())
    ?? createPlannerList({ name: openLoopsLedgerListTitle }).list;
  return resolveCanonicalReferenceNote(list.id, openLoopsLedgerNoteTitle);
}

function appendOpenLoopEntry(entry: { description: string; state: string; voiceThreadID: string }) {
  try {
    const target = ensureOpenLoopsLedger();
    if (target.kind !== "project") return;
    const note = loadNote(target.projectID, target.noteID);
    const description = cleanDailyText(entry.description).slice(0, 120) || "Delegated voice task";
    const dateLabel = new Date().toLocaleDateString(undefined, { month: "short", day: "numeric" });
    const line = `- [ ] ${description} (${entry.state}) — ${dateLabel} ([day log](${buildThreadURL(entry.voiceThreadID)}))`;
    const next = appendReferenceLinesToMarkdown(note.markdown, "Open", [line]);
    if (next !== note.markdown.replace(/\r\n/g, "\n")) {
      saveProjectNote(target.projectID, target.noteID, next);
      bridgeDebugLog(`[realtime.voice] open loop recorded state=${entry.state} thread=${entry.voiceThreadID}`);
    }
  } catch (error) {
    bridgeDebugLog(`[realtime.voice] open loop append failed: ${error instanceof Error ? error.message : String(error)}`);
  }
}

// Unchecked ledger lines, for the daily digest's read-only "unresolved agent
// tasks" block. Parsed straight from the note; no model involved.
function listOpenLoopEntries(limit = 10) {
  try {
    const lists = loadProjects().plannerLists;
    const list = lists.find((entry) => (entry.title ?? "").trim().toLowerCase() === openLoopsLedgerListTitle.toLowerCase());
    if (!list) return [];
    const existing = findProjectNoteByTitle(list.id, canonicalReferenceNoteCandidates(openLoopsLedgerNoteTitle));
    if (!existing?.id) return [];
    const note = loadNote(list.id, String(existing.id));
    return markdownSection(note.markdown, "Open")
      .split("\n")
      .filter((line) => /^\s*[-*]\s*\[ \]\s+/.test(line))
      .map((line) => cleanDailyText(line.replace(/^\s*[-*]\s*\[ \]\s+/, "").replace(/\(\[day log\]\([^)]*\)\)/, "")).trim())
      .filter(Boolean)
      .slice(0, limit);
  } catch {
    return [];
  }
}

function scheduledBacklogDetailsForDay(detailsMarkdown: string, targetDayID: string) {
  const normalizedTarget = normalizePlannerDayID(targetDayID);
  return String(detailsMarkdown ?? "")
    .replace(/\r\n/g, "\n")
    .split("\n")
    .filter((line) => {
      const text = cleanDailyText(line);
      return text !== `Moved from ${normalizedTarget}.`
        && text !== `Follow-up from completed planner item on ${normalizedTarget}.`;
    })
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function scheduleBacklogItem(itemID: string, targetDayID: string): BacklogItemMutationResult {
  const normalizedDayID = resolvePlannerDayIDForWrite(targetDayID);
  const backlog = loadPlannerBacklog();
  const existing = parseDailyItemsFromMarkdown(plannerBacklogID, backlog.markdown).find((item) => item.id === itemID);
  if (!existing) {
    throw new Error(`No backlog item matching "${itemID}" was found, so nothing was scheduled.`);
  }
  const scheduled = appendMovedDailyItemToDay({
    ...existing,
    dayID: normalizedDayID,
    checked: false,
    status: "todo",
    title: dailyItemVisibleTitle(existing),
    detailsMarkdown: scheduledBacklogDetailsForDay(existing.detailsMarkdown, normalizedDayID)
  }, normalizedDayID);
  const savedBacklog = savePlannerBacklog(
    existing.id.startsWith("plain:")
      ? removePlainDailyItemLine(backlog.markdown, existing.id)
      : removeStructuredDailyItem(backlog.markdown, existing.id)
  );
  emitPlannerBacklogChanged();
  return backlogMutationResult(savedBacklog, null, scheduled.day, scheduled.items);
}

function scheduleSelectionToPlanner(request: PlannerScheduleRequest): PlannerDayDetail {
  const mode = request.mode === "move" || request.mode === "link" ? request.mode : "copy";
  const targetDayID = normalizePlannerDayID(request.targetDayID);
  const day = loadPlannerDay(targetDayID);
  const selectedText = String(request.selectedText ?? "").trim();
  if (mode === "link" && request.sourceTarget) {
    return upsertDailyItem({
      dayID: targetDayID,
      title: request.sourceTitle || selectedText || "Linked note",
      detailsMarkdown: selectedText,
      links: [request.sourceTarget],
      status: "todo",
      checked: false
    }).day;
  }
  const content = mode === "link" && request.sourceTarget
    ? `- ${markdownLinkForTarget(request.sourceTitle, request.sourceTarget)}`
    : selectedText;
  if (!content.trim()) return day;
  const section = plannerSectionFor(mode, content);
  const metadata = plannerMetadataComment(request, mode);
  const block = `${content}\n${metadata}`;
  return savePlannerDay(targetDayID, appendToPlannerSection(day.markdown, section, block));
}

function loadThreadMemory(threadID: string) {
  const memoryPath = path.join(supportRoot(), "AssistantMemory", threadID, "memory.md");
  const exists = fs.existsSync(memoryPath);
  const agentFilesPath = threadAgentFilesDisplayPath(threadID);
  const session = findSession(threadID);
  const linkedFolderPath = normalizeLinkedFolderPath(session?.linkedProjectFolderPath);
  const agentFilesSection = [
    "## Agent Files",
    "",
    `Generated files for this thread should be saved in \`${agentFilesPath}\`.`,
    linkedFolderPath
      ? `Linked workspace for read/context: \`${linkedFolderPath}\`. Only write there when the user clearly asks.`
      : "No linked workspace is attached."
  ].join("\n");
  const memoryMarkdown = exists ? fs.readFileSync(memoryPath, "utf8").replace(/\r\n/g, "\n").trim() : "";
  return {
    threadID,
    exists,
    path: exists ? memoryPath : undefined,
    markdown: [memoryMarkdown, agentFilesSection].filter(Boolean).join("\n\n")
  };
}

// ---------------------------------------------------------------------------
// Assistant memory store (global, file-based — modeled on Claude Code's local
// memory): one durable fact per markdown file with frontmatter, plus a compact
// MEMORY.md index (one line per memory) that is cheap enough to inject into
// session-start instructions. Session digests (Codex-style rollout summaries)
// live under Memory/sessions/. See docs/plan: context diet + memory.
// ---------------------------------------------------------------------------

const assistantMemoryTypes = ["user", "project", "preference", "reference"] as const;
type AssistantMemoryType = (typeof assistantMemoryTypes)[number];

function memoryStoreRoot() {
  return path.join(supportRoot(), "Memory");
}

function memorySessionsRoot() {
  return path.join(memoryStoreRoot(), "sessions");
}

function memoryIndexPath() {
  return path.join(memoryStoreRoot(), "MEMORY.md");
}

function memorySlug(name: string) {
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
  return slug || "memory";
}

function normalizeAssistantMemoryType(value: unknown): AssistantMemoryType {
  const lowered = String(value ?? "").trim().toLowerCase();
  return (assistantMemoryTypes as readonly string[]).includes(lowered) ? lowered as AssistantMemoryType : "user";
}

function memoryFrontmatterEscape(value: string) {
  return value.replace(/\r?\n/g, " ").replace(/"/g, "'").trim();
}

function parseAssistantMemoryFile(filePath: string) {
  const raw = fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n");
  const match = raw.match(/^---\n([\s\S]*?)\n---\n?/);
  const frontmatter: Record<string, string> = {};
  if (match) {
    for (const line of match[1].split("\n")) {
      const separator = line.indexOf(":");
      if (separator <= 0) continue;
      frontmatter[line.slice(0, separator).trim()] = line.slice(separator + 1).trim().replace(/^"|"$/g, "");
    }
  }
  return {
    slug: path.basename(filePath, ".md"),
    name: frontmatter.name || path.basename(filePath, ".md"),
    description: frontmatter.description || "",
    type: normalizeAssistantMemoryType(frontmatter.type),
    originThreadID: frontmatter.originThreadID || undefined,
    updatedAt: frontmatter.updatedAt || undefined,
    content: match ? raw.slice(match[0].length).trim() : raw.trim()
  };
}

function listAssistantMemories() {
  const root = memoryStoreRoot();
  if (!fs.existsSync(root)) return [];
  return fs.readdirSync(root)
    .filter((entry) => entry.endsWith(".md") && entry !== "MEMORY.md")
    .map((entry) => {
      try {
        return parseAssistantMemoryFile(path.join(root, entry));
      } catch {
        return null;
      }
    })
    .filter((memory): memory is NonNullable<typeof memory> => Boolean(memory))
    .sort((left, right) => String(left.name).localeCompare(String(right.name)));
}

function rewriteAssistantMemoryIndex() {
  const memories = listAssistantMemories();
  const lines = memories.map((memory) =>
    `- [${memoryFrontmatterEscape(memory.name)}](${memory.slug}.md) — ${memoryFrontmatterEscape(memory.description)}`
  );
  fs.mkdirSync(memoryStoreRoot(), { recursive: true });
  fs.writeFileSync(memoryIndexPath(), lines.length ? `${lines.join("\n")}\n` : "", "utf8");
  return memories.length;
}

function saveAssistantMemory(input: {
  name: string;
  description: string;
  content: string;
  type?: string;
  originThreadID?: string;
}) {
  const name = input.name.trim();
  const description = input.description.trim();
  const content = input.content.trim();
  if (!name) throw new Error("Memory name is required.");
  if (!description) throw new Error("Memory description is required.");
  if (!content) throw new Error("Memory content is required.");
  const slug = memorySlug(name);
  const filePath = path.join(memoryStoreRoot(), `${slug}.md`);
  const existed = fs.existsSync(filePath);
  const existing = existed ? parseAssistantMemoryFile(filePath) : null;
  const frontmatter = [
    "---",
    `name: ${memoryFrontmatterEscape(name)}`,
    `description: ${memoryFrontmatterEscape(description)}`,
    `type: ${normalizeAssistantMemoryType(input.type)}`,
    ...(input.originThreadID?.trim() || existing?.originThreadID
      ? [`originThreadID: ${input.originThreadID?.trim() || existing?.originThreadID}`]
      : []),
    `updatedAt: ${new Date().toISOString()}`,
    "---"
  ].join("\n");
  fs.mkdirSync(memoryStoreRoot(), { recursive: true });
  fs.writeFileSync(filePath, `${frontmatter}\n\n${content}\n`, "utf8");
  rewriteAssistantMemoryIndex();
  return { slug, path: filePath, updated: existed };
}

function readAssistantMemory(nameOrSlug: string) {
  const slug = memorySlug(nameOrSlug);
  const filePath = path.join(memoryStoreRoot(), `${slug}.md`);
  if (!fs.existsSync(filePath)) return null;
  return parseAssistantMemoryFile(filePath);
}

function deleteAssistantMemory(nameOrSlug: string) {
  const slug = memorySlug(nameOrSlug);
  const filePath = path.join(memoryStoreRoot(), `${slug}.md`);
  if (!fs.existsSync(filePath)) return false;
  fs.rmSync(filePath, { force: true });
  rewriteAssistantMemoryIndex();
  return true;
}

// Compact index for prompt injection. Truncated on a line boundary so a large
// memory set cannot bloat session-start instructions past ~maxChars.
function readAssistantMemoryIndex(maxChars = 2000) {
  const indexPath = memoryIndexPath();
  if (!fs.existsSync(indexPath)) return "";
  const raw = fs.readFileSync(indexPath, "utf8").trim();
  if (raw.length <= maxChars) return raw;
  const lines = raw.split("\n");
  const kept: string[] = [];
  let used = 0;
  for (const line of lines) {
    if (used + line.length + 1 > maxChars) break;
    kept.push(line);
    used += line.length + 1;
  }
  return `${kept.join("\n")}\n…(${lines.length - kept.length} more memories — use oa_memory_list)`;
}

// Codex-style automatic session summaries, kept deterministic (no model
// calls): one digest file per thread per day with a one-line entry per turn.
// Cheap to write, indexed into the recall timeline, and survives thread
// deletion — "what did we work on Tuesday?" stays answerable.
const sessionDigestMaxTurnLines = 40;

function compactDigestText(value: string, maxChars: number) {
  return value.replace(/\s+/g, " ").trim().slice(0, maxChars);
}

function appendSessionDigest(input: {
  threadID: string;
  title: string;
  backend: string;
  prompt: string;
  responseText: string;
}) {
  try {
    const now = new Date();
    const dayID = plannerDayID();
    const fileName = `${dayID}-${input.threadID.slice(-8)}.md`;
    const filePath = path.join(memorySessionsRoot(), fileName);
    fs.mkdirSync(memorySessionsRoot(), { recursive: true });
    const header = [
      `# ${compactDigestText(input.title || "Chat session", 120)}`,
      "",
      `Thread: ${input.threadID}`,
      `Date: ${dayID}`,
      `Provider: ${input.backend}`,
      ""
    ].join("\n");
    const existing = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8") : "";
    const time = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
    const entry = `- ${time} · user: ${compactDigestText(input.prompt, 150)} → assistant: ${compactDigestText(input.responseText, 200)}`;
    const bodyLines = existing
      ? existing.split("\n").filter((line) => line.startsWith("- "))
      : [];
    bodyLines.push(entry);
    const kept = bodyLines.slice(-sessionDigestMaxTurnLines);
    fs.writeFileSync(filePath, `${header}${kept.join("\n")}\n`, "utf8");
  } catch (error) {
    bridgeDebugLog(`session digest write failed thread=${input.threadID}: ${error instanceof Error ? error.message : String(error)}`);
  }
}

function conversationSnapshotPath(threadID: string) {
  return path.join(conversationStoreRoot(), threadID, "conversation.json");
}

function codeTrackingStatePath(threadID: string) {
  return path.join(conversationStoreRoot(), threadID, "code-tracking.json");
}

function emptyCodeTrackingState(threadID: string): CodeTrackingState {
  return {
    sessionID: threadID,
    availability: "unavailable",
    checkpoints: [],
    currentCheckpointPosition: -1
  };
}

function readCodeTrackingState(threadID: string): CodeTrackingState {
  const snapshot = readJSON<Partial<CodeTrackingState>>(codeTrackingStatePath(threadID), emptyCodeTrackingState(threadID));
  return {
    sessionID: String(snapshot.sessionID || threadID),
    availability: snapshot.availability === "available" || snapshot.availability === "error" ? snapshot.availability : "unavailable",
    repoRootPath: typeof snapshot.repoRootPath === "string" ? snapshot.repoRootPath : undefined,
    repoLabel: typeof snapshot.repoLabel === "string" ? snapshot.repoLabel : undefined,
    checkpoints: Array.isArray(snapshot.checkpoints) ? snapshot.checkpoints as CodeCheckpointSummary[] : [],
    currentCheckpointPosition: typeof snapshot.currentCheckpointPosition === "number" && Number.isFinite(snapshot.currentCheckpointPosition)
      ? Number(snapshot.currentCheckpointPosition)
      : -1,
    errorMessage: typeof snapshot.errorMessage === "string" ? snapshot.errorMessage : undefined
  };
}

function writeCodeTrackingState(state: CodeTrackingState) {
  writeJSON(codeTrackingStatePath(state.sessionID), {
    version: 1,
    ...state
  });
}

function readConversationSnapshot(threadID: string) {
  return readJSON<{
    version?: number;
    threadID?: string;
    timeline?: JsonObject[];
    transcript?: JsonObject[];
    turns?: JsonObject[];
    updatedAt?: number;
    lastAppliedEventSequence?: number;
  }>(conversationSnapshotPath(threadID), {
    version: 2,
    threadID,
    timeline: [],
    transcript: [],
    turns: [],
    updatedAt: currentSwiftDate(),
    lastAppliedEventSequence: 0
  });
}

function readConversationSnapshotWithHistory(threadID: string) {
  const current = readConversationSnapshot(threadID);
  const directory = path.dirname(conversationSnapshotPath(threadID));
  const segments = readConversationHistorySegments(directory);
  return segments.length
    ? mergeConversationHistorySnapshots([...segments, current])
    : current;
}

function writeConversationSnapshot(threadID: string, snapshot: JsonObject) {
  writeJSON(conversationSnapshotPath(threadID), {
    version: 2,
    threadID,
    timeline: [],
    transcript: [],
    turns: [],
    lastAppliedEventSequence: 0,
    ...snapshot,
    updatedAt: currentSwiftDate()
  });
}

function clampCodeTrackingState(state: CodeTrackingState): CodeTrackingState {
  const maxPosition = state.checkpoints.length - 1;
  const currentCheckpointPosition = state.checkpoints.length
    ? Math.max(-1, Math.min(state.currentCheckpointPosition, maxPosition))
    : -1;
  return {
    ...state,
    currentCheckpointPosition
  };
}

function saveCodeTrackingState(state: CodeTrackingState) {
  const normalized = clampCodeTrackingState(state);
  writeCodeTrackingState(normalized);
  return normalized;
}

async function repositoryForTrackedCode(threadID: string, fallbackState?: CodeTrackingState): Promise<GitCheckpointRepositoryContext | null> {
  const session = findSession(threadID);
  const cwd = sessionWorkingDirectory(session)?.trim() || fallbackState?.repoRootPath?.trim();
  if (!cwd) return null;
  return gitCheckpointService.repositoryContext(cwd);
}

async function loadCodeTrackingState(threadID: string): Promise<CodeTrackingState> {
  let state = readCodeTrackingState(threadID);
  const repository = await repositoryForTrackedCode(threadID, state);
  if (!repository) {
    state = saveCodeTrackingState({
      ...state,
      availability: "unavailable",
      repoRootPath: undefined,
      repoLabel: undefined
    });
    return state;
  }

  state = {
    ...state,
    availability: "available",
    repoRootPath: repository.rootPath,
    repoLabel: repository.label
  };

  state = await recoverIncompleteTrackedCodeCheckpoints(threadID, repository, state);
  return saveCodeTrackingState(state);
}

async function recoverIncompleteTrackedCodeCheckpoints(
  threadID: string,
  repository: GitCheckpointRepositoryContext,
  state: CodeTrackingState
): Promise<CodeTrackingState> {
  const existingIDs = new Set(state.checkpoints.map((checkpoint) => checkpoint.id));
  const storedRefs = await gitCheckpointService.storedCheckpointRefs(repository, threadID);
  let nextState = state;
  for (const refState of storedRefs) {
    if (existingIDs.has(refState.checkpointID)) continue;
    if (!refState.hasBeforeWorktreeRef || !refState.hasBeforeIndexRef) continue;
    try {
      const beforeSnapshot = await gitCheckpointService.loadSnapshot(repository, threadID, refState.checkpointID, "before");
      if (!beforeSnapshot) continue;
      const afterSnapshot = refState.hasAfterWorktreeRef && refState.hasAfterIndexRef
        ? await gitCheckpointService.loadSnapshot(repository, threadID, refState.checkpointID, "after")
        : await gitCheckpointService.captureSnapshot(repository, threadID, refState.checkpointID, "after");
      if (!afterSnapshot) continue;
      const capture = await gitCheckpointService.buildCaptureResult(repository, beforeSnapshot, afterSnapshot);
      if (!capture.changedFiles.length) {
        await gitCheckpointService.deleteRefs(repository.rootPath, [
          beforeSnapshot.worktreeRef,
          beforeSnapshot.indexRef,
          afterSnapshot.worktreeRef,
          afterSnapshot.indexRef
        ]);
        continue;
      }
      const checkpoint: CodeCheckpointSummary = {
        id: refState.checkpointID,
        checkpointNumber: nextState.checkpoints.length + 1,
        createdAt: currentSwiftDate(),
        turnStatus: "completed",
        summary: capture.summary,
        patch: capture.patch,
        changedFiles: capture.changedFiles,
        ignoredTouchedPaths: capture.ignoredTouchedPaths,
        beforeSnapshot,
        afterSnapshot
      };
      nextState = {
        ...nextState,
        checkpoints: [...nextState.checkpoints, checkpoint],
        currentCheckpointPosition: nextState.checkpoints.length
      };
      existingIDs.add(refState.checkpointID);
      bridgeDebugLog(`recovered Electron code checkpoint threadID=${threadID} checkpointID=${refState.checkpointID}`);
    } catch (error) {
      bridgeDebugLog(`failed to recover Electron code checkpoint threadID=${threadID} checkpointID=${refState.checkpointID} error=${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return nextState;
}

async function beginTrackedCodeCheckpointIfNeeded(
  threadID: string,
  interactionMode: string | undefined,
  settings: SettingsSnapshot
) {
  if (!settings.assistantTrackCodeChangesInGitRepos) return;
  if (normalizeCodexInteractionMode(interactionMode) !== "agentic") return;
  if (pendingCodeCheckpointBaselinesBySessionID.has(threadID)) return;
  const repository = await repositoryForTrackedCode(threadID);
  if (!repository) {
    saveCodeTrackingState({
      ...readCodeTrackingState(threadID),
      sessionID: threadID,
      availability: "unavailable",
      repoRootPath: undefined,
      repoLabel: undefined
    });
    return;
  }
  const checkpointID = randomUUID().toLowerCase();
  try {
    const beforeSnapshot = await gitCheckpointService.captureSnapshot(repository, threadID, checkpointID, "before");
    pendingCodeCheckpointBaselinesBySessionID.set(threadID, {
      sessionID: threadID,
      checkpointID,
      repository,
      beforeSnapshot,
      startedAt: currentSwiftDate()
    });
    saveCodeTrackingState({
      ...readCodeTrackingState(threadID),
      sessionID: threadID,
      availability: "available",
      repoRootPath: repository.rootPath,
      repoLabel: repository.label
    });
    bridgeDebugLog(`started Electron code checkpoint threadID=${threadID} checkpointID=${checkpointID}`);
  } catch (error) {
    saveCodeTrackingState({
      ...readCodeTrackingState(threadID),
      sessionID: threadID,
      availability: "error",
      repoRootPath: repository.rootPath,
      repoLabel: repository.label,
      errorMessage: error instanceof Error ? error.message : String(error)
    });
    bridgeDebugLog(`failed to start Electron code checkpoint threadID=${threadID} error=${error instanceof Error ? error.message : String(error)}`);
  }
}

async function finalizeTrackedCodeCheckpointIfNeeded(options: {
  threadID: string;
  turnID?: string;
  assistantMessageID?: string;
  userMessageID?: string;
  turnStatus: CodeCheckpointTurnStatus;
}) {
  const baseline = pendingCodeCheckpointBaselinesBySessionID.get(options.threadID);
  if (!baseline) return undefined;
  pendingCodeCheckpointBaselinesBySessionID.delete(options.threadID);
  try {
    const afterSnapshot = await gitCheckpointService.captureSnapshot(
      baseline.repository,
      options.threadID,
      baseline.checkpointID,
      "after"
    );
    const capture = await gitCheckpointService.buildCaptureResult(
      baseline.repository,
      baseline.beforeSnapshot,
      afterSnapshot
    );
    if (!capture.changedFiles.length) {
      await gitCheckpointService.deleteRefs(baseline.repository.rootPath, [
        baseline.beforeSnapshot.worktreeRef,
        baseline.beforeSnapshot.indexRef,
        afterSnapshot.worktreeRef,
        afterSnapshot.indexRef
      ]);
      await loadCodeTrackingState(options.threadID);
      return undefined;
    }
    const state = await loadCodeTrackingState(options.threadID);
    const retainedCheckpoints = state.checkpoints.slice(0, Math.max(0, state.currentCheckpointPosition + 1));
    const checkpoint: CodeCheckpointSummary = {
      id: baseline.checkpointID,
      checkpointNumber: retainedCheckpoints.length + 1,
      createdAt: currentSwiftDate(),
      turnStatus: options.turnStatus,
      summary: capture.summary,
      patch: capture.patch,
      changedFiles: capture.changedFiles,
      ignoredTouchedPaths: capture.ignoredTouchedPaths,
      beforeSnapshot: baseline.beforeSnapshot,
      afterSnapshot,
      associatedMessageID: options.assistantMessageID,
      associatedTurnID: options.turnID,
      associatedUserMessageID: options.userMessageID
    };
    const nextState = saveCodeTrackingState({
      ...state,
      availability: "available",
      repoRootPath: baseline.repository.rootPath,
      repoLabel: baseline.repository.label,
      checkpoints: [...retainedCheckpoints, checkpoint],
      currentCheckpointPosition: retainedCheckpoints.length
    });
    bridgeDebugLog(`finalized Electron code checkpoint threadID=${options.threadID} checkpointID=${checkpoint.id} files=${checkpoint.changedFiles.length}`);
    return { checkpoint, state: nextState };
  } catch (error) {
    saveCodeTrackingState({
      ...readCodeTrackingState(options.threadID),
      sessionID: options.threadID,
      availability: "error",
      repoRootPath: baseline.repository.rootPath,
      repoLabel: baseline.repository.label,
      errorMessage: error instanceof Error ? error.message : String(error)
    });
    bridgeDebugLog(`failed to finalize Electron code checkpoint threadID=${options.threadID} checkpointID=${baseline.checkpointID} error=${error instanceof Error ? error.message : String(error)}`);
    return undefined;
  }
}

function checkpointInfoFor(checkpoint: CodeCheckpointSummary, state: CodeTrackingState): MessageCheckpointInfo {
  const checkpointIndex = Math.max(0, state.checkpoints.findIndex((item) => item.id === checkpoint.id));
  return {
    checkpoint,
    checkpointIndex,
    currentCheckpointPosition: state.currentCheckpointPosition,
    totalCheckpointCount: state.checkpoints.length,
    hasActiveTurn: false,
    actionsLocked: false,
    futureTurnsHidden: checkpointIndex > state.currentCheckpointPosition
  };
}

function attachCodeCheckpointInfo(messages: ChatMessage[], state: CodeTrackingState) {
  if (state.availability !== "available" || !state.checkpoints.length) return messages;
  const byID = new Map(messages.map((message) => [message.id, message]));
  for (let index = 0; index < state.checkpoints.length; index += 1) {
    const checkpoint = state.checkpoints[index];
    if (!checkpoint) continue;
    let target = checkpoint.associatedMessageID ? byID.get(checkpoint.associatedMessageID) : undefined;
    if (!target && checkpoint.associatedTurnID) {
      target = messages.find((message) =>
        message.role === "assistant" && message.turnID === checkpoint.associatedTurnID
      );
    }
    if (!target) {
      const checkpointCreatedAtMs = swiftDateToMs(checkpoint.createdAt) ?? Date.now();
      target = [...messages]
        .reverse()
        .find((message) => message.role === "assistant" && (message.createdAt ?? 0) <= checkpointCreatedAtMs);
    }
    if (!target || target.role !== "assistant") continue;
    target.checkpointInfo = {
      checkpoint,
      checkpointIndex: index,
      currentCheckpointPosition: state.currentCheckpointPosition,
      totalCheckpointCount: state.checkpoints.length,
      hasActiveTurn: false,
      actionsLocked: false,
      futureTurnsHidden: index > state.currentCheckpointPosition
    };
  }
  return messages;
}

async function openCodeReview(threadID: string, checkpointID?: string): Promise<CodeReviewPanelState | null> {
  const state = await loadCodeTrackingState(threadID);
  if (state.availability !== "available" || !state.repoRootPath || !state.repoLabel || !state.checkpoints.length) {
    return null;
  }
  const selectedCheckpointID = checkpointID && state.checkpoints.some((checkpoint) => checkpoint.id === checkpointID)
    ? checkpointID
    : state.checkpoints[Math.max(0, state.currentCheckpointPosition)]?.id ?? state.checkpoints.at(-1)?.id ?? "";
  if (!selectedCheckpointID) return null;
  return {
    sessionID: threadID,
    repoRootPath: state.repoRootPath,
    repoLabel: state.repoLabel,
    checkpoints: state.checkpoints,
    currentCheckpointPosition: state.currentCheckpointPosition,
    selectedCheckpointID,
    hasActiveTurn: pendingCodeCheckpointBaselinesBySessionID.has(threadID),
    actionsLocked: false
  };
}

async function restoreCodeCheckpoint(threadID: string, checkpointID: string) {
  const state = await loadCodeTrackingState(threadID);
  const repository = await repositoryForTrackedCode(threadID, state);
  if (!repository) throw new Error("Open Assist could not find a Git repository for this chat.");
  const checkpointIndex = state.checkpoints.findIndex((checkpoint) => checkpoint.id === checkpointID);
  if (checkpointIndex < 0) throw new Error("Open Assist could not find that saved checkpoint.");
  const checkpoint = state.checkpoints[checkpointIndex];
  const isUndo = checkpointIndex === state.currentCheckpointPosition;
  const isRedo = checkpointIndex === state.currentCheckpointPosition + 1;
  if (!isUndo && !isRedo) {
    throw new Error("Open Assist can only restore the current checkpoint or the next hidden checkpoint.");
  }
  const expectedSnapshot = isUndo ? checkpoint.afterSnapshot : checkpoint.beforeSnapshot;
  const guard = await gitCheckpointService.restoreGuard(
    repository,
    expectedSnapshot.worktreeTree,
    expectedSnapshot.indexTree
  );
  if (!guard.isAllowed) throw new Error(guard.message ?? "Open Assist can’t restore this checkpoint right now.");
  await gitCheckpointService.restore(repository, checkpoint.changedFiles, isUndo ? "before" : "after");
  const nextState = saveCodeTrackingState({
    ...state,
    currentCheckpointPosition: isUndo ? checkpointIndex - 1 : checkpointIndex
  });
  return {
    ok: true,
    state: nextState,
    panel: await openCodeReview(threadID, checkpointID)
  };
}

function loadSessionRegistry() {
  const snapshot = readJSON<{ version?: number; sessions?: SessionSummary[] }>(sessionRegistryPath(), { version: 2, sessions: [] });
  return {
    version: Math.max(2, Number(snapshot.version ?? 2)),
    sessions: (snapshot.sessions ?? []).filter((session): session is SessionSummary => Boolean(session?.id))
  };
}

function saveSessionRegistry(sessions: SessionSummary[]) {
  const sorted = sessions
    .filter((session) => session.id)
    .sort((a, b) => (Number(b.updatedAt ?? b.createdAt ?? 0) - Number(a.updatedAt ?? a.createdAt ?? 0)));
  const seen = new Set<string>();
  const normalized: SessionSummary[] = [];
  for (const session of sorted) {
    const key = `${session.source.toLowerCase()}::${session.id.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    normalized.push(session);
    if (normalized.length >= 200) break;
  }
  writeJSON(sessionRegistryPath(), { version: 2, sessions: normalized });
}

function findSession(threadID: string) {
  const registry = loadSessionRegistry();
  return registry.sessions.find((session) => session.id.toLowerCase() === threadID.toLowerCase());
}

function updateSession(session: SessionSummary) {
  const registry = loadSessionRegistry();
  const next = [
    { ...session, updatedAt: currentSwiftDate() },
    ...registry.sessions.filter((item) => item.id.toLowerCase() !== session.id.toLowerCase() || item.source !== session.source)
  ];
  saveSessionRegistry(next);
  return next[0];
}

function clearProviderBindingsForBackend(backend: AssistantBackend) {
  const registry = loadSessionRegistry();
  const next = registry.sessions.map((session) => {
    const bindings = session.providerBindingsByBackend ?? [];
    const filtered = bindings.filter((binding) => binding.backend !== backend);
    if (filtered.length === bindings.length) return session;
    return {
      ...session,
      providerBindingsByBackend: filtered,
      updatedAt: currentSwiftDate()
    };
  });
  saveSessionRegistry(next);
}

function providerBinding(session: SessionSummary | undefined, backend: AssistantBackend) {
  return (session?.providerBindingsByBackend ?? []).find((binding) => binding.backend === backend);
}

function projectContextForThread(threadID: string) {
  const loadedProjects = loadProjects();
  const projectID = loadedProjects.threadAssignments[threadID];
  const project = projectID
    ? loadedProjects.projects.find((item) => item.kind !== "folder" && item.id.toLowerCase() === projectID.toLowerCase())
    : undefined;
  return { project, projectID: project?.id ?? projectID };
}

function agentFilesStorageProjectID(projectID?: string | null) {
  const id = projectID?.trim();
  return id || unassignedAgentFilesProjectID;
}

function agentFilesProjectRoot(projectID?: string | null) {
  return path.join(projectStoreRoot(), agentFilesStorageProjectID(projectID), agentFilesDirectoryName);
}

function safeAgentFilesPathComponent(value: string, fallback = "thread") {
  const slug = value
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 72)
    .replace(/-+$/g, "");
  return slug || fallback;
}

function agentFilesThreadSuffix(threadID: string) {
  const compact = threadID.replace(/^openassist-/i, "").replace(/[^a-z0-9]/gi, "").toLowerCase();
  return compact.slice(0, 8) || createHash("sha1").update(threadID).digest("hex").slice(0, 8);
}

function titleForAgentFiles(session: SessionSummary | undefined, seedTitle?: string) {
  const title = normalizeTitle(session?.title, "");
  if (title && !isGenericThreadTitle(title)) return title;
  const latestUserMessage = normalizeTitle(session?.latestUserMessage, "");
  if (latestUserMessage) return titleForPrompt(latestUserMessage);
  const seed = normalizeTitle(seedTitle, "");
  if (seed) return titleForPrompt(seed);
  return "Thread";
}

function agentFilesThreadFolder(threadID: string, title: string) {
  return `${safeAgentFilesPathComponent(title, "thread")}--${agentFilesThreadSuffix(threadID)}`;
}

function readAgentFilesManifest(folderPath: string) {
  return readJSON<Partial<AgentFilesManifest>>(path.join(folderPath, agentFilesManifestName), {});
}

function writeAgentFilesManifest(folderPath: string, manifest: AgentFilesManifest) {
  writeJSON(path.join(folderPath, agentFilesManifestName), manifest);
}

function linkedFolderPathForProject(projectID?: string | null) {
  const id = projectID?.trim();
  if (!id || id === unassignedAgentFilesProjectID) return undefined;
  const { snapshot } = projectStoreSnapshot();
  const project = projectRecord(snapshot, id);
  return normalizeLinkedFolderPath(String(project?.linkedFolderPath ?? ""));
}

function agentFilesSearchProjectIDs(preferredProjectID?: string | null) {
  const ids: string[] = [agentFilesStorageProjectID(preferredProjectID), unassignedAgentFilesProjectID];
  try {
    for (const entry of fs.readdirSync(projectStoreRoot(), { withFileTypes: true })) {
      if (entry.isDirectory()) ids.push(entry.name);
    }
  } catch {
    // No project storage exists yet.
  }
  return [...new Set(ids.map((id) => id.trim()).filter(Boolean))];
}

function findThreadAgentFilesDirectory(threadID: string, preferredProjectID?: string | null) {
  const normalizedThreadID = threadID.trim().toLowerCase();
  if (!normalizedThreadID) return null;
  for (const projectID of agentFilesSearchProjectIDs(preferredProjectID)) {
    const root = agentFilesProjectRoot(projectID === unassignedAgentFilesProjectID ? undefined : projectID);
    let folders: fs.Dirent[] = [];
    try {
      folders = fs.readdirSync(root, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const folder of folders) {
      if (!folder.isDirectory()) continue;
      const folderPath = path.join(root, folder.name);
      const manifest = readAgentFilesManifest(folderPath);
      if (String(manifest.threadID ?? "").trim().toLowerCase() !== normalizedThreadID) continue;
      return {
        folderPath,
        projectID: String(manifest.projectID ?? projectID),
        manifest: manifest as AgentFilesManifest
      };
    }
  }
  return null;
}

function uniqueAgentFilesFolderPath(root: string, threadFolder: string, currentPath?: string) {
  let candidate = path.join(root, threadFolder);
  if (!fs.existsSync(candidate) || sameResolvedPath(candidate, currentPath)) return candidate;
  for (let index = 2; index < 1000; index += 1) {
    candidate = path.join(root, `${threadFolder}-${index}`);
    if (!fs.existsSync(candidate) || sameResolvedPath(candidate, currentPath)) return candidate;
  }
  return path.join(root, `${threadFolder}-${Date.now().toString(36)}`);
}

function updateSessionAgentFilesWorkingDirectory(threadID: string, folderPath: string) {
  const session = findSession(threadID);
  if (!session) return;
  session.cwd = folderPath;
  session.effectiveCWD = folderPath;
  session.updatedAt = currentSwiftDate();
  updateSession(session);
}

function rewriteMovedPathValue(value: string, oldRoot: string, newRoot: string) {
  const fileURLPrefix = "file://";
  const hasFilePrefix = value.startsWith(fileURLPrefix);
  const rawValue = hasFilePrefix ? value.slice(fileURLPrefix.length) : value;
  if (rawValue !== oldRoot && !rawValue.startsWith(`${oldRoot}${path.sep}`)) return value;
  const next = rawValue === oldRoot
    ? newRoot
    : path.join(newRoot, path.relative(oldRoot, rawValue));
  return hasFilePrefix ? `${fileURLPrefix}${next}` : next;
}

function rewriteMovedPathsDeep(value: unknown, oldRoot: string, newRoot: string): { value: unknown; changed: boolean } {
  if (typeof value === "string") {
    const next = rewriteMovedPathValue(value, oldRoot, newRoot);
    return { value: next, changed: next !== value };
  }
  if (Array.isArray(value)) {
    let changed = false;
    const next = value.map((item) => {
      const result = rewriteMovedPathsDeep(item, oldRoot, newRoot);
      changed = changed || result.changed;
      return result.value;
    });
    return { value: next, changed };
  }
  if (value && typeof value === "object") {
    let changed = false;
    const next: JsonObject = {};
    for (const [key, item] of Object.entries(value as JsonObject)) {
      const result = rewriteMovedPathsDeep(item, oldRoot, newRoot);
      changed = changed || result.changed;
      next[key] = result.value;
    }
    return { value: next, changed };
  }
  return { value, changed: false };
}

function rewriteConversationArtifactPaths(threadID: string, oldRoot: string, newRoot: string) {
  const snapshot = readConversationSnapshot(threadID);
  const rewritten = rewriteMovedPathsDeep(snapshot, oldRoot, newRoot);
  if (!rewritten.changed) return;
  writeConversationSnapshot(threadID, rewritten.value as JsonObject);
}

function movedToMarkerPayload(threadID: string, fromPath: string, toPath: string) {
  return {
    threadID,
    from: fromPath,
    to: toPath,
    movedAt: currentSwiftDate()
  };
}

function moveThreadAgentFilesDirectory(threadID: string, nextProjectID?: string | null, titleHint?: string) {
  const existing = findThreadAgentFilesDirectory(threadID);
  if (!existing) return null;
  const storageProjectID = agentFilesStorageProjectID(nextProjectID);
  const session = findSession(threadID);
  const title = titleForAgentFiles(session, titleHint);
  const manifest = existing.manifest;
  const threadFolder = String(manifest.threadFolder ?? "").trim() || agentFilesThreadFolder(threadID, title);
  const targetRoot = agentFilesProjectRoot(storageProjectID === unassignedAgentFilesProjectID ? undefined : storageProjectID);
  fs.mkdirSync(targetRoot, { recursive: true });
  const targetPath = uniqueAgentFilesFolderPath(targetRoot, threadFolder, existing.folderPath);
  const linkedFolderPath = linkedFolderPathForProject(storageProjectID);
  const now = currentSwiftDate();

  if (!sameResolvedPath(existing.folderPath, targetPath)) {
    try {
      fs.renameSync(existing.folderPath, targetPath);
    } catch {
      fs.cpSync(existing.folderPath, targetPath, { recursive: true });
      fs.rmSync(existing.folderPath, { recursive: true, force: true });
    }
    fs.mkdirSync(existing.folderPath, { recursive: true });
    writeJSON(path.join(existing.folderPath, agentFilesMovedToName), movedToMarkerPayload(threadID, existing.folderPath, targetPath));
    rewriteConversationArtifactPaths(threadID, existing.folderPath, targetPath);
  }

  const previousLocations = [
    ...new Set([
      ...(Array.isArray(manifest.previousLocations) ? manifest.previousLocations.filter((item) => typeof item === "string") : []),
      ...(sameResolvedPath(existing.folderPath, targetPath) ? [] : [existing.folderPath])
    ])
  ];
  const nextManifest: AgentFilesManifest = {
    threadID,
    projectID: storageProjectID,
    threadTitle: title,
    threadFolder: path.basename(targetPath),
    createdAt: Number(manifest.createdAt ?? now),
    updatedAt: now,
    previousLocations,
    ...(linkedFolderPath ? { linkedFolderPath } : {})
  };
  writeAgentFilesManifest(targetPath, nextManifest);
  updateSessionAgentFilesWorkingDirectory(threadID, targetPath);
  return { path: targetPath, manifest: nextManifest };
}

function ensureThreadAgentFilesDirectory(threadID: string, titleHint?: string) {
  const session = ensureOpenAssistSessionRecord(threadID);
  const projectID = session.projectID ?? projectContextForThread(threadID).projectID;
  const storageProjectID = agentFilesStorageProjectID(projectID);
  const existing = findThreadAgentFilesDirectory(threadID, storageProjectID);
  if (existing && agentFilesStorageProjectID(existing.manifest.projectID) !== storageProjectID) {
    const moved = moveThreadAgentFilesDirectory(threadID, storageProjectID, titleHint);
    if (moved) return moved;
  }

  const refreshedExisting = findThreadAgentFilesDirectory(threadID, storageProjectID);
  const title = titleForAgentFiles(findSession(threadID) ?? session, titleHint);
  const linkedFolderPath = linkedFolderPathForProject(storageProjectID);
  const now = currentSwiftDate();
  if (refreshedExisting) {
    const manifest: AgentFilesManifest = {
      threadID,
      projectID: storageProjectID,
      threadTitle: title,
      threadFolder: String(refreshedExisting.manifest.threadFolder ?? path.basename(refreshedExisting.folderPath)),
      createdAt: Number(refreshedExisting.manifest.createdAt ?? now),
      updatedAt: now,
      previousLocations: Array.isArray(refreshedExisting.manifest.previousLocations)
        ? refreshedExisting.manifest.previousLocations.filter((item): item is string => typeof item === "string")
        : [],
      ...(linkedFolderPath ? { linkedFolderPath } : {})
    };
    writeAgentFilesManifest(refreshedExisting.folderPath, manifest);
    updateSessionAgentFilesWorkingDirectory(threadID, refreshedExisting.folderPath);
    return { path: refreshedExisting.folderPath, manifest };
  }

  const threadFolder = agentFilesThreadFolder(threadID, title);
  const root = agentFilesProjectRoot(storageProjectID === unassignedAgentFilesProjectID ? undefined : storageProjectID);
  fs.mkdirSync(root, { recursive: true });
  const folderPath = uniqueAgentFilesFolderPath(root, threadFolder);
  fs.mkdirSync(folderPath, { recursive: true });
  const manifest: AgentFilesManifest = {
    threadID,
    projectID: storageProjectID,
    threadTitle: title,
    threadFolder: path.basename(folderPath),
    createdAt: now,
    updatedAt: now,
    previousLocations: [],
    ...(linkedFolderPath ? { linkedFolderPath } : {})
  };
  writeAgentFilesManifest(folderPath, manifest);
  updateSessionAgentFilesWorkingDirectory(threadID, folderPath);
  return { path: folderPath, manifest };
}

function threadAgentFilesDisplayPath(threadID: string) {
  const existing = findThreadAgentFilesDirectory(threadID);
  if (existing) return existing.folderPath;
  const session = findSession(threadID);
  const projectID = session?.projectID ?? projectContextForThread(threadID).projectID;
  const title = titleForAgentFiles(session, session?.latestUserMessage);
  const storageProjectID = agentFilesStorageProjectID(projectID);
  return path.join(
    agentFilesProjectRoot(storageProjectID === unassignedAgentFilesProjectID ? undefined : storageProjectID),
    agentFilesThreadFolder(threadID, title)
  );
}

function resolveMovedAgentFilesPath(filePath: string, depth = 0): string {
  if (depth > 8 || fs.existsSync(filePath)) return filePath;
  const support = supportRoot();
  let current = path.dirname(filePath);
  while (pathIsInside(current, support)) {
    const markerPath = path.join(current, agentFilesMovedToName);
    if (fs.existsSync(markerPath)) {
      const marker = readJSON<{ to?: string; targetPath?: string; path?: string }>(markerPath, {});
      const toPath = pluginString(marker.to, marker.targetPath, marker.path);
      if (toPath) {
        const relative = path.relative(current, filePath);
        const nextPath = path.join(toPath, relative);
        if (!sameResolvedPath(nextPath, filePath)) return resolveMovedAgentFilesPath(nextPath, depth + 1);
      }
    }
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return filePath;
}

function threadAgentFilesPath(threadID: string) {
  return {
    ok: true,
    path: ensureThreadAgentFilesDirectory(threadID).path
  };
}

function ensureOpenAssistSessionRecord(threadID: string, backend?: AssistantBackend, modelID?: string) {
  const existing = findSession(threadID);
  if (existing) return existing;
  const { project, projectID } = projectContextForThread(threadID);
  const now = currentSwiftDate();
  const linkedFolderPath = project?.linkedFolderPath ?? undefined;
  const session: SessionSummary = {
    id: threadID,
    title: "New Assistant Session",
    source: "openAssist",
    threadArchitectureVersion: 2,
    conversationPersistence: 2,
    providerBindingsByBackend: [],
    status: "idle",
    createdAt: now,
    updatedAt: now,
    latestTaskMode: "chat",
    latestModel: modelID,
    latestInteractionMode: "agentic",
    latestReasoningEffort: "high",
    latestPermissionMode: "fullAccess",
    isArchived: false,
    isTemporary: false,
    projectID,
    projectName: project?.title,
    linkedProjectFolderPath: linkedFolderPath,
    projectFolderMissing: false,
    activeProvider: backend
  };
  return updateSession(session);
}

function updateProviderBinding(threadID: string, backend: AssistantBackend, providerSessionID: string, modelID?: string, extras?: JsonObject) {
  const session = ensureOpenAssistSessionRecord(threadID, backend, modelID);
  const existing = session.providerBindingsByBackend ?? [];
  const nextBinding = {
    ...(existing.find((binding) => binding.backend === backend) ?? {}),
    backend,
    providerSessionID,
    latestModelID: modelID || String((existing.find((binding) => binding.backend === backend) ?? {}).latestModelID ?? ""),
    latestInteractionMode: "agentic",
    latestReasoningEffort: "high",
    lastConnectedAt: currentSwiftDate(),
    ...(extras ?? {})
  };
  session.providerBindingsByBackend = [nextBinding, ...existing.filter((binding) => binding.backend !== backend)];
  session.activeProvider = backend;
  return updateSession(session);
}

function updateProjectThreadAssignment(threadID: string, projectID?: string | null) {
  if (!projectID) return;
  const filePath = path.join(projectStoreRoot(), "projects.json");
  const snapshot = readJSON<JsonObject & { threadAssignments?: Record<string, string> }>(filePath, {});
  snapshot.threadAssignments = { ...(snapshot.threadAssignments ?? {}), [threadID]: projectID };
  writeJSON(filePath, snapshot);
}

function removeProjectThreadAssignment(threadID: string) {
  const filePath = path.join(projectStoreRoot(), "projects.json");
  const snapshot = readJSON<JsonObject & { threadAssignments?: Record<string, string> }>(filePath, {});
  const assignments = { ...(snapshot.threadAssignments ?? {}) };
  delete assignments[threadID];
  snapshot.threadAssignments = assignments;
  writeJSON(filePath, snapshot);
}

function normalizeProjectName(name: string) {
  return name.replace(/\s+/g, " ").trim();
}

function recoverableProjectNoteIDs() {
  const notesRoot = path.join(projectStoreRoot(), "ProjectNotes");
  try {
    return new Set(
      fs.readdirSync(notesRoot, { withFileTypes: true })
        .filter((entry) => entry.isDirectory())
        .map((entry) => entry.name.trim().toLowerCase())
        .filter(Boolean)
    );
  } catch {
    return new Set<string>();
  }
}

function projectStoreBackupCandidates() {
  const root = cleanupBackupsRoot();
  try {
    return fs.readdirSync(root, { withFileTypes: true })
      .filter((entry) => entry.isDirectory())
      .map((entry) => path.join(root, entry.name, "projects.before.json"))
      .filter((filePath) => fs.existsSync(filePath))
      .sort((a, b) => {
        try {
          return fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs;
        } catch {
          return 0;
        }
      });
  } catch {
    return [];
  }
}

function recoverProjectStoreSnapshot(filePath: string, snapshot: JsonObject & {
  version?: number;
  projects?: JsonObject[];
  threadAssignments?: Record<string, string>;
  brainByProjectID?: Record<string, JsonObject>;
}) {
  if ((snapshot.projects ?? []).length > 0) return snapshot;

  const noteProjectIDs = recoverableProjectNoteIDs();
  if (!noteProjectIDs.size) return snapshot;

  for (const backupPath of projectStoreBackupCandidates()) {
    const backup = readJSON<JsonObject & {
      version?: number;
      projects?: JsonObject[];
      threadAssignments?: Record<string, string>;
      brainByProjectID?: Record<string, JsonObject>;
    }>(backupPath, {});
    const backupProjects = backup.projects ?? [];
    if (!backupProjects.length) continue;
    const backupProjectIDs = new Set(
      backupProjects
        .map((project) => String(project.id ?? "").trim().toLowerCase())
        .filter(Boolean)
    );
    const hasNoteProject = [...noteProjectIDs].some((id) => backupProjectIDs.has(id));
    if (!hasNoteProject) continue;

    const backupFilePath = `${filePath}.empty-${new Date().toISOString().replace(/[:.]/g, "-")}.bak`;
    try {
      if (fs.existsSync(filePath)) fs.copyFileSync(filePath, backupFilePath);
    } catch {
      // Recovery should still proceed even if the empty snapshot backup fails.
    }

    snapshot.version = Math.max(Number(snapshot.version ?? 1), Number(backup.version ?? 1));
    snapshot.projects = backupProjects;
    snapshot.threadAssignments = Object.keys(snapshot.threadAssignments ?? {}).length
      ? snapshot.threadAssignments
      : (backup.threadAssignments ?? {});
    snapshot.brainByProjectID = Object.keys(snapshot.brainByProjectID ?? {}).length
      ? snapshot.brainByProjectID
      : (backup.brainByProjectID ?? {});
    saveProjectStoreSnapshot(filePath, snapshot);
    return snapshot;
  }

  return snapshot;
}

function projectStoreSnapshot() {
  const filePath = path.join(projectStoreRoot(), "projects.json");
  const snapshot = readJSON<JsonObject & {
    version?: number;
    projects?: JsonObject[];
    threadAssignments?: Record<string, string>;
    brainByProjectID?: Record<string, JsonObject>;
  }>(filePath, {});
  snapshot.projects = snapshot.projects ?? [];
  snapshot.threadAssignments = snapshot.threadAssignments ?? {};
  snapshot.brainByProjectID = snapshot.brainByProjectID ?? {};
  return { filePath, snapshot: recoverProjectStoreSnapshot(filePath, snapshot) };
}

function saveProjectStoreSnapshot(filePath: string, snapshot: JsonObject) {
  snapshot.version = Math.max(1, Number(snapshot.version ?? 1));
  writeJSON(filePath, snapshot);
  loadAppStateCachedResult = null;
  loadAppStateCachedAt = 0;
}

function projectRecord(snapshot: { projects?: JsonObject[] }, projectID: string) {
  const id = projectID.trim().toLowerCase();
  return (snapshot.projects ?? []).find((project) => String(project.id ?? "").trim().toLowerCase() === id);
}

function canonicalProjectFolderID(snapshot: { projects?: JsonObject[] }, folderID?: string | null) {
  const id = folderID?.trim().toLowerCase();
  if (!id) return undefined;
  const folder = (snapshot.projects ?? []).find((project) =>
    String(project.id ?? "").trim().toLowerCase() === id && String(project.kind ?? "") === "folder"
  );
  return folder ? String(folder.id ?? "") : undefined;
}

function normalizeLinkedFolderPath(folderPath?: string | null) {
  const trimmed = folderPath?.trim();
  if (!trimmed) return undefined;
  const resolved = path.resolve(trimmed);
  try {
    return fs.realpathSync.native(resolved);
  } catch {
    return resolved;
  }
}

function linkedFolderPathKey(folderPath?: string | null) {
  return normalizeLinkedFolderPath(folderPath)?.toLowerCase() ?? "";
}

function loadedProjectItem(projectID: string) {
  return loadProjects().projects.find((project) => project.id.toLowerCase() === projectID.toLowerCase()) ?? null;
}

function loadedProjectsState() {
  const loaded = loadProjects();
  return { projects: loaded.projects, hiddenProjects: loaded.hiddenProjects, plannerLists: loaded.plannerLists };
}

function emitProjectsChanged() {
  loadAppStateCachedResult = null;
  loadAppStateCachedAt = 0;
  emitAppStateBackgroundUpdate({ type: "projects", ...loadedProjectsState() });
  scheduleMacSyncSoon();
}

function renameProject(projectID: string, name: string) {
  const { filePath, snapshot } = projectStoreSnapshot();
  const project = projectRecord(snapshot, projectID);
  if (!project) throw new Error("Project was not found.");
  const nextName = normalizeProjectName(name);
  if (!nextName) throw new Error("Project name is required.");
  project.name = nextName;
  project.updatedAt = currentSwiftDate();
  saveProjectStoreSnapshot(filePath, snapshot);
  scheduleMacSyncSoon();
  return loadedProjectItem(projectID);
}

