function deleteProject(projectID: string) {
  const { filePath, snapshot } = projectStoreSnapshot();
  const normalizedID = projectID.trim().toLowerCase();
  const projectIDsToDelete = new Set<string>([normalizedID]);
  for (const project of snapshot.projects ?? []) {
    const parentID = String(project.parentID ?? "").trim().toLowerCase();
    if (projectIDsToDelete.has(parentID)) {
      projectIDsToDelete.add(String(project.id ?? "").trim().toLowerCase());
    }
  }
  snapshot.projects = (snapshot.projects ?? []).filter((project) => !projectIDsToDelete.has(String(project.id ?? "").trim().toLowerCase()));
  const assignments = { ...(snapshot.threadAssignments ?? {}) };
  for (const [threadID, assignedProjectID] of Object.entries(assignments)) {
    if (projectIDsToDelete.has(String(assignedProjectID).trim().toLowerCase())) {
      const moved = moveThreadAgentFilesDirectory(threadID, null);
      const session = findSession(threadID);
      if (session) {
        delete session.projectID;
        delete session.projectName;
        delete session.linkedProjectFolderPath;
        if (moved) {
          session.cwd = moved.path;
          session.effectiveCWD = moved.path;
        }
        updateSession(session);
      }
      delete assignments[threadID];
    }
  }
  snapshot.threadAssignments = assignments;
  for (const projectKey of Object.keys(snapshot.brainByProjectID ?? {})) {
    if (projectIDsToDelete.has(projectKey.trim().toLowerCase())) delete snapshot.brainByProjectID?.[projectKey];
  }
  saveProjectStoreSnapshot(filePath, snapshot);
  for (const deletedProjectID of projectIDsToDelete) recordMacSyncTombstone("project", deletedProjectID.toUpperCase());
  scheduleMacSyncSoon();
  return { ok: true };
}

function loadProjectMemory(projectID: string) {
  const { filePath, snapshot } = projectStoreSnapshot();
  const project = projectRecord(snapshot, projectID);
  const title = normalizeTitle(project?.name, "Project");
  const linkedFolderPath = normalizeLinkedFolderPath(String(project?.linkedFolderPath ?? ""));
  const agentFilesRoot = agentFilesProjectRoot(projectID);
  const brain = snapshot.brainByProjectID?.[projectID]
    ?? snapshot.brainByProjectID?.[projectID.toUpperCase()]
    ?? snapshot.brainByProjectID?.[projectID.toLowerCase()];
  const summary = normalizeTitle(brain?.projectSummary, "");
  const digests = Object.values((brain?.threadDigestsByThreadID as Record<string, JsonObject> | undefined) ?? {});
  const digestLines = digests.slice(0, 24).map((digest) => {
    const threadTitle = normalizeTitle(digest.threadTitle, "Untitled chat");
    const digestText = normalizeTitle(digest.digest, normalizeTitle(digest.summary, ""));
    return digestText ? `- ${threadTitle}: ${digestText}` : `- ${threadTitle}`;
  });
  const markdown = [
    `# ${title} Memory`,
    "",
    summary || "No project summary has been saved yet.",
    "",
    "## Agent Files",
    "",
    `Project thread files are saved under \`${agentFilesRoot}\`.`,
    linkedFolderPath
      ? `Linked workspace for read/context: \`${linkedFolderPath}\`. Only write there when the user clearly asks.`
      : "No linked workspace is attached.",
    digestLines.length ? "\n## Chat Digests" : "",
    ...digestLines
  ].filter(Boolean).join("\n");
  return {
    threadID: `project:${projectID}`,
    exists: Boolean(summary || digestLines.length),
    path: filePath,
    markdown
  };
}

function projectItemFromSnapshot(project: JsonObject, notes = 0, chats = 0): ProjectItem {
  const id = String(project.id ?? "");
  const kind = String(project.kind ?? "project") as "folder" | "project";
  const area = normalizeDailyArea(project.area);
  const plannerOnly = projectRecordPlannerOnly(project);
  const subtitle = kind === "folder"
    ? `${chats} ${chats === 1 ? "chat" : "chats"}`
    : plannerOnly
      ? `Planner List${area ? ` · ${area}` : ""}`
    : `${chats ? `${chats} ${chats === 1 ? "chat" : "chats"}` : "No chats yet"}${notes ? ` · ${notes} notes` : ""}`;
  return {
    id,
    title: normalizeTitle(project.name, kind === "folder" ? "Group" : "Project"),
    subtitle,
    icon: iconForProject(project.iconSymbolName, kind, project.linkedFolderPath),
    kind,
    parentID: (project.parentID as string | undefined) ?? null,
    linkedFolderPath: (project.linkedFolderPath as string | undefined) ?? null,
    peerLinkedFolders: Array.isArray(project.peerLinkedFolders)
      ? project.peerLinkedFolders
        .map((entry) => jsonObject(entry))
        .filter((entry): entry is JsonObject => Boolean(entry))
        .map((entry) => ({
          machineID: String(entry.machineID ?? "").trim() || undefined,
          machineName: String(entry.machineName ?? "").trim() || undefined,
          path: String(entry.path ?? "").trim() || undefined
        }))
      : undefined,
    area,
    color: (project.color as string | undefined) ?? undefined,
    plannerOnly,
    hidden: project.isHidden === true
  };
}

function uniqueProjectName(snapshot: { projects?: JsonObject[] }, name: string, parentID?: string | null) {
  const base = normalizeProjectName(name);
  if (!base) throw new Error("Project name is required.");
  const normalizedParent = parentID?.trim().toLowerCase() || "";
  const siblings = new Set(
    (snapshot.projects ?? [])
      .filter((project) => String(project.parentID ?? "").trim().toLowerCase() === normalizedParent)
      .map((project) => normalizeProjectName(String(project.name ?? "")).toLowerCase())
      .filter(Boolean)
  );
  if (!siblings.has(base.toLowerCase())) return base;
  for (let index = 2; index < 100; index += 1) {
    const candidate = `${base} ${index}`;
    if (!siblings.has(candidate.toLowerCase())) return candidate;
  }
  return `${base} ${Date.now()}`;
}

function createProject(name: string, kind: "project" | "folder" = "project", parentID?: string | null) {
  const { filePath, snapshot } = projectStoreSnapshot();
  const projects = snapshot.projects ?? [];
  const normalizedKind = kind === "folder" ? "folder" : "project";
  const normalizedParentID = normalizedKind === "project" ? canonicalProjectFolderID(snapshot, parentID) : undefined;
  const projectID = randomUUID().toUpperCase();
  const now = currentSwiftDate();
  const project: JsonObject = {
    id: projectID,
    kind: normalizedKind,
    name: uniqueProjectName(snapshot, name, normalizedParentID),
    isHidden: false,
    createdAt: now,
    updatedAt: now,
    iconSymbolName: normalizedKind === "folder" ? "folder.fill" : "book.closed.fill"
  };
  if (normalizedParentID) project.parentID = normalizedParentID;
  snapshot.version = Math.max(1, Number(snapshot.version ?? 1));
  snapshot.projects = [...projects, project];
  snapshot.threadAssignments = snapshot.threadAssignments ?? {};
  snapshot.brainByProjectID = snapshot.brainByProjectID ?? {};
  if (normalizedKind === "project") {
    snapshot.brainByProjectID[projectID] = { projectSummary: "", processedThreadIDs: [], threadDigestsByThreadID: {} };
  }
  saveProjectStoreSnapshot(filePath, snapshot);
  emitProjectsChanged();
  return projectItemFromSnapshot(project);
}

function listKnowledgeProjects() {
  const projects = loadProjects().projects.filter((project) => project.hidden !== true && project.plannerOnly !== true);
  const folderNames = new Map(
    projects
      .filter((project) => project.kind === "folder")
      .map((folder) => [folder.id.toLowerCase(), folder.title])
  );
  return projects.map((project) => ({
    id: project.id,
    name: project.title,
    kind: project.kind === "folder" ? "folder" : "project",
    parentFolderID: project.parentID ?? undefined,
    parentFolderName: project.parentID ? folderNames.get(project.parentID.toLowerCase()) : undefined,
    chats: Number(project.subtitle.match(/(\d+) chats?/)?.[1] ?? 0),
    notes: Number(project.subtitle.match(/(\d+) notes?/)?.[1] ?? 0)
  }));
}

function createKnowledgeProject(args: JsonObject) {
  const name = cleanDailyText(args.name ?? args.projectName ?? args.folderName);
  if (!name) throw new Error("Project or folder name is required.");
  const kind = String(args.kind ?? "project").trim().toLowerCase() === "folder" ? "folder" : "project";
  if (args.confirmed !== true) {
    return {
      status: "confirmation_required",
      suggestion: {
        name,
        kind,
        parentFolderName: cleanDailyText(args.parentFolderName)
      },
      message: `Ask the user to confirm creating the ${kind} "${name}" before making it.`
    };
  }

  const loaded = loadProjects();
  const visible = loaded.projects.filter((project) => project.hidden !== true && project.plannerOnly !== true);
  const normalizedName = name.toLowerCase();
  let parentFolder = kind === "project"
    ? visible.find((project) => project.kind === "folder" && (
      (cleanDailyText(args.parentFolderID) && project.id.toLowerCase() === cleanDailyText(args.parentFolderID).toLowerCase())
      || (cleanDailyText(args.parentFolderName) && project.title.trim().toLowerCase() === cleanDailyText(args.parentFolderName).toLowerCase())
    ))
    : undefined;

  const requestedParentName = cleanDailyText(args.parentFolderName);
  if (kind === "project" && !parentFolder && requestedParentName) {
    if (args.createParentFolderIfMissing !== true) {
      return {
        status: "parent_folder_not_found",
        message: `The folder "${requestedParentName}" does not exist. Ask whether it should be created, then retry with createParentFolderIfMissing=true.`
      };
    }
    parentFolder = createProject(requestedParentName, "folder");
  }

  const existing = loadProjects().projects.find((project) =>
    project.hidden !== true
    && project.plannerOnly !== true
    && (project.kind === "folder" ? "folder" : "project") === kind
    && project.title.trim().toLowerCase() === normalizedName
    && (kind === "folder" || String(project.parentID ?? "").toLowerCase() === String(parentFolder?.id ?? "").toLowerCase())
  );
  const project = existing ?? createProject(name, kind, parentFolder?.id);
  emitProjectsChanged();
  return {
    status: existing ? "existing" : "applied",
    project: {
      id: project.id,
      projectID: kind === "project" ? project.id : undefined,
      name: project.title,
      kind,
      parentFolderID: project.parentID ?? undefined,
      parentFolderName: parentFolder?.title
    },
    parentFolder: parentFolder ? { id: parentFolder.id, name: parentFolder.title } : undefined,
    message: existing
      ? `Using existing ${kind} "${project.title}".`
      : `Created ${kind} "${project.title}"${parentFolder ? ` inside "${parentFolder.title}"` : ""}.`,
    nextAction: kind === "project"
      ? `Use projectID ${project.id} when creating the note, chat, or delegated task.`
      : "Folders organize projects but cannot directly contain notes or chats. Create or choose a project inside this folder next."
  };
}

function createProjectFromFolder(folderPath: string, parentID?: string | null) {
  const linkedFolderPath = normalizeLinkedFolderPath(folderPath);
  if (!linkedFolderPath) throw new Error("Project folder is required.");
  const folderStats = fs.statSync(linkedFolderPath);
  if (!folderStats.isDirectory()) throw new Error("Choose a folder to open as a project.");

  const { filePath, snapshot } = projectStoreSnapshot();
  const projects = snapshot.projects ?? [];
  const folderKey = linkedFolderPathKey(linkedFolderPath);
  const normalizedParentID = canonicalProjectFolderID(snapshot, parentID);
  const existingProject = projects.find((project) =>
    String(project.kind ?? "project") === "project" && linkedFolderPathKey(String(project.linkedFolderPath ?? "")) === folderKey
  );
  if (existingProject) {
    const previousFolderPath = normalizeLinkedFolderPath(String(existingProject.linkedFolderPath ?? ""));
    existingProject.linkedFolderPath = linkedFolderPath;
    if (normalizedParentID) existingProject.parentID = normalizedParentID;
    existingProject.updatedAt = currentSwiftDate();
    saveProjectStoreSnapshot(filePath, snapshot);
    syncLinkedFolderForProjectSessions(
      String(existingProject.id ?? ""),
      normalizeTitle(String(existingProject.name ?? ""), "Project"),
      previousFolderPath,
      linkedFolderPath
    );
    scheduleMacSyncSoon();
    return loadedProjectItem(String(existingProject.id ?? ""));
  }

  const projectID = randomUUID().toUpperCase();
  const now = currentSwiftDate();
  const project: JsonObject = {
    id: projectID,
    kind: "project",
    name: uniqueProjectName(snapshot, path.basename(linkedFolderPath) || "Project", normalizedParentID),
    isHidden: false,
    createdAt: now,
    updatedAt: now,
    iconSymbolName: "folder.fill",
    linkedFolderPath
  };
  if (normalizedParentID) project.parentID = normalizedParentID;
  snapshot.version = Math.max(1, Number(snapshot.version ?? 1));
  snapshot.projects = [...projects, project];
  snapshot.threadAssignments = snapshot.threadAssignments ?? {};
  snapshot.brainByProjectID = snapshot.brainByProjectID ?? {};
  snapshot.brainByProjectID[projectID] = { projectSummary: "", processedThreadIDs: [], threadDigestsByThreadID: {} };
  saveProjectStoreSnapshot(filePath, snapshot);
  scheduleMacSyncSoon();
  return projectItemFromSnapshot(project);
}

function createEmptyConversation(threadID: string) {
  writeConversationSnapshot(threadID, {
    threadID,
    timeline: [],
    transcript: [],
    turns: [],
    lastAppliedEventSequence: 0
  });
}

function createOpenAssistThread(projectID?: string, persistEmptyConversation = true, isTemporary = false) {
  const loadedProjects = loadProjects();
  const normalizedProjectID = projectID?.trim().toLowerCase();
  const project = normalizedProjectID
    ? loadedProjects.projects.find((item) => item.kind !== "folder" && item.id.toLowerCase() === normalizedProjectID)
    : undefined;
  const threadID = makeOpenAssistThreadID();
  const now = currentSwiftDate();
  const linkedFolderPath = project?.linkedFolderPath ?? undefined;
  const session: SessionSummary = {
    id: threadID,
    title: "New Assistant Session",
    source: "openAssist",
    threadArchitectureVersion: 2,
    conversationPersistence: isTemporary ? 0 : 2,
    providerBindingsByBackend: [],
    status: "idle",
    createdAt: now,
    updatedAt: now,
    latestTaskMode: "chat",
    latestInteractionMode: "agentic",
    latestReasoningEffort: "high",
    latestPermissionMode: "fullAccess",
    isArchived: false,
    isTemporary,
    projectID: project?.id,
    projectName: project?.title,
    linkedProjectFolderPath: linkedFolderPath,
    projectFolderMissing: false
  };
  updateSession(session);
  updateProjectThreadAssignment(threadID, project?.id);
  if (!isTemporary && persistEmptyConversation) createEmptyConversation(threadID);
  return {
    session,
    thread: {
      id: threadID,
      title: session.title,
      projectID: project?.id,
      project: project?.title,
      activeProvider: session.activeProvider,
      modelID: pluginString(session.modelID, session.latestModel),
      age: "1m",
      updatedAt: Date.now(),
      isTemporary,
      active: true
    } satisfies ThreadItem,
    detail: {
      threadID,
      title: session.title,
      messages: []
    } satisfies ThreadDetail
  };
}

function sessionHasRecordedConversation(session?: SessionSummary | null) {
  return Boolean(pluginString(session?.latestUserMessage, session?.latestAssistantMessage));
}

function ensureConversationFromSessionSummary(session: SessionSummary) {
  const userText = pluginString(session.latestUserMessage);
  const assistantText = pluginString(session.latestAssistantMessage);
  if (!userText && !assistantText) return;
  const snapshot = readConversationSnapshot(session.id);
  if (conversationHasVisibleMessages(snapshot)) return;

  const backend = normalizeBackend(String(session.activeProvider ?? pluginString(session.providerBackend) ?? "codex"));
  const modelID = pluginString(session.modelID, session.latestModel) ?? "";
  const turnID = `recovered-turn-${randomUUID().toLowerCase()}`;
  const userCreatedAt = currentSwiftDate();
  const assistantCreatedAt = currentSwiftDate();
  const timeline = [
    ...(userText ? [timelineUserMessage(session.id, userText, userCreatedAt)] : []),
    ...(assistantText ? [timelineAssistantFinal(session.id, assistantText, backend, modelID, turnID, assistantCreatedAt)] : [])
  ];
  const transcript = [
    ...(userText ? [transcriptEntry("user", userText, backend, modelID)] : []),
    ...(assistantText ? [transcriptEntry("assistant", assistantText, backend, modelID)] : [])
  ];

  writeConversationSnapshot(session.id, {
    threadID: session.id,
    timeline,
    transcript,
    turns: assistantText ? [{
      threadID: session.id,
      openAssistTurnID: turnID,
      provider: backend,
      providerSessionID: session.id,
      providerTurnID: turnID,
      messageIDs: timeline.filter((item) => item.kind === "assistantFinal").map((item) => item.id),
      createdAt: assistantCreatedAt,
      updatedAt: assistantCreatedAt,
      checkpointReferences: []
    }] : [],
    lastAppliedEventSequence: snapshot.lastAppliedEventSequence ?? 0
  });
}

export function destroyTemporaryThread(threadID: string) {
  const session = findSession(threadID);
  const conversationPath = path.join(conversationStoreRoot(), threadID);
  // A session that is NOT temporary must never be destroyed through this path —
  // e.g. the user promoted ("kept") the thread, or the renderer is acting on
  // stale state. Temporary sessions ARE deleted in full, content included:
  // that is what "temporary" means. (Turns no longer auto-promote, so reaching
  // this with content is the normal leave-a-temporary-chat flow.)
  if (session && session.isTemporary !== true && session.conversationPersistence !== 0) {
    return { ok: false, kept: true };
  }
  if (session) {
    const registry = loadSessionRegistry();
    saveSessionRegistry(registry.sessions.filter((item) => item.id.toLowerCase() !== threadID.toLowerCase()));
  }
  fs.rmSync(conversationPath, { recursive: true, force: true });
  removeProjectThreadAssignment(threadID);
  return { ok: !fs.existsSync(conversationPath) };
}

// Temporary threads that survived a crash/force-quit (their leave-cleanup never
// ran) must not reappear as saved chats on the next launch.
export function purgeTemporaryThreadsOnStartup() {
  const registry = loadSessionRegistry();
  const temporary = registry.sessions.filter(
    (session) => session.isTemporary === true || session.conversationPersistence === 0
  );
  if (!temporary.length) return { removed: 0 };
  saveSessionRegistry(registry.sessions.filter(
    (session) => session.isTemporary !== true && session.conversationPersistence !== 0
  ));
  for (const session of temporary) {
    fs.rmSync(path.join(conversationStoreRoot(), session.id), { recursive: true, force: true });
    removeProjectThreadAssignment(session.id);
  }
  bridgeDebugLog(`Startup: purged ${temporary.length} leftover temporary thread(s).`);
  return { removed: temporary.length };
}

function normalizedModelForBackend(backend: AssistantBackend, rawModelID?: unknown) {
  const requested = pluginString(rawModelID)?.trim() ?? "";
  const lowered = requested.toLowerCase();
  if (backend === "ollamaLocal") return requested || "gemma4:e2b";
  if (backend === "antigravityCLI") {
    if (!requested || lowered === "antigravity-default") return "gemini-3.5-flash-high";
    return requested;
  }
  if (backend === "claudeCode") {
    if (lowered.includes("opus")) return "opus";
    if (lowered.includes("haiku")) return "haiku";
    if (lowered.includes("sonnet")) return "sonnet";
    return "sonnet";
  }
  if (backend === "copilot") {
    return requested || "auto";
  }
  // Codex backend: only GPT-5 / *-codex models are accepted. Reject anything else
  // (e.g. a stale "gpt-4o") and fall back to the Codex default.
  return codexSafeModel(requested);
}

export async function setThreadProvider(threadID: string, rawBackend: string, rawModelID?: string) {
  const backend = normalizeBackend(rawBackend);
  if (!isRuntimeBackend(backend)) {
    throw new Error("Main chat runtime must be Codex, Claude, Copilot, Antigravity, or Ollama.");
  }
  const session = ensureOpenAssistSessionRecord(threadID, backend);
  const existing = session.providerBindingsByBackend ?? [];
  const existingBinding = existing.find((binding) => binding.backend === backend);
  const modelID = normalizedModelForBackend(
    backend,
    rawModelID ?? existingBinding?.latestModelID ?? session.modelID ?? session.latestModel
  );
  const nextBinding = {
    ...(existingBinding ?? {}),
    backend,
    latestModelID: modelID,
    latestInteractionMode: "agentic",
    latestReasoningEffort: "high",
    lastConnectedAt: currentSwiftDate()
  };
  session.providerBindingsByBackend = [nextBinding, ...existing.filter((binding) => binding.backend !== backend)];
  session.activeProvider = backend;
  session.modelID = modelID;
  session.latestModel = modelID;
  updateSession(session);
  await refreshUsageForBackend(backend, { threadID, modelID, connectThread: true });
  const projects = loadProjects();
  return loadThreads(projects).find((thread) => thread.id.toLowerCase() === threadID.toLowerCase()) ?? null;
}

function renameSession(threadID: string, title: string) {
  const session = ensureOpenAssistSessionRecord(threadID);
  const nextTitle = normalizeTitle(title, "");
  if (!nextTitle) throw new Error("Chat title is required.");
  session.title = nextTitle;
  updateSession(session);
  const projects = loadProjects();
  return loadThreads(projects).find((thread) => thread.id.toLowerCase() === threadID.toLowerCase()) ?? null;
}

function promoteTemporarySession(threadID: string) {
  const session = ensureOpenAssistSessionRecord(threadID);
  session.isTemporary = false;
  session.conversationPersistence = 2;
  const updatedSession = updateSession(session);
  const conversationPath = path.join(conversationStoreRoot(), threadID, "conversation.json");
  if (!fs.existsSync(conversationPath)) createEmptyConversation(threadID);
  const projects = loadProjects();
  return loadThreads(projects).find((thread) => thread.id.toLowerCase() === threadID.toLowerCase())
    ?? threadItemForCompletedSession(updatedSession);
}

function assignSessionToProject(threadID: string, projectID?: string | null) {
  const session = ensureOpenAssistSessionRecord(threadID);
  const previousLinkedFolderPath = session.linkedProjectFolderPath;
  const loadedProjects = loadProjects();
  const project = projectID
    ? loadedProjects.projects.find((item) => item.id.toLowerCase() === projectID.toLowerCase() && item.kind !== "folder")
    : undefined;
  if (projectID && !project) throw new Error("Project was not found.");
  if (project) {
    session.projectID = project.id;
    session.projectName = project.title;
    if (project.linkedFolderPath) {
      session.linkedProjectFolderPath = project.linkedFolderPath;
    } else {
      delete session.linkedProjectFolderPath;
    }
    updateProjectThreadAssignment(threadID, project.id);
  } else {
    delete session.projectID;
    delete session.projectName;
    delete session.linkedProjectFolderPath;
    removeProjectThreadAssignment(threadID);
  }
  if (previousLinkedFolderPath && linkedFolderPathKey(session.cwd) === linkedFolderPathKey(previousLinkedFolderPath)) delete session.cwd;
  if (previousLinkedFolderPath && linkedFolderPathKey(session.effectiveCWD) === linkedFolderPathKey(previousLinkedFolderPath)) delete session.effectiveCWD;
  updateSession(session);
  const moved = moveThreadAgentFilesDirectory(threadID, project?.id ?? null, session.title);
  if (moved) {
    session.cwd = moved.path;
    session.effectiveCWD = moved.path;
    updateSession(session);
  }
  const projects = loadProjects();
  return loadThreads(projects).find((thread) => thread.id.toLowerCase() === threadID.toLowerCase()) ?? null;
}

function codexProviderThreadID(session: SessionSummary | undefined) {
  return pluginString(providerBinding(session, "codex")?.providerSessionID)?.trim();
}

async function archiveCodexProviderThread(providerThreadID?: string) {
  if (!providerThreadID) return { ok: false, reason: "missing-provider-thread" };
  try {
    await codexTransport.request("thread/archive", { threadId: providerThreadID }, undefined, 20_000);
    return { ok: true };
  } catch (error) {
    bridgeDebugLog(`Codex provider archive failed thread=${providerThreadID}: ${error instanceof Error ? error.message : String(error)}`);
    return { ok: false, reason: error instanceof Error ? error.message : String(error) };
  }
}

async function unarchiveCodexProviderThread(providerThreadID?: string) {
  if (!providerThreadID) return { ok: false, reason: "missing-provider-thread" };
  try {
    await codexTransport.request("thread/unarchive", { threadId: providerThreadID }, undefined, 20_000);
    return { ok: true };
  } catch (error) {
    bridgeDebugLog(`Codex provider unarchive failed thread=${providerThreadID}: ${error instanceof Error ? error.message : String(error)}`);
    return { ok: false, reason: error instanceof Error ? error.message : String(error) };
  }
}

function looksLikeUnsupportedCodexMethod(error: unknown) {
  const message = error instanceof Error ? error.message : String(error ?? "");
  return /method.*not.*found|unknown method|unsupported method|not implemented/i.test(message);
}

async function deleteCodexProviderThread(providerThreadID?: string) {
  if (!providerThreadID) return { ok: false, used: "none", reason: "missing-provider-thread" };
  let deleteReason: string | undefined;
  try {
    // Current Codex app-server bindings expose archive/unarchive, not hard
    // delete. Keep this future-ready for newer builds that add thread/delete.
    await codexTransport.request("thread/delete", { threadId: providerThreadID }, undefined, 20_000);
    return { ok: true, used: "thread/delete" };
  } catch (error) {
    deleteReason = error instanceof Error ? error.message : String(error);
    if (!looksLikeUnsupportedCodexMethod(error)) {
      bridgeDebugLog(`Codex provider delete failed thread=${providerThreadID}: ${deleteReason}`);
    }
  }
  const archived = await archiveCodexProviderThread(providerThreadID);
  return {
    ok: archived.ok,
    used: "thread/archive",
    reason: archived.reason ?? deleteReason
  };
}

async function archiveSession(threadID: string) {
  const session = ensureOpenAssistSessionRecord(threadID);
  const archivedAt = currentSwiftDate();
  await archiveCodexProviderThread(codexProviderThreadID(session));
  session.isArchived = true;
  session.archivedAt = archivedAt;
  session.autoDeleteAfter = null;
  updateSession(session);
  const projects = loadProjects();
  return loadThreads(projects).find((thread) => thread.id.toLowerCase() === threadID.toLowerCase()) ?? null;
}

async function unarchiveSession(threadID: string) {
  const session = ensureOpenAssistSessionRecord(threadID);
  await unarchiveCodexProviderThread(codexProviderThreadID(session));
  session.isArchived = false;
  delete session.archivedAt;
  delete session.autoDeleteAfter;
  updateSession(session);
  const projects = loadProjects();
  return loadThreads(projects).find((thread) => thread.id.toLowerCase() === threadID.toLowerCase()) ?? null;
}

async function deleteSessionPermanently(threadID: string) {
  const session = findSession(threadID);
  await deleteCodexProviderThread(codexProviderThreadID(session));
  const registry = loadSessionRegistry();
  saveSessionRegistry(registry.sessions.filter((session) => session.id.toLowerCase() !== threadID.toLowerCase()));
  fs.rmSync(path.join(conversationStoreRoot(), threadID), { recursive: true, force: true });
  removeProjectThreadAssignment(threadID);
  return { ok: true };
}

function providerLabel(raw: string) {
  if (raw === "claudeCode") return "Claude";
  if (raw === "antigravityCLI") return "Antigravity";
  if (raw === "copilot") return "Copilot";
  if (raw === "ollamaLocal") return "Ollama";
  if (raw === "githubCopilot") return "Copilot";
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

function projectListForNote(projects: LoadedProjects, projectID: string) {
  const key = projectID.toLowerCase();
  return projects.plannerLists.find((project) => project.id.toLowerCase() === key);
}

function projectNotesHiddenForList(projects: LoadedProjects, projectID: string) {
  const project = projectListForNote(projects, projectID);
  if (project?.plannerOnly) return false;
  return projects.hiddenProjectIDs.has(projectID.toLowerCase());
}

function projectNoteMarkdownPath(projectID: string, note: JsonObject, noteID: string) {
  const fileName = macSyncSafeNoteFileName(note.fileName, noteID);
  return path.join(noteDirectoryPath(projectID), fileName);
}

function readProjectNoteMarkdown(projectID: string, note: JsonObject, noteID: string) {
  const filePath = projectNoteMarkdownPath(projectID, note, noteID);
  return fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : "";
}

function noteMetadataFromRecord(note: JsonObject | undefined, projects: LoadedProjects, projectID: string, markdown?: string) {
  const project = projectListForNote(projects, projectID);
  const frontmatter = typeof markdown === "string" ? parseFrontmatter(markdown) : {};
  const area = normalizeDailyArea(note?.area ?? note?.category)
    || normalizeDailyArea(frontmatter.area ?? frontmatter.category)
    || normalizeDailyArea(project?.area);
  const noteTags = normalizeDailyTagLabels(note?.tags ?? note?.tag);
  const frontmatterTags = normalizeDailyTagLabels(frontmatter.tags ?? frontmatter.tag);
  return {
    area,
    tags: noteTags.length ? noteTags : frontmatterTags
  };
}

function projectNoteSearchMetadataText(metadata?: JsonObject) {
  if (!metadata) return "";
  const area = cleanDailyText(metadata.area);
  const tags = normalizeDailyTagLabels(metadata.tags);
  return [
    area ? `Category: ${area}` : "",
    tags.length ? `Tags: ${tags.join(", ")}` : ""
  ].filter(Boolean).join("\n");
}

function loadNotes(projects: LoadedProjects, options: { includeArchived?: boolean } = {}) {
  const notes: NoteItem[] = [];
  const noteFolders: NoteFolderItem[] = [];
  const notesRoot = path.join(projectStoreRoot(), "ProjectNotes");
  if (!fs.existsSync(notesRoot)) return { notes, noteFolders };
  for (const projectDir of fs.readdirSync(notesRoot)) {
    const projectID = projectDir.toUpperCase();
    if (projectNotesHiddenForList(projects, projectID)) continue;
    const projectName = projects.projectNameByID.get(projectID) ?? projects.projectNameByID.get(projectDir) ?? "Project";
    const manifestPath = path.join(notesRoot, projectDir, "notes", "manifest.json");
    const manifest = readJSON<{ notes?: JsonObject[]; folders?: JsonObject[]; selectedNoteID?: string }>(manifestPath, {});
    const folderCounts = new Map<string, number>();
    for (const note of manifest.notes ?? []) {
      if (note.isArchived === true && !options.includeArchived) continue;
      const folderID = typeof note.folderID === "string" ? note.folderID : null;
      if (folderID) folderCounts.set(folderID, (folderCounts.get(folderID) ?? 0) + 1);
    }
    for (const folder of manifest.folders ?? []) {
      const id = String(folder.id ?? "");
      if (!id) continue;
      noteFolders.push({
        id,
        name: normalizeTitle(folder.name, "Folder"),
        projectID,
        parentFolderID: normalizedNoteFolderParentID(folder.parentFolderID),
        noteCount: folderCounts.get(id) ?? 0
      });
    }
    for (const note of manifest.notes ?? []) {
      if (note.isArchived === true && !options.includeArchived) continue;
      const id = String(note.id ?? "");
      if (!id) continue;
      const updatedAt = swiftDateToMs(note.updatedAt);
      const markdown = readProjectNoteMarkdown(projectID, note, id);
      const metadata = noteMetadataFromRecord(note, projects, projectID, markdown);
      notes.push({
        id,
        projectID,
        projectName,
        folderID: typeof note.folderID === "string" ? note.folderID : null,
        title: normalizeTitle(note.title, "Untitled note"),
        subtitle: noteSubtitle(updatedAt),
        area: metadata.area,
        tags: metadata.tags,
        updatedAt,
        isArchived: note.isArchived === true,
        archivedAt: storedArchiveDateToMs(note.archivedAt),
        autoDeleteAfter: storedArchiveDateToMs(note.autoDeleteAfter) ?? null,
        active: manifest.selectedNoteID === id
      });
    }
  }
  notes.sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0));
  if (!notes.some((note) => note.active) && notes.length) notes[0].active = true;
  return { notes, noteFolders };
}

function noteManifestPath(projectID: string) {
  return path.join(projectStoreRoot(), "ProjectNotes", projectID.toUpperCase(), "notes", "manifest.json");
}

function noteDirectoryPath(projectID: string) {
  return path.join(projectStoreRoot(), "ProjectNotes", projectID.toUpperCase(), "notes");
}

function projectNoteRecoveryDirectoryPath(projectID: string, noteID: string) {
  return path.join(
    projectStoreRoot(),
    "ProjectNotesRecovery",
    "history",
    "project",
    projectID.toUpperCase(),
    noteID.toLowerCase()
  );
}

// Trailing whitespace/newlines flip back and forth between editor autosaves,
// so version identity must ignore them — otherwise every autosave looks like
// a "change" and floods the 50-slot history with copies of the same content.
function noteHistoryContentKey(markdown: string) {
  return markdown.replace(/\r\n/g, "\n").replace(/\s+$/g, "");
}

function noteHistoryContentHash(markdown: string) {
  return createHash("sha256").update(noteHistoryContentKey(markdown)).digest("hex");
}

function snapshotProjectNote(projectID: string, noteID: string, note: JsonObject, previousMarkdown: string) {
  if (!previousMarkdown.trim()) return;
  const recoveryRoot = projectNoteRecoveryDirectoryPath(projectID, noteID);
  const indexPath = path.join(recoveryRoot, "index.json");
  const entries = readJSON<JsonObject[]>(indexPath, []);
  // Skip if the newest snapshot already holds this exact content.
  const contentHash = noteHistoryContentHash(previousMarkdown);
  const latest = entries[0];
  if (latest && typeof latest.contentFileName === "string" && !latest.contentFileName.includes("/") && !latest.contentFileName.includes("\\")) {
    const latestPath = path.join(recoveryRoot, latest.contentFileName);
    if (fs.existsSync(latestPath) && noteHistoryContentHash(fs.readFileSync(latestPath, "utf8")) === contentHash) return;
  }
  const snapshotID = randomUUID().toLowerCase();
  const contentFileName = `${snapshotID}.md`;
  const filePath = path.join(recoveryRoot, contentFileName);
  fs.mkdirSync(recoveryRoot, { recursive: true });
  fs.writeFileSync(filePath, previousMarkdown, "utf8");
  const entry: JsonObject = {
    id: snapshotID,
    noteID,
    ownerID: projectID.toUpperCase(),
    ownerKind: "project",
    title: normalizeTitle(note.title, "Untitled note"),
    fileName: typeof note.fileName === "string" ? note.fileName : `${noteID}.md`,
    contentFileName,
    contentHash,
    preview: shortSearchText(previousMarkdown, 180),
    createdAt: Number(note.createdAt ?? 0) || currentSwiftDate(),
    updatedAt: Number(note.updatedAt ?? 0) || currentSwiftDate(),
    savedAt: currentSwiftDate()
  };
  writeJSON(indexPath, [entry, ...entries].slice(0, 50));
}

function listProjectNoteHistory(projectID: string, noteID: string) {
  const recoveryRoot = projectNoteRecoveryDirectoryPath(projectID, noteID);
  const indexPath = path.join(recoveryRoot, "index.json");
  const entries = readJSON<JsonObject[]>(indexPath, []);
  return entries
    .map((entry) => {
      const id = String(entry.id ?? "");
      const contentFileName = String(entry.contentFileName ?? "");
      if (!id || !contentFileName || contentFileName.includes("/") || contentFileName.includes("\\")) return null;
      const filePath = path.join(recoveryRoot, contentFileName);
      if (!fs.existsSync(filePath)) return null;
      const markdown = fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n");
      return {
        id,
        title: normalizeTitle(entry.title, "Untitled note"),
        savedAtLabel: noteHistorySavedAtLabel(Number(entry.savedAt ?? entry.updatedAt)),
        preview: normalizeTitle(entry.preview, shortSearchText(markdown, 180)),
        markdown
      };
    })
    .filter((entry): entry is NonNullable<typeof entry> => Boolean(entry));
}

function readNoteManifest(projectID: string) {
  return readJSON<{ version?: number; selectedNoteID?: string; notes?: JsonObject[]; folders?: JsonObject[] }>(
    noteManifestPath(projectID),
    { version: 3, notes: [], folders: [] }
  );
}

function writeNoteManifest(projectID: string, manifest: { version?: number; selectedNoteID?: string; notes?: JsonObject[]; folders?: JsonObject[] }) {
  writeJSON(noteManifestPath(projectID), {
    version: Math.max(3, Number(manifest.version ?? 3)),
    selectedNoteID: manifest.selectedNoteID,
    folders: manifest.folders ?? [],
    notes: manifest.notes ?? []
  });
}

function loadNote(projectID: string, noteID: string): NoteDetail {
  const manifest = readNoteManifest(projectID);
  const note = (manifest.notes ?? []).find((entry) => entry.id === noteID);
  const fileName = macSyncSafeNoteFileName(note?.fileName, noteID);
  if (note && manifest.selectedNoteID !== noteID) {
    manifest.selectedNoteID = noteID;
    writeNoteManifest(projectID, manifest);
  }
  const filePath = path.join(noteDirectoryPath(projectID), fileName);
  const markdown = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8") : "";
  const metadata = noteMetadataFromRecord(note, loadProjects(), projectID, markdown);
  return {
    id: noteID,
    title: normalizeTitle(note?.title, "Untitled note"),
    markdown,
    path: filePath,
    area: metadata.area,
    tags: metadata.tags
  };
}

function createProjectNote(projectID: string) {
  const manifest = readNoteManifest(projectID);
  const noteID = randomUUID().toLowerCase();
  const now = currentSwiftDate();
  const loadedProjects = loadProjects();
  const projectName = loadedProjects.projectNameByID.get(projectID) ?? loadedProjects.projectNameByID.get(projectID.toUpperCase());
  const projectArea = normalizeDailyArea(projectListForNote(loadedProjects, projectID)?.area);
  const note: JsonObject = {
    id: noteID,
    title: "Untitled note",
    noteType: "note",
    fileName: `${noteID}.md`,
    order: (manifest.notes ?? []).length,
    createdAt: now,
    updatedAt: now
  };
  if (projectArea) note.area = projectArea;
  manifest.notes = [...(manifest.notes ?? []), note];
  manifest.selectedNoteID = noteID;
  writeNoteManifest(projectID, manifest);
  const noteItem: NoteItem = {
    id: noteID,
    title: "Untitled note",
    subtitle: noteSubtitle(Date.now()),
    projectID: projectID.toUpperCase(),
    projectName,
    area: projectArea,
    tags: [],
    updatedAt: Date.now(),
    active: true
  };
  scheduleRemoteAccessBroadcast();
  return {
    note: noteItem,
    detail: {
      id: noteID,
      title: "Untitled note",
      markdown: "",
      path: path.join(noteDirectoryPath(projectID), `${noteID}.md`),
      area: projectArea,
      tags: []
    } satisfies NoteDetail
  };
}

function applyProjectNoteMetadataFromMarkdown(note: JsonObject, projectID: string, markdown: string) {
  const frontmatter = parseFrontmatter(markdown);
  const hasArea = Object.prototype.hasOwnProperty.call(frontmatter, "area")
    || Object.prototype.hasOwnProperty.call(frontmatter, "category");
  if (hasArea) {
    const area = normalizeDailyArea(frontmatter.area ?? frontmatter.category);
    if (area) note.area = area;
    else delete note.area;
  } else if (!cleanDailyText(note.area)) {
    const inheritedArea = normalizeDailyArea(projectListForNote(loadProjects(), projectID)?.area);
    if (inheritedArea) note.area = inheritedArea;
  }
  const hasTags = Object.prototype.hasOwnProperty.call(frontmatter, "tags")
    || Object.prototype.hasOwnProperty.call(frontmatter, "tag");
  if (hasTags) {
    note.tags = normalizeDailyTagLabels(frontmatter.tags ?? frontmatter.tag);
  }
}

function renameProjectNote(projectID: string, noteID: string, title: string): NoteDetail {
  const manifest = readNoteManifest(projectID);
  const note = (manifest.notes ?? []).find((entry) => entry.id === noteID);
  if (!note) throw new Error("Note was not found.");
  note.title = normalizeTitle(title, "Untitled note");
  note.updatedAt = currentSwiftDate();
  manifest.selectedNoteID = noteID;
  writeNoteManifest(projectID, manifest);
  const detail = loadNote(projectID, noteID);
  scheduleRemoteAccessBroadcast();
  return detail;
}

function saveProjectNote(projectID: string, noteID: string, markdown: string): NoteDetail {
  const manifest = readNoteManifest(projectID);
  const note = (manifest.notes ?? []).find((entry) => entry.id === noteID);
  if (!note) throw new Error("Note was not found.");
  const now = currentSwiftDate();
  note.updatedAt = now;
  const fileName = typeof note.fileName === "string" ? note.fileName : `${noteID}.md`;
  const filePath = path.join(noteDirectoryPath(projectID), fileName);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const nextMarkdown = markdown.replace(/\r\n/g, "\n");
  const previousMarkdown = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : "";
  if (noteHistoryContentKey(previousMarkdown) !== noteHistoryContentKey(nextMarkdown)) {
    snapshotProjectNote(projectID, noteID, note, previousMarkdown);
  }
  applyProjectNoteMetadataFromMarkdown(note, projectID, nextMarkdown);
  manifest.selectedNoteID = noteID;
  writeNoteManifest(projectID, manifest);
  fs.writeFileSync(filePath, nextMarkdown, "utf8");
  scheduleRemoteAccessBroadcast();
  // Keep the renderer in step with writes that do not come from the editor
  // (AI note edits, knowledge applies) and ship the change to paired Macs.
  emitProjectNoteChanged(projectID, noteID, normalizeTitle(note.title, "Untitled note"), nextMarkdown);
  scheduleMacSyncSoon();
  const metadata = noteMetadataFromRecord(note, loadProjects(), projectID, nextMarkdown);
  return {
    id: noteID,
    title: normalizeTitle(note.title, "Untitled note"),
    markdown: nextMarkdown,
    path: filePath,
    area: metadata.area,
    tags: metadata.tags
  };
}

type ReferenceNoteTarget =
  | { kind: "project"; projectID: string; noteID: string; title: string }
  | { kind: "thread"; threadID: string; noteID: string; title: string };

function normalizeReferenceNoteTitle(value?: unknown) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function canonicalReferenceNoteCandidates(primaryTitle: string) {
  return [
    primaryTitle,
    "Reference",
    "References",
    "Notes"
  ]
    .map((title) => normalizeTitle(title, "Reference"))
    .filter((title, index, titles) => titles.findIndex((candidate) => normalizeReferenceNoteTitle(candidate) === normalizeReferenceNoteTitle(title)) === index);
}

function findProjectNoteByTitle(projectID: string, titles: string[]) {
  const wanted = new Set(titles.map(normalizeReferenceNoteTitle).filter(Boolean));
  const manifest = readNoteManifest(projectID);
  return (manifest.notes ?? []).find((note) =>
    note.isArchived !== true
    && typeof note.id === "string"
    && wanted.has(normalizeReferenceNoteTitle(note.title))
  );
}

function resolveCanonicalReferenceNote(projectID: string, requestedTitle?: string): ReferenceNoteTarget {
  const loadedProjects = loadProjects();
  const project = projectListForNote(loadedProjects, projectID);
  const canonicalTitle = normalizeTitle(requestedTitle, project?.title || "Reference");
  const existing = findProjectNoteByTitle(projectID, canonicalReferenceNoteCandidates(canonicalTitle));
  if (existing?.id) {
    return {
      kind: "project",
      projectID: projectID.toUpperCase(),
      noteID: String(existing.id),
      title: normalizeTitle(existing.title, canonicalTitle)
    };
  }
  const created = createProjectNote(projectID);
  const renamed = renameProjectNote(projectID, created.note.id, canonicalTitle);
  return {
    kind: "project",
    projectID: projectID.toUpperCase(),
    noteID: created.note.id,
    title: renamed.title
  };
}

function findThreadNoteByTitle(threadID: string, titles: string[]) {
  const wanted = new Set(titles.map(normalizeReferenceNoteTitle).filter(Boolean));
  const manifest = readThreadNoteManifest(threadID);
  return (manifest.notes ?? []).find((note) =>
    note.isArchived !== true
    && typeof note.id === "string"
    && wanted.has(normalizeReferenceNoteTitle(note.title))
  );
}

function resolveCanonicalThreadReferenceNote(threadID: string, requestedTitle?: string): ReferenceNoteTarget {
  const canonicalTitle = normalizeThreadNoteTitle(requestedTitle || "Reference");
  const existing = findThreadNoteByTitle(threadID, canonicalReferenceNoteCandidates(canonicalTitle));
  if (existing?.id) {
    return {
      kind: "thread",
      threadID,
      noteID: String(existing.id),
      title: normalizeThreadNoteTitle(existing.title)
    };
  }
  const workspace = createThreadNote(threadID, canonicalTitle);
  const noteID = workspace.selectedNoteID ?? workspace.selectedNote?.id ?? "";
  if (!noteID) throw new Error("I couldn't create the thread reference note.");
  return { kind: "thread", threadID, noteID, title: canonicalTitle };
}

function referenceNoteItemID(target: ReferenceNoteTarget) {
  return target.kind === "project"
    ? knowledgeItemID({ ownerKind: "project", ownerId: target.projectID, noteId: target.noteID }, "project_note")
    : knowledgeItemID({ ownerKind: "thread", ownerId: target.threadID, noteId: target.noteID }, "thread_note");
}

function referenceLineKey(line: string) {
  return line
    .replace(/^\s*[-*]\s+/, "")
    .replace(/^\s*\d+[.)]\s+/, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function referenceMarkdownLine(line: string) {
  const trimmed = line.trim();
  if (!trimmed) return "";
  if (/^(#{1,6}\s+|[-*]\s+|\d+[.)]\s+|>\s+|\|)/.test(trimmed)) return trimmed;
  return `- ${trimmed}`;
}

function referencePayloadLines(payload: JsonObject) {
  const title = cleanDailyText(payload.title ?? payload.label ?? payload.name);
  const text = cleanDailyText(payload.text ?? payload.content ?? payload.note ?? payload.value);
  const details = cleanDailyText(payload.detailsMarkdown ?? payload.details ?? payload.description);
  const rawLines = [
    ...(details ? details.split("\n") : []),
    ...(!details && text ? text.split("\n") : []),
    ...(!details && !text && title ? [title] : [])
  ];
  const seen = new Set<string>();
  return rawLines
    .map(referenceMarkdownLine)
    .filter((line) => {
      const key = referenceLineKey(line);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function referenceSectionFromPayload(payload: JsonObject) {
  const explicit = normalizeDailySection(payload.section ?? payload.topic ?? payload.grouping ?? payload.heading);
  if (explicit) return explicit;
  const title = normalizeDailySection(payload.title ?? payload.label ?? payload.name);
  return title || "Reference";
}

function appendReferenceLinesToMarkdown(markdown: string, section: string, lines: string[]) {
  const currentSection = markdownSection(markdown, section);
  const existing = new Set(
    currentSection
      .split("\n")
      .map(referenceLineKey)
      .filter(Boolean)
  );
  const additions = lines.filter((line) => {
    const key = referenceLineKey(line);
    return key && !existing.has(key);
  });
  if (!additions.length) {
    return String(markdown ?? "").replace(/\r\n/g, "\n");
  }
  const nextSection = [currentSection.trim(), additions.join("\n")]
    .filter(Boolean)
    .join("\n");
  return replaceMarkdownSection(markdown, section, nextSection);
}

function referenceTargetFromPayload(payload: JsonObject): ReferenceNoteTarget {
  const parsedItemID = typeof payload.itemID === "string" ? parseKnowledgeItemID(payload.itemID) : null;
  if (parsedItemID?.target?.ownerKind === "project") {
    const item = readKnowledgeItem(payload.itemID as string);
    return {
      kind: "project",
      projectID: parsedItemID.target.ownerId.toUpperCase(),
      noteID: parsedItemID.target.noteId,
      title: item.title
    };
  }
  if (parsedItemID?.target?.ownerKind === "thread") {
    const item = readKnowledgeItem(payload.itemID as string);
    return {
      kind: "thread",
      threadID: parsedItemID.target.ownerId,
      noteID: parsedItemID.target.noteId,
      title: item.title
    };
  }

  const listResolution = resolvePlannerListFromDailyInput(payload);
  if ((listResolution.status === "not_found" || listResolution.status === "ambiguous")
    && !cleanDailyText(payload.projectID) && !cleanDailyText(payload.folderID)) {
    assertPlannerListResolved(listResolution);
  }
  const list = listResolution.status === "ok" ? listResolution.list : undefined;
  const projectID = cleanDailyText(payload.projectID)
    || cleanDailyText(payload.listProjectID)
    || (list ? list.id : "");
  if (projectID) {
    const loadedProjects = loadProjects();
    const project = projectListForNote(loadedProjects, projectID);
    const requestedTitle = cleanDailyText(payload.noteTitle ?? payload.referenceNoteTitle ?? project?.title);
    return resolveCanonicalReferenceNote(projectID, requestedTitle);
  }

  const threadID = cleanDailyText(payload.threadID ?? payload.conversationID ?? payload.sessionID);
  if (threadID) {
    return resolveCanonicalThreadReferenceNote(threadID, cleanDailyText(payload.noteTitle ?? payload.referenceNoteTitle ?? payload.threadTitle));
  }

  throw new Error("Which List or note should I save that reference under? Please name an @List or provide a note.");
}

function resolveExistingReferenceTargetFromPayload(payload: JsonObject): ReferenceNoteTarget | null {
  const parsedItemID = typeof payload.itemID === "string" ? parseKnowledgeItemID(payload.itemID) : null;
  if (parsedItemID?.target?.ownerKind === "project") {
    const item = readKnowledgeItem(payload.itemID as string);
    return {
      kind: "project",
      projectID: parsedItemID.target.ownerId.toUpperCase(),
      noteID: parsedItemID.target.noteId,
      title: item.title
    };
  }
  if (parsedItemID?.target?.ownerKind === "thread") {
    const item = readKnowledgeItem(payload.itemID as string);
    return {
      kind: "thread",
      threadID: parsedItemID.target.ownerId,
      noteID: parsedItemID.target.noteId,
      title: item.title
    };
  }

  const listResolution = resolvePlannerListFromDailyInput(payload);
  if ((listResolution.status === "not_found" || listResolution.status === "ambiguous")
    && !cleanDailyText(payload.projectID) && !cleanDailyText(payload.folderID)) {
    assertPlannerListResolved(listResolution);
  }
  const list = listResolution.status === "ok" ? listResolution.list : undefined;
  const projectID = cleanDailyText(payload.projectID)
    || cleanDailyText(payload.listProjectID)
    || (list ? list.id : "");
  if (projectID) {
    const loadedProjects = loadProjects();
    const project = projectListForNote(loadedProjects, projectID);
    const requestedTitle = cleanDailyText(payload.noteTitle ?? payload.referenceNoteTitle ?? project?.title);
    const canonicalTitle = normalizeTitle(requestedTitle, project?.title || "Reference");
    const existing = findProjectNoteByTitle(projectID, canonicalReferenceNoteCandidates(canonicalTitle));
    if (!existing?.id) return null;
    return {
      kind: "project",
      projectID: projectID.toUpperCase(),
      noteID: String(existing.id),
      title: normalizeTitle(existing.title, canonicalTitle)
    };
  }

  const threadID = cleanDailyText(payload.threadID ?? payload.conversationID ?? payload.sessionID);
  if (threadID) {
    const canonicalTitle = normalizeThreadNoteTitle(cleanDailyText(payload.noteTitle ?? payload.referenceNoteTitle ?? payload.threadTitle) || "Reference");
    const existing = findThreadNoteByTitle(threadID, canonicalReferenceNoteCandidates(canonicalTitle));
    return existing?.id
      ? { kind: "thread", threadID, noteID: String(existing.id), title: normalizeThreadNoteTitle(existing.title) }
      : null;
  }

  throw new Error("Which List or note should I save that reference under? Please name an existing @List or note.");
}

function referenceCreatePreviewFromPayload(payload: JsonObject, lines: string[]): KnowledgePreview | undefined {
  const listResolution = resolvePlannerListFromDailyInput(payload);
  if ((listResolution.status === "not_found" || listResolution.status === "ambiguous")
    && !cleanDailyText(payload.projectID) && !cleanDailyText(payload.folderID)) {
    assertPlannerListResolved(listResolution);
  }
  const list = listResolution.status === "ok" ? listResolution.list : undefined;
  const projectID = cleanDailyText(payload.projectID)
    || cleanDailyText(payload.listProjectID)
    || (list && list.kind !== "folder" ? list.id : "");
  const threadID = cleanDailyText(payload.threadID ?? payload.conversationID ?? payload.sessionID);
  const section = referenceSectionFromPayload(payload);
  const sectionMarkdown = appendReferenceLinesToMarkdown("", section, lines);
  if (projectID) {
    const loadedProjects = loadProjects();
    const project = projectListForNote(loadedProjects, projectID);
    const title = normalizeTitle(
      payload.noteTitle
        ?? payload.referenceNoteTitle
        ?? payload.title
        ?? payload.topic
        ?? payload.label
        ?? project?.title,
      project?.title || "Reference"
    );
    return { kind: "reference_note_create", ownerKind: "project", ownerId: projectID.toUpperCase(), title, markdown: sectionMarkdown };
  }
  if (threadID) {
    const title = normalizeThreadNoteTitle(cleanDailyText(payload.noteTitle ?? payload.referenceNoteTitle ?? payload.title ?? payload.topic ?? payload.label ?? payload.threadTitle) || "Reference");
    return { kind: "reference_note_create", ownerKind: "thread", ownerId: threadID, title, markdown: sectionMarkdown };
  }
  return undefined;
}

function loadThreadReferenceNote(threadID: string, noteID: string) {
  const workspace = loadThreadNoteWorkspace(threadID);
  if (workspace.selectedNote?.id === noteID) {
    return workspace.selectedNote;
  }
  const manifest = readThreadNoteManifest(threadID);
  const note = (manifest.notes ?? []).find((entry) => entry.id === noteID);
  const fileName = typeof note?.fileName === "string" ? note.fileName : `${noteID}.md`;
  const filePath = path.join(threadNotesDirectory(threadID), fileName);
  return {
    id: noteID,
    title: normalizeThreadNoteTitle(note?.title),
    markdown: fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : ""
  };
}

function referencePreviewFromPayload(payload: JsonObject): KnowledgePreview | undefined {
  const lines = referencePayloadLines(payload);
  if (!lines.length) return undefined;
  const target = resolveExistingReferenceTargetFromPayload(payload);
  if (!target) return referenceCreatePreviewFromPayload(payload, lines);
  const itemID = referenceNoteItemID(target);
  const current = target.kind === "project"
    ? loadNote(target.projectID, target.noteID)
    : loadThreadReferenceNote(target.threadID, target.noteID);
  const section = referenceSectionFromPayload(payload);
  const previousMarkdown = String(current.markdown ?? "").replace(/\r\n/g, "\n");
  return {
    kind: "replace_markdown",
    itemID,
    markdown: appendReferenceLinesToMarkdown(previousMarkdown, section, lines),
    previousMarkdown,
    title: current.title
  };
}

function restoreProjectNoteHistory(projectID: string, noteID: string, historyID: string): NoteDetail {
  const manifest = readNoteManifest(projectID);
  const note = (manifest.notes ?? []).find((entry) => entry.id === noteID);
  if (!note) throw new Error("Note was not found.");
  const historyItem = listProjectNoteHistory(projectID, noteID).find((entry) => entry.id === historyID);
  if (!historyItem) throw new Error("Saved version was not found.");
  const fileName = typeof note.fileName === "string" ? note.fileName : `${noteID}.md`;
  const filePath = path.join(noteDirectoryPath(projectID), fileName);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const previousMarkdown = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : "";
  if (noteHistoryContentKey(previousMarkdown) !== noteHistoryContentKey(historyItem.markdown)) {
    snapshotProjectNote(projectID, noteID, note, previousMarkdown);
  }
  fs.writeFileSync(filePath, historyItem.markdown, "utf8");
  note.updatedAt = currentSwiftDate();
  applyProjectNoteMetadataFromMarkdown(note, projectID, historyItem.markdown);
  manifest.selectedNoteID = noteID;
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  const metadata = noteMetadataFromRecord(note, loadProjects(), projectID, historyItem.markdown);
  return {
    id: noteID,
    title: normalizeTitle(note.title, "Untitled note"),
    markdown: historyItem.markdown,
    path: filePath,
    area: metadata.area,
    tags: metadata.tags
  };
}

function archiveProjectNote(projectID: string, noteID: string): { projectID: string; archivedNoteID: string } {
  const manifest = readNoteManifest(projectID);
  const now = currentSwiftDate();
  let found = false;
  const notes = (manifest.notes ?? []).map((entry) => {
    if (entry.id !== noteID) return entry;
    found = true;
    return {
      ...entry,
      isArchived: true,
      archivedAt: now,
      autoDeleteAfter: entry.autoDeleteAfter ?? null,
      updatedAt: now
    };
  });
  if (!found) return { projectID: projectID.toUpperCase(), archivedNoteID: noteID };
  if (manifest.selectedNoteID === noteID) {
    const nextNote = notes.find((entry) => entry.isArchived !== true);
    manifest.selectedNoteID = nextNote ? String(nextNote.id ?? "") || undefined : undefined;
  }
  manifest.notes = notes;
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  return { projectID: projectID.toUpperCase(), archivedNoteID: noteID };
}

function restoreProjectNote(projectID: string, noteID: string): { projectID: string; restoredNoteID: string } {
  const manifest = readNoteManifest(projectID);
  const now = currentSwiftDate();
  let found = false;
  manifest.notes = (manifest.notes ?? []).map((entry) => {
    if (entry.id !== noteID) return entry;
    found = true;
    const restored = { ...entry, isArchived: false, updatedAt: now };
    delete (restored as JsonObject).archivedAt;
    delete (restored as JsonObject).autoDeleteAfter;
    return restored;
  });
  if (!found) return { projectID: projectID.toUpperCase(), restoredNoteID: noteID };
  manifest.selectedNoteID = noteID;
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  return { projectID: projectID.toUpperCase(), restoredNoteID: noteID };
}

function deleteProjectNotePermanently(projectID: string, noteID: string): { projectID: string; deletedNoteID: string } {
  const manifest = readNoteManifest(projectID);
  const target = (manifest.notes ?? []).find((entry) => entry.id === noteID);
  if (!target) return { projectID: projectID.toUpperCase(), deletedNoteID: noteID };
  const remaining = (manifest.notes ?? []).filter((entry) => entry.id !== noteID);
  const fileName = macSyncSafeNoteFileName(target.fileName, noteID);
  const filePath = path.join(noteDirectoryPath(projectID), fileName);
  try {
    if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  } catch {
    // Ignore filesystem errors — manifest update below is the source of truth.
  }
  try {
    fs.rmSync(path.join(noteDirectoryPath(projectID), `${fileName.replace(/\.md$/, "")}.assets`), { force: true, recursive: true });
  } catch {
    // The manifest update remains the source of truth; a later cleanup can retry.
  }
  if (manifest.selectedNoteID === noteID) {
    manifest.selectedNoteID = remaining[0] ? String(remaining[0].id ?? "") || undefined : undefined;
  }
  manifest.notes = remaining;
  writeNoteManifest(projectID, manifest);
  recordMacSyncTombstone("note", noteID, projectID.toUpperCase());
  scheduleRemoteAccessBroadcast();
  return { projectID: projectID.toUpperCase(), deletedNoteID: noteID };
}

function deleteProjectNote(projectID: string, noteID: string): { projectID: string; archivedNoteID: string } {
  return archiveProjectNote(projectID, noteID);
}

function projectIDsWithNoteManifests() {
  const { snapshot } = projectStoreSnapshot();
  return [...new Set((snapshot.projects ?? []).map((project) => String(project.id ?? "").toUpperCase()).filter(Boolean))];
}

function purgeExpiredArchivedProjectNotes(settings: Pick<SettingsSnapshot, "archiveAutoDeleteDays">) {
  const now = Date.now();
  for (const projectID of projectIDsWithNoteManifests()) {
    const manifest = readNoteManifest(projectID);
    let changed = false;
    const remaining: JsonObject[] = [];
    for (const entry of manifest.notes ?? []) {
      if (shouldAutoDeleteArchivedRecord(entry, settings, now)) {
        const noteID = String(entry.id ?? "").trim();
        const fileName = noteID ? macSyncSafeNoteFileName(entry.fileName, noteID) : "";
        if (fileName) {
          try { fs.unlinkSync(path.join(noteDirectoryPath(projectID), fileName)); } catch {}
          try { fs.rmSync(path.join(noteDirectoryPath(projectID), `${fileName.replace(/\.md$/, "")}.assets`), { force: true, recursive: true }); } catch {}
        }
        if (noteID) recordMacSyncTombstone("note", noteID, projectID.toUpperCase());
        changed = true;
        continue;
      }
      remaining.push(entry);
    }
    if (!changed) continue;
    if (!remaining.some((entry) => entry.id === manifest.selectedNoteID)) {
      const nextNote = remaining.find((entry) => entry.isArchived !== true);
      manifest.selectedNoteID = nextNote ? String(nextNote.id ?? "") || undefined : undefined;
    }
    manifest.notes = remaining;
    writeNoteManifest(projectID, manifest);
  }
}

function threadIDsWithNoteManifests() {
  const ids = new Set(loadSessionRegistry().sessions.map((session) => session.id).filter(Boolean));
  try {
    for (const entry of fs.readdirSync(conversationStoreRoot(), { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (fs.existsSync(threadNoteManifestPath(entry.name))) ids.add(entry.name);
    }
  } catch {}
  return [...ids];
}

function purgeExpiredArchivedThreadNotes(settings: Pick<SettingsSnapshot, "archiveAutoDeleteDays">) {
  const now = Date.now();
  for (const threadID of threadIDsWithNoteManifests()) {
    const manifestPath = threadNoteManifestPath(threadID);
    if (!fs.existsSync(manifestPath)) continue;
    const manifest = readThreadNoteManifest(threadID);
    let changed = false;
    const remaining: JsonObject[] = [];
    for (const note of manifest.notes ?? []) {
      if (shouldAutoDeleteArchivedRecord(note as JsonObject, settings, now)) {
        const fileName = typeof note.fileName === "string" ? note.fileName : "";
        if (fileName) {
          try { fs.unlinkSync(path.join(threadNotesDirectory(threadID), fileName)); } catch {}
        }
        changed = true;
        continue;
      }
      remaining.push(note as JsonObject);
    }
    if (!changed) continue;
    const selectedStillExists = remaining.some((note) => note.id === manifest.selectedNoteID);
    const nextSelectedID = selectedStillExists
      ? manifest.selectedNoteID
      : String(remaining.find((note) => note.isArchived !== true)?.id ?? "") || undefined;
    writeThreadNoteManifest(threadID, { ...manifest, selectedNoteID: nextSelectedID, notes: remaining });
  }
}

async function purgeExpiredArchivedThreads(settings: Pick<SettingsSnapshot, "archiveAutoDeleteDays">) {
  const now = Date.now();
  const expired = loadSessionRegistry().sessions.filter((session) => shouldAutoDeleteArchivedRecord(session, settings, now));
  for (const session of expired) {
    try {
      await deleteSessionPermanently(session.id);
    } catch (error) {
      bridgeDebugLog(`Archived thread auto-delete failed thread=${session.id}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
}

async function purgeExpiredArchivedItems(settings: Pick<SettingsSnapshot, "archiveAutoDeleteDays">) {
  purgeExpiredArchivedProjectNotes(settings);
  purgeExpiredArchivedThreadNotes(settings);
  await purgeExpiredArchivedThreads(settings);
}

function normalizedNoteFolderParentID(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function sameNoteFolderParent(left: unknown, right: unknown) {
  return (normalizedNoteFolderParentID(left) ?? "") === (normalizedNoteFolderParentID(right) ?? "");
}

function noteFolderDescendantIDs(folders: JsonObject[], folderID: string): Set<string> {
  const descendants = new Set<string>();
  const visit = (parentID: string) => {
    for (const folder of folders) {
      const id = String(folder.id ?? "");
      if (!id || descendants.has(id)) continue;
      if (normalizedNoteFolderParentID(folder.parentFolderID) === parentID) {
        descendants.add(id);
        visit(id);
      }
    }
  };
  visit(folderID);
  return descendants;
}

function noteFolderNameClash(folders: JsonObject[], input: { folderID?: string; parentFolderID: string | null; name: string }) {
  const name = input.name.toLowerCase();
  return folders.some((folder) => {
    const id = String(folder.id ?? "");
    if (input.folderID && id === input.folderID) return false;
    return sameNoteFolderParent(folder.parentFolderID, input.parentFolderID)
      && normalizeTitle(folder.name, "Folder").toLowerCase() === name;
  });
}

function noteFolderItemFromManifest(projectID: string, folder: JsonObject, folderCounts: Map<string, number>): NoteFolderItem {
  const id = String(folder.id ?? "");
  return {
    id,
    name: normalizeTitle(folder.name, "Folder"),
    projectID: projectID.toUpperCase(),
    parentFolderID: normalizedNoteFolderParentID(folder.parentFolderID),
    noteCount: folderCounts.get(id) ?? 0
  };
}

function noteFolderCounts(manifest: { notes?: JsonObject[] }): Map<string, number> {
  const counts = new Map<string, number>();
  for (const note of manifest.notes ?? []) {
    const folderID = typeof note.folderID === "string" ? note.folderID : null;
    if (folderID) counts.set(folderID, (counts.get(folderID) ?? 0) + 1);
  }
  return counts;
}

function createProjectNoteFolder(projectID: string, name: string, parentFolderID?: string | null): NoteFolderItem {
  const trimmed = name.trim();
  if (!trimmed) throw new Error("Enter a folder name.");
  const manifest = readNoteManifest(projectID);
  const folders = manifest.folders ?? [];
  const normalizedParentID = normalizedNoteFolderParentID(parentFolderID);
  if (normalizedParentID && !folders.some((folder) => String(folder.id ?? "") === normalizedParentID)) {
    throw new Error("Parent folder was not found.");
  }
  if (noteFolderNameClash(folders, { parentFolderID: normalizedParentID, name: trimmed })) {
    throw new Error("A folder with that name already exists here.");
  }
  const now = currentSwiftDate();
  const folder: JsonObject = {
    id: randomUUID().toLowerCase(),
    name: trimmed,
    parentFolderID: normalizedParentID,
    createdAt: now,
    updatedAt: now
  };
  manifest.folders = [...folders, folder];
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  return noteFolderItemFromManifest(projectID, folder, noteFolderCounts(manifest));
}

function renameProjectNoteFolder(projectID: string, folderID: string, name: string): NoteFolderItem {
  const trimmed = name.trim();
  if (!trimmed) throw new Error("Enter a folder name.");
  const manifest = readNoteManifest(projectID);
  const folders = manifest.folders ?? [];
  const folder = folders.find((entry) => String(entry.id ?? "") === folderID);
  if (!folder) throw new Error("Folder was not found.");
  if (noteFolderNameClash(folders, {
    folderID,
    parentFolderID: normalizedNoteFolderParentID(folder.parentFolderID),
    name: trimmed
  })) {
    throw new Error("A folder with that name already exists here.");
  }
  folder.name = trimmed;
  folder.updatedAt = currentSwiftDate();
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  return noteFolderItemFromManifest(projectID, folder, noteFolderCounts(manifest));
}

function deleteProjectNoteFolder(projectID: string, folderID: string): { projectID: string; deletedFolderID: string; deletedFolderIDs: string[] } {
  const manifest = readNoteManifest(projectID);
  const folders = manifest.folders ?? [];
  const deletedIDs = new Set([folderID, ...noteFolderDescendantIDs(folders, folderID)]);
  manifest.folders = folders.filter((entry) => !deletedIDs.has(String(entry.id ?? "")));
  // Detaching notes (rather than deleting them) keeps the notes themselves safe.
  for (const note of manifest.notes ?? []) {
    if (typeof note.folderID === "string" && deletedIDs.has(note.folderID)) note.folderID = null;
  }
  writeNoteManifest(projectID, manifest);
  for (const deletedID of deletedIDs) recordMacSyncTombstone("noteFolder", deletedID, projectID.toUpperCase());
  scheduleRemoteAccessBroadcast();
  return { projectID: projectID.toUpperCase(), deletedFolderID: folderID, deletedFolderIDs: [...deletedIDs] };
}

function moveProjectNoteFolder(projectID: string, folderID: string, parentFolderID: string | null): NoteFolderItem {
  const manifest = readNoteManifest(projectID);
  const folders = manifest.folders ?? [];
  const folder = folders.find((entry) => String(entry.id ?? "") === folderID);
  if (!folder) throw new Error("Folder was not found.");
  const normalizedParentID = normalizedNoteFolderParentID(parentFolderID);
  if (normalizedParentID === folderID) throw new Error("A folder cannot be moved inside itself.");
  const descendants = noteFolderDescendantIDs(folders, folderID);
  if (normalizedParentID && descendants.has(normalizedParentID)) {
    throw new Error("A folder cannot be moved inside one of its subfolders.");
  }
  if (normalizedParentID && !folders.some((entry) => String(entry.id ?? "") === normalizedParentID)) {
    throw new Error("Parent folder was not found.");
  }
  if (noteFolderNameClash(folders, {
    folderID,
    parentFolderID: normalizedParentID,
    name: normalizeTitle(folder.name, "Folder")
  })) {
    throw new Error("A folder with that name already exists there.");
  }
  folder.parentFolderID = normalizedParentID;
  folder.updatedAt = currentSwiftDate();
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  return noteFolderItemFromManifest(projectID, folder, noteFolderCounts(manifest));
}

function moveProjectNoteToFolder(projectID: string, noteID: string, folderID: string | null): { projectID: string; noteID: string; folderID: string | null } {
  const manifest = readNoteManifest(projectID);
  const note = (manifest.notes ?? []).find((entry) => String(entry.id ?? "") === noteID);
  if (!note) throw new Error("Note was not found.");
  if (folderID && !(manifest.folders ?? []).some((entry) => String(entry.id ?? "") === folderID)) {
    throw new Error("Folder was not found.");
  }
  note.folderID = folderID;
  note.updatedAt = currentSwiftDate();
  writeNoteManifest(projectID, manifest);
  scheduleRemoteAccessBroadcast();
  return { projectID: projectID.toUpperCase(), noteID, folderID };
}

function moveProjectNoteToProject(sourceProjectID: string, noteID: string, destinationProjectID: string) {
  const sourceID = sourceProjectID.trim().toUpperCase();
  const destinationID = destinationProjectID.trim().toUpperCase();
  if (!sourceID || !destinationID) throw new Error("Choose a destination List.");
  if (sourceID === destinationID) throw new Error("The note is already in that List.");

  const loadedProjects = loadProjects();
  const destinationProject = projectListForNote(loadedProjects, destinationID);
  if (!destinationProject || destinationProject.kind === "folder") {
    throw new Error("The destination List was not found.");
  }

  const sourceManifest = readNoteManifest(sourceID);
  const destinationManifest = readNoteManifest(destinationID);
  const sourceNotes = sourceManifest.notes ?? [];
  const note = sourceNotes.find((entry) => String(entry.id ?? "") === noteID);
  if (!note) throw new Error("Note was not found.");
  if ((destinationManifest.notes ?? []).some((entry) => String(entry.id ?? "") === noteID)) {
    throw new Error("A note with this ID already exists in the destination List.");
  }

  const fileName = macSyncSafeNoteFileName(note.fileName, noteID);
  const sourceFilePath = path.join(noteDirectoryPath(sourceID), fileName);
  const destinationFilePath = path.join(noteDirectoryPath(destinationID), fileName);
  const assetsDirectoryName = `${fileName.replace(/\.md$/, "")}.assets`;
  const sourceAssetsPath = path.join(noteDirectoryPath(sourceID), assetsDirectoryName);
  const destinationAssetsPath = path.join(noteDirectoryPath(destinationID), assetsDirectoryName);
  const sourceHistoryPath = projectNoteRecoveryDirectoryPath(sourceID, noteID);
  const destinationHistoryPath = projectNoteRecoveryDirectoryPath(destinationID, noteID);
  const copiedPaths: string[] = [];

  const copyMovePath = (sourcePath: string, destinationPath: string) => {
    if (!fs.existsSync(sourcePath)) return;
    if (fs.existsSync(destinationPath)) {
      throw new Error("The destination already contains files for this note.");
    }
    fs.mkdirSync(path.dirname(destinationPath), { recursive: true });
    const sourceStat = fs.statSync(sourcePath);
    if (sourceStat.isDirectory()) {
      fs.cpSync(sourcePath, destinationPath, { recursive: true, force: false, errorOnExist: true });
    } else {
      fs.copyFileSync(sourcePath, destinationPath, fs.constants.COPYFILE_EXCL);
    }
    copiedPaths.push(destinationPath);
  };
  const removeCopiedPaths = () => {
    for (const copiedPath of [...copiedPaths].reverse()) {
      try { fs.rmSync(copiedPath, { recursive: true, force: true }); } catch {}
    }
  };

  const now = currentSwiftDate();
  const movedNote: JsonObject = {
    ...note,
    folderID: null,
    order: (destinationManifest.notes ?? []).length,
    updatedAt: now
  };
  const remainingSourceNotes = sourceNotes.filter((entry) => String(entry.id ?? "") !== noteID);
  const nextSourceSelectedID = sourceManifest.selectedNoteID === noteID
    ? String(remainingSourceNotes.find((entry) => entry.isArchived !== true)?.id ?? remainingSourceNotes[0]?.id ?? "") || undefined
    : sourceManifest.selectedNoteID;
  const nextSourceManifest = {
    ...sourceManifest,
    selectedNoteID: nextSourceSelectedID,
    notes: remainingSourceNotes
  };
  const nextDestinationManifest = {
    ...destinationManifest,
    selectedNoteID: noteID,
    notes: [...(destinationManifest.notes ?? []), movedNote]
  };

  try {
    copyMovePath(sourceFilePath, destinationFilePath);
    copyMovePath(sourceAssetsPath, destinationAssetsPath);
    copyMovePath(sourceHistoryPath, destinationHistoryPath);
    if (fs.existsSync(destinationHistoryPath)) {
      const indexPath = path.join(destinationHistoryPath, "index.json");
      const entries = readJSON<JsonObject[]>(indexPath, []);
      if (entries.length) {
        writeJSON(indexPath, entries.map((entry) => ({ ...entry, ownerID: destinationID })));
      }
    }
    writeNoteManifest(destinationID, nextDestinationManifest);
    writeNoteManifest(sourceID, nextSourceManifest);
  } catch (error) {
    try { writeNoteManifest(sourceID, sourceManifest); } catch {}
    try { writeNoteManifest(destinationID, destinationManifest); } catch {}
    removeCopiedPaths();
    throw error;
  }

  for (const sourcePath of [sourceFilePath, sourceAssetsPath, sourceHistoryPath]) {
    try { fs.rmSync(sourcePath, { recursive: true, force: true }); } catch {}
  }
  recordMacSyncTombstone("note", noteID, sourceID);
  scheduleRemoteAccessBroadcast();
  scheduleMacSyncSoon();

  const markdown = fs.existsSync(destinationFilePath)
    ? fs.readFileSync(destinationFilePath, "utf8").replace(/\r\n/g, "\n")
    : "";
  const metadata = noteMetadataFromRecord(movedNote, loadedProjects, destinationID, markdown);
  const noteItem: NoteItem = {
    id: noteID,
    title: normalizeTitle(movedNote.title, "Untitled note"),
    subtitle: noteSubtitle(Date.now()),
    projectID: destinationID,
    projectName: destinationProject.title,
    folderID: null,
    area: metadata.area,
    tags: metadata.tags,
    updatedAt: Date.now(),
    isArchived: movedNote.isArchived === true,
    archivedAt: storedArchiveDateToMs(movedNote.archivedAt),
    autoDeleteAfter: storedArchiveDateToMs(movedNote.autoDeleteAfter) ?? null,
    active: true
  };
  const detail: NoteDetail = {
    id: noteID,
    title: noteItem.title,
    markdown,
    path: destinationFilePath,
    area: metadata.area,
    tags: metadata.tags
  };
  emitProjectNoteChanged(destinationID, noteID, noteItem.title, markdown);
  return {
    sourceProjectID: sourceID,
    destinationProjectID: destinationID,
    note: noteItem,
    detail
  };
}

function normalizeNoteLinkTarget(target: unknown): NoteLinkTarget | null {
  if (!target || typeof target !== "object") return null;
  const raw = target as Record<string, unknown>;
  const ownerKind = raw.ownerKind === "project" || raw.ownerKind === "thread" || raw.ownerKind === "planner"
    ? raw.ownerKind
    : undefined;
  const ownerId = typeof raw.ownerId === "string" ? raw.ownerId.trim() : "";
  const noteId = typeof raw.noteId === "string" ? raw.noteId.trim() : "";
  if (!ownerKind || !ownerId || !noteId) return null;
  return { ownerKind, ownerId, noteId };
}

function noteLinkKey(target: NoteLinkTarget) {
  return `${target.ownerKind}:${target.ownerId.toLowerCase()}:${target.noteId.toLowerCase()}`;
}

function parseInternalNoteHref(href: string): NoteLinkTarget | null {
  try {
    const parsed = new URL(href.replace(/&amp;/g, "&"));
    if (parsed.protocol !== "oa-note:" || parsed.hostname !== "open") return null;
    const ownerKind = parsed.searchParams.get("ownerKind");
    const ownerId = parsed.searchParams.get("ownerId")?.trim() ?? "";
    const noteId = parsed.searchParams.get("noteId")?.trim() ?? "";
    if ((ownerKind !== "project" && ownerKind !== "thread" && ownerKind !== "planner") || !ownerId || !noteId) return null;
    return { ownerKind, ownerId, noteId };
  } catch {
    return null;
  }
}

function extractInternalNoteLinks(markdown: string): NoteLinkTarget[] {
  const links: NoteLinkTarget[] = [];
  const matcher = /oa-note:\/\/open\?[^)\s>"']+/gi;
  for (const match of markdown.matchAll(matcher)) {
    const parsed = parseInternalNoteHref(match[0]);
    if (parsed) links.push(parsed);
  }
  return links;
}

function safeMermaidLabel(value: string) {
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, " ").slice(0, 90);
}

function relationForRecord(record: StoredNoteLinkRecord | undefined, target: NoteLinkTarget, occurrenceCount: number): NoteLinkRelation {
  return {
    ownerKind: target.ownerKind,
    ownerId: target.ownerId,
    noteId: target.noteId,
    title: record?.title ?? "Missing note",
    sourceLabel: record?.sourceLabel ?? "Not found",
    occurrenceCount,
    isMissing: !record
  };
}

function scanStoredNoteLinkRecords(currentTarget: NoteLinkTarget, currentMarkdown?: string): StoredNoteLinkRecord[] {
  const records: StoredNoteLinkRecord[] = [];
  const currentKey = noteLinkKey(currentTarget);
  const projects = loadProjects();

  const addRecord = (record: StoredNoteLinkRecord) => {
    records.push(record.key === currentKey && typeof currentMarkdown === "string"
      ? { ...record, markdown: currentMarkdown.replace(/\r\n/g, "\n") }
      : record);
  };

  const projectNotesRoot = path.join(projectStoreRoot(), "ProjectNotes");
  if (fs.existsSync(projectNotesRoot)) {
    for (const projectDir of fs.readdirSync(projectNotesRoot)) {
      const ownerId = projectDir.toUpperCase();
      if (projectNotesHiddenForList(projects, ownerId)) continue;
      const sourceLabel = projects.projectNameByID.get(ownerId) ?? projects.projectNameByID.get(projectDir) ?? "Project notes";
      const manifestPath = path.join(projectNotesRoot, projectDir, "notes", "manifest.json");
      const manifest = readJSON<{ notes?: JsonObject[] }>(manifestPath, {});
      for (const note of manifest.notes ?? []) {
        const noteId = String(note.id ?? "");
        if (!noteId) continue;
        const filePath = projectNoteMarkdownPath(ownerId, note, noteId);
        const markdown = fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : "";
        const metadata = noteMetadataFromRecord(note, projects, ownerId, markdown);
        addRecord({
          ownerKind: "project",
          ownerId,
          noteId,
          key: noteLinkKey({ ownerKind: "project", ownerId, noteId }),
          title: normalizeTitle(note.title, "Untitled note"),
          sourceLabel,
          markdown,
          metadata
        });
      }
    }
  }

  const conversationsRoot = conversationStoreRoot();
  if (fs.existsSync(conversationsRoot)) {
    for (const threadDir of fs.readdirSync(conversationsRoot)) {
      const manifest = readThreadNoteManifest(threadDir);
      if (!(manifest.notes ?? []).length) continue;
      const sourceLabel = projects.threadTitles.get(threadDir) ?? "Thread notes";
      const notesDir = threadNotesDirectory(threadDir);
      for (const note of manifest.notes ?? []) {
        const noteId = String(note.id ?? "");
        if (!noteId || !note.fileName) continue;
        const fileName = String(note.fileName);
        const filePath = path.join(notesDir, fileName);
        addRecord({
          ownerKind: "thread",
          ownerId: threadDir,
          noteId,
          key: noteLinkKey({ ownerKind: "thread", ownerId: threadDir, noteId }),
          title: normalizeThreadNoteTitle(note.title),
          sourceLabel,
          markdown: fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : ""
        });
      }
    }
  }

  for (const day of listPlannerDays(365, plannerDayID())) {
    const filePath = plannerDayPath(day.id);
    addRecord({
      ownerKind: "planner",
      ownerId: "global",
      noteId: day.id,
      key: noteLinkKey({ ownerKind: "planner", ownerId: "global", noteId: day.id }),
      title: day.title,
      sourceLabel: "Planner",
      markdown: fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8").replace(/\r\n/g, "\n") : ""
    });
  }

  return records;
}

function buildNoteLinksSnapshot(target: NoteLinkTarget, currentMarkdown?: string): NoteLinksSnapshot {
  const currentKey = noteLinkKey(target);
  const records = scanStoredNoteLinkRecords(target, currentMarkdown);
  const recordsByKey = new Map(records.map((record) => [record.key, record]));
  const recordsByStableID = new Map<string, StoredNoteLinkRecord | null>();
  for (const record of records) {
    const stableID = `${record.ownerKind}:${record.noteId.toLowerCase()}`;
    recordsByStableID.set(stableID, recordsByStableID.has(stableID) ? null : record);
  }
  const canonicalLinkTarget = (linkedTarget: NoteLinkTarget): NoteLinkTarget => {
    if (recordsByKey.has(noteLinkKey(linkedTarget))) return linkedTarget;
    const matchingRecord = recordsByStableID.get(`${linkedTarget.ownerKind}:${linkedTarget.noteId.toLowerCase()}`);
    return matchingRecord
      ? { ownerKind: matchingRecord.ownerKind, ownerId: matchingRecord.ownerId, noteId: matchingRecord.noteId }
      : linkedTarget;
  };
  const currentRecord = recordsByKey.get(currentKey) ?? {
    ...target,
    key: currentKey,
    title: "Current note",
    sourceLabel: "Current note",
    markdown: typeof currentMarkdown === "string" ? currentMarkdown.replace(/\r\n/g, "\n") : ""
  };

  const outgoingCounts = new Map<string, { target: NoteLinkTarget; count: number }>();
  for (const rawLink of extractInternalNoteLinks(currentRecord.markdown)) {
    const link = canonicalLinkTarget(rawLink);
    const key = noteLinkKey(link);
    const previous = outgoingCounts.get(key);
    outgoingCounts.set(key, { target: link, count: (previous?.count ?? 0) + 1 });
  }
  const outgoingLinks = [...outgoingCounts.values()]
    .map(({ target: linkedTarget, count }) => relationForRecord(recordsByKey.get(noteLinkKey(linkedTarget)), linkedTarget, count))
    .sort((a, b) => a.title.localeCompare(b.title));

  const backlinkCounts = new Map<string, { record: StoredNoteLinkRecord; count: number }>();
  for (const record of records) {
    if (record.key === currentKey) continue;
    const count = extractInternalNoteLinks(record.markdown)
      .map(canonicalLinkTarget)
      .filter((link) => noteLinkKey(link) === currentKey)
      .length;
    if (count > 0) backlinkCounts.set(record.key, { record, count });
  }
  const backlinks = [...backlinkCounts.values()]
    .map(({ record, count }) => relationForRecord(record, record, count))
    .sort((a, b) => a.title.localeCompare(b.title));

  const nodeRecords = new Map<string, StoredNoteLinkRecord | (NoteLinkRelation & { key: string })>();
  nodeRecords.set(currentKey, currentRecord);
  for (const relation of outgoingLinks) {
    const key = noteLinkKey(relation);
    nodeRecords.set(key, { ...relation, key });
  }
  for (const relation of backlinks) {
    const key = noteLinkKey(relation);
    nodeRecords.set(key, { ...relation, key });
  }

  const nodeIDByKey = new Map<string, string>();
  const nodes: NoteLinkGraphNode[] = [...nodeRecords.entries()].map(([key, record], index) => {
    const id = `note_${index}`;
    nodeIDByKey.set(key, id);
    return {
      id,
      ownerKind: record.ownerKind,
      ownerId: record.ownerId,
      noteId: record.noteId,
      title: record.title,
      sourceLabel: record.sourceLabel,
      isCurrent: key === currentKey,
      isMissing: "isMissing" in record ? record.isMissing : false
    };
  });

  const edges: NoteLinkGraphEdge[] = [
    ...outgoingLinks.map((link) => ({
      from: nodeIDByKey.get(currentKey) ?? "note_0",
      to: nodeIDByKey.get(noteLinkKey(link)) ?? "note_0",
      occurrenceCount: link.occurrenceCount
    })),
    ...backlinks.map((link) => ({
      from: nodeIDByKey.get(noteLinkKey(link)) ?? "note_0",
      to: nodeIDByKey.get(currentKey) ?? "note_0",
      occurrenceCount: link.occurrenceCount
    }))
  ];

  const mermaidLines = ["flowchart LR"];
  for (const node of nodes) {
    const label = node.isCurrent ? `${node.title} (current)` : node.title;
    mermaidLines.push(`  ${node.id}["${safeMermaidLabel(label)}"]`);
  }
  for (const edge of edges) {
    mermaidLines.push(`  ${edge.from} --> ${edge.to}`);
  }

  return {
    outgoingLinks,
    backlinks,
    graph: edges.length
      ? {
        nodeCount: nodes.length,
        edgeCount: edges.length,
        mermaidCode: mermaidLines.join("\n"),
        nodes,
        edges
      }
      : null
  };
}

function loadNoteLinks(target: unknown, currentMarkdown?: string): NoteLinksSnapshot {
  const normalizedTarget = normalizeNoteLinkTarget(target);
  if (!normalizedTarget) return { outgoingLinks: [], backlinks: [], graph: null };
  return buildNoteLinksSnapshot(normalizedTarget, currentMarkdown);
}

